export const HIP_AUDIT_ENTRIES={"ig26_band_hip_flexion":{"id":"ig26_band_hip_flexion","segment":"A","edits":{"en":"Supported Standing Band Hip Flexion","equipmentDetail":["Guma upevněná nízko za tělem a pevná opora ruky: zábradlí, stabilní židle nebo zeď. Smyčka či vhodná manžeta musí držet u kotníku; kotvu před cvičením zkontroluj.","A band secured low behind you and stable hand support: a rail, sturdy chair or wall. A loop or suitable cuff must stay at the ankle; check the anchor before starting."],"exe":["Pokrč pracovní koleno a přitáhni je před tělo proti odporu. Zastav před záklonem trupu a pomalu vrať nohu. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Bend the working knee and lift it forward against resistance. Stop before leaning back and lower slowly. One lift and return is one repetition for the working leg. Change sides after the set."],"pro":["Lehčí: slabší guma, nižší zdvih nebo nácvik bez gumy. Náročnější: o něco silnější guma při stále klidném trupu. Výšku přizpůsob vlastnímu ovládanému rozsahu a oporu ruky ponech.","Easier: a lighter band, lower lift or practice without the band. More demanding: a slightly stronger band while the torso stays still. Choose a height you control and retain hand support."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"secondaryRegions":["trunk"],"focus":["strength"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["guma"],["fixed_anchor"],["fixed_support","chair","zed"]],"priority":1,"aliases":["supported band hip flexion","přitahování kolena proti gumě","band march"]},"policy":{"id":"ig26_band_hip_flexion","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["guma"],["fixed_anchor"],["fixed_support","chair","zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig26_band_hip_flexion","atlasId":"ig26_band_hip_flexion","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"7438f2ba6c6b0de69a76ea8a2e6781fa646561ca2219627d967b68f40a0e744e","thumb":"/expansion-atlas/ig26_band_hip_flexion-original-256.webp","detail":"/expansion-atlas/ig26_band_hip_flexion-original-960.webp","inkThumb":"/expansion-atlas/ig26_band_hip_flexion-ink-256.webp","inkDetail":"/expansion-atlas/ig26_band_hip_flexion-ink-960.webp","fillThumb":"/expansion-atlas/ig26_band_hip_flexion-fill-256.webp","fillDetail":"/expansion-atlas/ig26_band_hip_flexion-fill-960.webp"},"sourceSha256":"7438f2ba6c6b0de69a76ea8a2e6781fa646561ca2219627d967b68f40a0e744e","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"376061c4a895a257":{"fields":{"id":"ig26_band_hip_flexion","cz":"Přitahování kolena ve stoji proti gumě","en":"Supported Standing Band Hip Flexion","pat":"ohyb","eq":["guma"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Zvedej koleno, trup nech klidný.","Lift the knee without moving the torso."],"startPosition":["Gumu ukotvi nízko za sebou a připoj ji kolem kotníku pracovní nohy. Ve stoji se lehce přidrž pevné opory.","Anchor a band low behind you and attach it around the working ankle. Stand tall with light hand support."],"execution":["Pokrč pracovní koleno a přitáhni je před tělo proti odporu. Zastav před záklonem trupu a pomalu vrať nohu. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Bend the working knee and lift it forward against resistance. Stop before leaning back and lower slowly. One lift and return is one repetition for the working leg. Change sides after the set."],"watchFor":["Nevytáčej pánev a nevyhazuj koleno švihem. Stojné chodidlo je celé opřené, koleno není násilně propnuté.","Avoid twisting the pelvis or swinging the knee upward. Ground the standing foot and keep its knee soft."]},"progression":["Lehčí: slabší guma, nižší zdvih nebo nácvik bez gumy. Náročnější: o něco silnější guma při stále klidném trupu. Výšku přizpůsob vlastnímu ovládanému rozsahu a oporu ruky ponech.","Easier: a lighter band, lower lift or practice without the band. More demanding: a slightly stronger band while the torso stays still. Choose a height you control and retain hand support."]}}},"ig29_standing_straight_leg_raise":{"id":"ig29_standing_straight_leg_raise","segment":"A","edits":{"exe":["Pomalu zvedni nataženou nohu před sebe jen tak vysoko, aby trup zůstal klidný. Krátce zastav a pomalu ji spusť. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Slowly raise the straight leg in front only as high as you can keep the torso still. Pause briefly and lower slowly. One lift and return is one repetition for the working leg. Change sides after the set."],"pro":["Lehčí: menší zdvih, opora ruky nebo mírně pokrčené pracovní koleno. Náročnější: pomalejší spouštění či krátká pauza bez záklonu. Vyšší zdvih není podmínkou postupu; opora ruky může zůstat.","Easier: a lower lift, hand support or a slightly bent working knee. More demanding: slower lowering or a brief pause without leaning back. Greater height is not required to progress; hand support may stay."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"secondaryRegions":["thighs","trunk"],"focus":["mobility"],"positions":["standing"],"supports":[],"equipmentRequirements":[["telo"]],"priority":1,"aliases":["standing straight leg raise","pomalé přednožování"]},"policy":{"id":"ig29_standing_straight_leg_raise","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ig29_standing_straight_leg_raise-5ee5cc6c9cb575eb.mp4"]},"art":{"appId":"ig29_standing_straight_leg_raise","atlasId":"ig29_standing_straight_leg_raise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"2f420ea5ab279df6bf64f95dcfeedffbfc5f46ec0d6d7319ebd665d463524d4f","thumb":"/expansion-atlas/ig29_standing_straight_leg_raise-original-256.webp","detail":"/expansion-atlas/ig29_standing_straight_leg_raise-original-960.webp","inkThumb":"/expansion-atlas/ig29_standing_straight_leg_raise-ink-256.webp","inkDetail":"/expansion-atlas/ig29_standing_straight_leg_raise-ink-960.webp","fillThumb":"/expansion-atlas/ig29_standing_straight_leg_raise-fill-256.webp","fillDetail":"/expansion-atlas/ig29_standing_straight_leg_raise-fill-960.webp"},"sourceSha256":"2f420ea5ab279df6bf64f95dcfeedffbfc5f46ec0d6d7319ebd665d463524d4f","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"c353f6f7cde1b6ed":{"fields":{"id":"ig29_standing_straight_leg_raise","cz":"Pomalé přednožování natažené nohy ve stoji","en":"Controlled Standing Straight-Leg Raise","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Zvedej nohu pomalu, trup nech vzpřímený.","Lift the leg slowly and keep the torso upright."],"startPosition":["Stůj vzpřímeně a podle potřeby se jednou rukou lehce přidrž pevné opory. Stojné chodidlo opři celou plochou, druhou nohu natáhni a špičku lehce přitáhni k holeni.","Stand upright, using light one-hand support if needed. Keep the standing foot flat; straighten the other leg and gently draw its toes toward the shin."],"execution":["Pomalu zvedni nataženou nohu před sebe jen tak vysoko, aby trup zůstal klidný. Krátce zastav a pomalu ji spusť. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Slowly raise the straight leg in front only as high as you can keep the torso still. Pause briefly and lower slowly. One lift and return is one repetition for the working leg. Change sides after the set."],"watchFor":["Nezakláněj se, nevyhazuj nohu švihem a stojné koleno nezamykej. Výška zdvihu není cíl sama o sobě; při pohybu pánve zmenši rozsah.","Avoid leaning back, swinging the leg or locking the standing knee. Height is not the goal by itself; reduce the range if the pelvis moves."]},"progression":["Lehčí: menší zdvih, opora ruky nebo mírně pokrčené pracovní koleno. Náročnější: pomalejší spouštění či krátká pauza bez záklonu. Vyšší zdvih není podmínkou postupu; opora ruky může zůstat.","Easier: a lower lift, hand support or a slightly bent working knee. More demanding: slower lowering or a brief pause without leaning back. Greater height is not required to progress; hand support may stay."]}}},"ex26_mob_pike_compression":{"id":"ex26_mob_pike_compression","segment":"A","edits":{"exe":["Zvedni patu natažené nohy jen kousek nad zem a pomalu ji polož. Pánev zůstává na zemi. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Lift the straight-leg heel just clear of the floor and lower slowly. Keep the pelvis grounded. One lift and return is one repetition for the working leg. Change sides after the set."],"wat":["Nezakláněj trup ani se neodrážej od země. Koleno nepokrčuj jen kvůli větší výšce; menší ovládaný zdvih stačí. Pokud potřebuješ lehčí variantu, mírné pokrčení zvol už před sérií.","Do not lean back or bounce off the floor. Do not bend the knee just to gain height; a small controlled lift is enough. If you need an easier version, choose a slight knee bend before the set."],"equipmentDetail":["Bez povinné pomůcky, vsedě na pevné podlaze; podložka je volitelná.","No required equipment, seated on a firm floor; a mat is optional."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"secondaryRegions":["thighs","trunk"],"focus":["mobility","strength"],"positions":["seated"],"supports":[],"equipmentRequirements":[["telo"]],"priority":1,"aliases":["seated single leg compression","aktivní komprese v sedu","zdvih natažené nohy v sedu"]},"policy":{"id":"ex26_mob_pike_compression","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_flexion","blockedMotionSources":["/exercise-motion/ex26_mob_pike_compression-bd0f435d5e3bf5db.mp4"]},"art":{"appId":"ex26_mob_pike_compression","atlasId":"ex26_mob_pike_compression","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"c19c500a3d76e913afa279fa2e5bce535a680f08a58784dc3da4e321eee9aa81","thumb":"/expansion-atlas/ex26_mob_pike_compression-original-256.webp","detail":"/expansion-atlas/ex26_mob_pike_compression-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_pike_compression-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_pike_compression-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_pike_compression-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_pike_compression-fill-960.webp"},"sourceSha256":"c19c500a3d76e913afa279fa2e5bce535a680f08a58784dc3da4e321eee9aa81","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"b0a58d2674cc5814":{"fields":{"id":"ex26_mob_pike_compression","cz":"Aktivní zdvih natažené nohy v sedu","en":"Seated Single-Leg Compression Lift","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Zvedni patu natažené nohy několik centimetrů a pomalu ji polož.","Lift the straight-leg heel a few centimetres and lower slowly, keeping the pelvis grounded."],"startPosition":["Sedni na zem, jednu nohu natáhni a druhé koleno přitáhni pažemi k trupu.","Sit on the floor with one leg straight, hugging the opposite bent knee toward the trunk."],"execution":["Zvedni patu natažené nohy jen kousek nad zem a pomalu ji polož. Pánev zůstává na zemi. Zdvih a návrat jsou jedno opakování na pracovní nohu. Po sérii vystřídej stranu.","Lift the straight-leg heel just clear of the floor and lower slowly. Keep the pelvis grounded. One lift and return is one repetition for the working leg. Change sides after the set."],"watchFor":["Nezakláněj trup ani se neodrážej od země. Koleno nepokrčuj jen kvůli větší výšce; menší ovládaný zdvih stačí. Pokud potřebuješ lehčí variantu, mírné pokrčení zvol už před sérií.","Do not lean back or bounce off the floor. Do not bend the knee just to gain height; a small controlled lift is enough. If you need an easier version, choose a slight knee bend before the set."]},"progression":["Lehčí: lehce pokrč pracující koleno. Těžší: krátce podrž patu ve vzduchu bez zaklonění.","Easier: soften the working knee. Harder: briefly hold the heel airborne without leaning back."]}}},"ig27_seated_leg_crossover":{"id":"ig27_seated_leg_crossover","segment":"A","edits":{"pro":["Lehčí: přenos přes čáru na zemi nebo mírně pokrčené koleno. Náročnější: krátká pauza nad nízkou překážkou při klidném trupu. Překážku není nutné zvyšovat.","Easier: cross a line on the floor or slightly bend the knee. More demanding: pause briefly above a low obstacle with a quiet torso. Raising the obstacle is not necessary."],"source":{"author":"Tanmay","document":"Seated straight-leg obstacle crossover — independent coaching variation","url":"https://gmb.io/l-sit/","scope":"Independent obstacle-crossing variation of a seated active straight-leg lift. The GMB reference supports the base seated leg lift, not this exact crossing variation or its benefits. Use a low soft obstacle; out and back counts as one repetition in this variation."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"secondaryRegions":["thighs","trunk"],"focus":["mobility","coordination"],"positions":["seated"],"supports":["hand_support"],"equipmentRequirements":[["towel","yoga_block"]],"priority":2,"aliases":["seated leg over block","hip flexor crossover","přenos nohy přes překážku v sedu"]},"policy":{"id":"ig27_seated_leg_crossover","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["towel","yoga_block"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_seated_leg_crossover","atlasId":"ig27_seated_leg_crossover","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"611328bf226c58a955911bf65c322d650697ef949ce32b98c1ec60bc68fadde4","thumb":"/expansion-atlas/ig27_seated_leg_crossover-original-256.webp","detail":"/expansion-atlas/ig27_seated_leg_crossover-original-960.webp","inkThumb":"/expansion-atlas/ig27_seated_leg_crossover-ink-256.webp","inkDetail":"/expansion-atlas/ig27_seated_leg_crossover-ink-960.webp","fillThumb":"/expansion-atlas/ig27_seated_leg_crossover-fill-256.webp","fillDetail":"/expansion-atlas/ig27_seated_leg_crossover-fill-960.webp"},"sourceSha256":"611328bf226c58a955911bf65c322d650697ef949ce32b98c1ec60bc68fadde4","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"ebccddc1d363ac96":{"fields":{"id":"ig27_seated_leg_crossover","cz":"Přenášení natažené nohy přes nízkou překážku v sedu","en":"Seated Straight-Leg Obstacle Crossover","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":20,"unilateral":true,"sideMode":"perSide","focus":["Zvedni nataženou nohu a přenes patu malým obloukem přes překážku.","Lift the straight leg and carry its heel over the obstacle in a small arc."],"startPosition":["Sedni na zem s jednou nohou nataženou, druhé koleno pokrč a chodidlo opři. Dlaně dej vedle boků. K natažené noze polož nízkou měkkou překážku, třeba složený ručník.","Sit on the floor with one leg straight and the other knee bent with its foot supported. Place the palms beside the hips. Set a low soft obstacle, such as a folded towel, beside the straight leg."],"execution":["Zvedni nataženou nohu a přenes patu malým obloukem přes překážku. Lehce ji polož a vrať stejnou cestou. Přenos tam a zpět je jedno opakování; pak vystřídej nohy.","Lift the straight leg and carry its heel over the obstacle in a small arc. Touch down lightly and return along the same path. Out and back counts as one repetition; then switch legs."],"watchFor":["Pánev zůstává na zemi a trup se nerozhoupává. Překážka nesmí nutit koleno do ohnutí ani nohu do prudkého švihu. Použij měkký předmět, ne těžkou činku.","Keep the pelvis grounded and the torso quiet. The obstacle must not force you to bend the knee or swing the leg sharply. Use a soft object rather than a heavy dumbbell."]},"progression":["Lehčí: přenos přes čáru na zemi nebo mírně pokrčené koleno. Náročnější: krátká pauza nad nízkou překážkou při klidném trupu. Překážku není nutné zvyšovat.","Easier: cross a line on the floor or slightly bend the knee. More demanding: pause briefly above a low obstacle with a quiet torso. Raising the obstacle is not necessary."]}}},"donkeykick":{"id":"donkeykick","segment":"B","edits":{"hd":null,"pos":["Opři dlaně pod ramena a kolena přibližně pod kyčle. Pracovní koleno nech pokrčené zhruba do pravého úhlu; chodidlo může zůstat lehce přitažené. Trup drž v pohodlné klidné poloze.","Place the hands under the shoulders and knees roughly under the hips. Keep the working knee bent about a right angle; the foot may stay gently flexed. Hold a comfortable, steady trunk position."],"exe":["Zvedni stehno dozadu z kyčle, koleno zůstává pokrčené. Krátce zastav a pomalu vrať koleno pod kyčel. Jeden zdvih a návrat jsou jedno opakování. Po sérii podle plánu vystřídej nohu.","Lift the thigh backward from the hip, keeping the knee bent. Pause briefly and slowly return the knee under the hip. One lift and return is one repetition. Change legs after the planned set."],"wat":["Výšku nezískávej prohnutím beder ani otočením pánve. Stačí rozsah, ve kterém trup zůstává klidný; netlač patu co nejvýš. Hlavu nech v prodloužení trupu a dýchej.","Do not gain height by arching the lower back or rotating the pelvis. Use a range that keeps the trunk steady; do not chase maximum heel height. Keep the head in line with the trunk and breathe."],"pro":["Lehčí: menší zdvih. Náročnější: pomalejší návrat nebo krátká pauza při stejném klidu trupu. Guma ani činka za kolenem nejsou součástí této základní varianty.","Easier: a smaller lift. More demanding: a slower return or brief pause with the same steady trunk. A band or dumbbell behind the knee is not part of this base version."],"foc":["Zvedej stehno z kyčle, pánev a trup nech klidné.","Lift the thigh from the hip while keeping the pelvis and trunk steady."],"equipmentDetail":["Bez povinné pomůcky. Podložka pod kolena a ruce je volitelná.","No required equipment. Padding under the knees and hands is optional."],"source":{"author":"American Council on Exercise","document":"Quadruped Bent-knee Hip Extensions","url":"https://www.acefitness.org/resources/everyone/exercise-library/270/quadruped-bent-knee-hip-extensions/","scope":"Technique reference for bent-knee hip extension on all fours. Independent wording; a gently flexed or comfortable foot is allowed rather than requiring the source’s pointed foot. The source’s knee-held dumbbell progression is not part of this bodyweight version."}},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs","trunk"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["quadruped"],"supports":["hand_support"],"equipmentRequirements":[["telo"]],"aliases":["donkey kick","quadruped bent knee hip extension","zanožení s pokrčeným kolenem","zanožování na čtyřech"]},"policy":{"id":"donkeykick","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_extension_isolation"},"art":{"appId":"donkeykick","atlasId":"donkeykick","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"61e9702362bff44aac7d8fa8ae640e9b1e7f84abe930f182f2b39226783abc20","thumb":"/unified-atlas/donkeykick-083e38d9584bd3ed-thumb.webp","detail":"/unified-atlas/donkeykick-f5a1ddc9a4264cb8-detail.webp","inkThumb":"/unified-atlas/donkeykick-acc414ed0f253d4c-inkThumb.webp","inkDetail":"/unified-atlas/donkeykick-fc7fbc59124c9f78-inkDetail.webp","fillThumb":"/unified-atlas/donkeykick-34c98c31b6f85bea-fillThumb.webp","fillDetail":"/unified-atlas/donkeykick-ba30acfd231523eb-fillDetail.webp"},"sourceSha256":"61e9702362bff44aac7d8fa8ae640e9b1e7f84abe930f182f2b39226783abc20","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"0459e5d7a0d6f058":{"fields":{"id":"donkeykick","cz":"Zanožování ve vzporu","en":"Donkey Kick","pat":"ohyb","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Zvedej stehno z kyčle, pánev a trup nech klidné.","Lift the thigh from the hip while keeping the pelvis and trunk steady."],"startPosition":["Opři dlaně pod ramena a kolena přibližně pod kyčle. Pracovní koleno nech pokrčené zhruba do pravého úhlu; chodidlo může zůstat lehce přitažené. Trup drž v pohodlné klidné poloze.","Place the hands under the shoulders and knees roughly under the hips. Keep the working knee bent about a right angle; the foot may stay gently flexed. Hold a comfortable, steady trunk position."],"execution":["Zvedni stehno dozadu z kyčle, koleno zůstává pokrčené. Krátce zastav a pomalu vrať koleno pod kyčel. Jeden zdvih a návrat jsou jedno opakování. Po sérii podle plánu vystřídej nohu.","Lift the thigh backward from the hip, keeping the knee bent. Pause briefly and slowly return the knee under the hip. One lift and return is one repetition. Change legs after the planned set."],"watchFor":["Výšku nezískávej prohnutím beder ani otočením pánve. Stačí rozsah, ve kterém trup zůstává klidný; netlač patu co nejvýš. Hlavu nech v prodloužení trupu a dýchej.","Do not gain height by arching the lower back or rotating the pelvis. Use a range that keeps the trunk steady; do not chase maximum heel height. Keep the head in line with the trunk and breathe."]},"progression":["Lehčí: menší zdvih. Náročnější: pomalejší návrat nebo krátká pauza při stejném klidu trupu. Guma ani činka za kolenem nejsou součástí této základní varianty.","Easier: a smaller lift. More demanding: a slower return or brief pause with the same steady trunk. A band or dumbbell behind the knee is not part of this base version."]}}},"ex26_cable_kickback":{"id":"ex26_cable_kickback","segment":"B","edits":{"ez":null,"pos":["Stůj čelem ke spodní kladce. Manžetu určenou pro kladku upevni těsně nad kotník a spoj s lankem. Přidrž se pevné části stroje nebo jiné pevné opory a lehce se předkloň z kyčlí. Pracovní koleno nech téměř natažené, stojné koleno měkké.","Face the low pulley. Secure a cable-compatible cuff just above the ankle and connect it to the cable. Hold a fixed part of the station or another stable support and hinge slightly at the hips. Keep the working knee nearly straight and the standing knee soft."],"exe":["Veď nohu krátce dozadu z kyčle bez změny pokrčení kolena a pomalu ji vrať. Pánev zůstává čelem ke kladce. Zanožení a návrat jsou jedno opakování na pracovní nohu; po sérii vystřídej stranu.","Move the leg a short distance backward from the hip without changing the knee bend, then return slowly. Keep the pelvis facing the pulley. One backward lift and return is one repetition for the working leg; change sides after the set."],"wat":["Výška nohy není cíl. Při záklonu nebo otáčení pánve zmenši rozsah či odpor. Nenech lanko tahat trup dopředu a závaží nepouštěj nárazem na doraz.","Leg height is not the goal. Reduce range or resistance if the back arches or pelvis turns. Do not let the cable pull the trunk forward or let the weight stack slam down."],"pro":["Lehčí: menší odpor nebo rozsah. Náročnější: krátká pauza či malá změna odporu, pokud zachováš stejné provedení. Nastavení kladky a manžety při porovnávání sérií ponech stejné.","Easier: less resistance or range. More demanding: a brief pause or small resistance change while keeping the same execution. Keep pulley and cuff settings consistent when comparing sets."],"equipmentDetail":["Spodní nebo výškově nastavitelná kladka nastavená nízko, kotníková manžeta určená ke kladce a pevná opora rukou. Opora může být součástí stanice. Zapisuj nastavenou zátěž dané kladky, ne součet za obě nohy.","A low pulley or height-adjustable pulley set low, a cable-compatible ankle cuff and fixed hand support. The station itself may provide the support. Record the selected load on that pulley, not a total for both legs."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]],"aliases":["cable kickback","zanožení na spodní kladce"]},"policy":{"id":"ex26_cable_kickback","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_cable_kickback","atlasId":"ex26_cable_kickback","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"821b8287129cc4a5ef64b717c7b5b930ad3e15f29df9bda4f183d5212757fb76","thumb":"/expansion-atlas/ex26_cable_kickback-original-256.webp","detail":"/expansion-atlas/ex26_cable_kickback-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_kickback-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_kickback-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_kickback-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_kickback-fill-960.webp"},"sourceSha256":"821b8287129cc4a5ef64b717c7b5b930ad3e15f29df9bda4f183d5212757fb76","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"2f3480f71d5056fd":{"fields":{"id":"ex26_cable_kickback","cz":"Zanožování na spodní kladce","en":"Standing Cable Hip Extension","pat":"ohyb","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Veď nohu krátce dozadu z kyčle.","Move the leg a short distance backward from the hip."],"startPosition":["Stůj čelem ke spodní kladce. Manžetu určenou pro kladku upevni těsně nad kotník a spoj s lankem. Přidrž se pevné části stroje nebo jiné pevné opory a lehce se předkloň z kyčlí. Pracovní koleno nech téměř natažené, stojné koleno měkké.","Face the low pulley. Secure a cable-compatible cuff just above the ankle and connect it to the cable. Hold a fixed part of the station or another stable support and hinge slightly at the hips. Keep the working knee nearly straight and the standing knee soft."],"execution":["Veď nohu krátce dozadu z kyčle bez změny pokrčení kolena a pomalu ji vrať. Pánev zůstává čelem ke kladce. Zanožení a návrat jsou jedno opakování na pracovní nohu; po sérii vystřídej stranu.","Move the leg a short distance backward from the hip without changing the knee bend, then return slowly. Keep the pelvis facing the pulley. One backward lift and return is one repetition for the working leg; change sides after the set."],"watchFor":["Výška nohy není cíl. Při záklonu nebo otáčení pánve zmenši rozsah či odpor. Nenech lanko tahat trup dopředu a závaží nepouštěj nárazem na doraz.","Leg height is not the goal. Reduce range or resistance if the back arches or pelvis turns. Do not let the cable pull the trunk forward or let the weight stack slam down."]},"progression":["Lehčí: menší odpor nebo rozsah. Náročnější: krátká pauza či malá změna odporu, pokud zachováš stejné provedení. Nastavení kladky a manžety při porovnávání sérií ponech stejné.","Easier: less resistance or range. More demanding: a brief pause or small resistance change while keeping the same execution. Keep pulley and cuff settings consistent when comparing sets."]}}},"ex26_machine_glute":{"id":"ex26_machine_glute","segment":"B","edits":{"pos":["Nastav odpor a opory klečícího stroje podle jeho návodu. Jedno koleno opři o spodní podložku, rukama se drž madel a chodidlo druhé nohy polož na tlačnou desku. Opory musí umožnit klidný trup bez natahování za madly.","Set the resistance and supports of the kneeling machine according to its instructions. Support one knee on the lower pad, hold the handles and place the other foot on the press plate. Adjust the supports so the torso stays steady without reaching for the handles."],"exe":["Tlač chodidlo dozadu po dráze stroje, přitom se napřimuje kyčel a postupně narovnává koleno. Zastav před prohnutím trupu a pomalu se vrať. Jeden tlak a návrat jsou jedno opakování na pracovní nohu; po sérii vystřídej stranu.","Press the foot backward along the machine path as the hip extends and the knee gradually straightens. Stop before arching the trunk and return slowly. One press and return is one repetition for the working leg; change sides after the set."],"wat":["Opěrné koleno nech na podložce a pánev neotáčej kvůli delšímu dosahu. Chodidlo udržuj na desce, koleno nenarážej do krajního propnutí a závaží vracej bez rány.","Keep the supporting knee on the pad and do not rotate the pelvis to reach farther. Keep the foot on the plate, avoid snapping the knee into its end range and return the weight without impact."],"pro":["Lehčí: menší odpor nebo rozsah v mezích nastavení stroje. Náročnější: krátká pauza nebo malý přírůstek odporu při stejných oporách a klidném trupu. Vyšší zátěž není povinný další krok.","Easier: less resistance or range within the machine settings. More demanding: a brief pause or small resistance increase with the same supports and a steady trunk. More load is not a required next step."],"foc":["Tlač chodidlo dozadu po dráze stroje, trup nech klidný.","Press the foot backward along the machine path while keeping the trunk steady."],"equipmentDetail":["Klečící stroj na zanožování s oporou kolena, madly a tlačnou deskou pro chodidlo. Běžný leg press, stroj na zakopávání ani stroj pro zanožení ve stoji tuto pomůcku nenahrazují. Zapisuj nastavenou zátěž a používej stejné nastavení stroje.","A kneeling glute press machine with knee support, handles and a foot press plate. A regular leg press, leg-curl machine or standing hip-extension machine is not the same setup. Record the selected load and use consistent machine settings."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["strength"],"priority":1,"positions":["kneeling"],"supports":["machine","hand_support"],"equipmentRequirements":[["kneeling_glute_press_machine"]],"aliases":["kneeling glute press","kneeling hip extension machine","klečící stroj na zanožování"]},"policy":{"id":"ex26_machine_glute","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["kneeling_glute_press_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_machine_glute","atlasId":"ex26_machine_glute","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e0a3195c9c399d98b81d44861b7d013f66f3d7989facd65bedb9831e2715609b","thumb":"/expansion-atlas/ex26_machine_glute-original-256.webp","detail":"/expansion-atlas/ex26_machine_glute-original-960.webp","inkThumb":"/expansion-atlas/ex26_machine_glute-ink-256.webp","inkDetail":"/expansion-atlas/ex26_machine_glute-ink-960.webp","fillThumb":"/expansion-atlas/ex26_machine_glute-fill-256.webp","fillDetail":"/expansion-atlas/ex26_machine_glute-fill-960.webp"},"sourceSha256":"e0a3195c9c399d98b81d44861b7d013f66f3d7989facd65bedb9831e2715609b","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"9185050c6f24b81b":{"fields":{"id":"ex26_machine_glute","cz":"Zanožování na klečícím stroji","en":"Kneeling Glute Press Machine","pat":"ohyb","eq":["stroj"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Tlač chodidlo dozadu po dráze stroje, trup nech klidný.","Press the foot backward along the machine path while keeping the trunk steady."],"startPosition":["Nastav odpor a opory klečícího stroje podle jeho návodu. Jedno koleno opři o spodní podložku, rukama se drž madel a chodidlo druhé nohy polož na tlačnou desku. Opory musí umožnit klidný trup bez natahování za madly.","Set the resistance and supports of the kneeling machine according to its instructions. Support one knee on the lower pad, hold the handles and place the other foot on the press plate. Adjust the supports so the torso stays steady without reaching for the handles."],"execution":["Tlač chodidlo dozadu po dráze stroje, přitom se napřimuje kyčel a postupně narovnává koleno. Zastav před prohnutím trupu a pomalu se vrať. Jeden tlak a návrat jsou jedno opakování na pracovní nohu; po sérii vystřídej stranu.","Press the foot backward along the machine path as the hip extends and the knee gradually straightens. Stop before arching the trunk and return slowly. One press and return is one repetition for the working leg; change sides after the set."],"watchFor":["Opěrné koleno nech na podložce a pánev neotáčej kvůli delšímu dosahu. Chodidlo udržuj na desce, koleno nenarážej do krajního propnutí a závaží vracej bez rány.","Keep the supporting knee on the pad and do not rotate the pelvis to reach farther. Keep the foot on the plate, avoid snapping the knee into its end range and return the weight without impact."]},"progression":["Lehčí: menší odpor nebo rozsah v mezích nastavení stroje. Náročnější: krátká pauza nebo malý přírůstek odporu při stejných oporách a klidném trupu. Vyšší zátěž není povinný další krok.","Easier: less resistance or range within the machine settings. More demanding: a brief pause or small resistance increase with the same supports and a steady trunk. More load is not a required next step."]}}},"clamshell":{"id":"clamshell","segment":"C","edits":{"eq":["telo"],"pos":["Lehni si na bok, podepři hlavu a pokrč obě kolena. Ramena a pánev srovnej nad sebe, chodidla nech u sebe. Začni bez gumy.","Lie on your side, support your head and bend both knees. Stack the shoulders and pelvis and keep the feet together. Start without a band."],"exe":["Pomalu otevři horní koleno, jen dokud se pánev nepřeklápí dozadu. Chodidla zůstávají v kontaktu. Vrať koleno dolů; otevření a návrat je jedno opakování horní nohy. Po sérii se otoč na druhý bok.","Slowly open the top knee only as far as the pelvis stays still. Keep the feet in contact. Lower the knee; one opening and return is one repetition of the top leg. Turn onto the other side after the set."],"pro":["Lehčí: menší otevření. Náročnější: pomalejší návrat nebo krátká pauza. Smyčka nad koleny je volitelná odporová úprava; poznamenej její použití a nepřeváděj barvu gumy na kilogramy.","Easier: open through a smaller range. More demanding: lower more slowly or pause briefly. A loop above the knees is an optional resisted modification; note its use and do not convert band colour to kilograms."],"source":{"author":"Royal Orthopaedic Hospital NHS Foundation Trust","document":"Exercises for Osteoarthritis of the Hip — Clam","url":"https://roh.nhs.uk/services-information/therapy/exercises-for-osteoarthritis-of-the-hip","scope":"Position and controlled knee opening with feet together only. Local repetition definition and optional resistance are general-library clarifications; the clinical indication, dose and outcomes are not transferred."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["side_lying"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"clamshell","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/clamshell-37855a9b92c1756a.mp4"]},"art":{"appId":"clamshell","atlasId":"clamshell","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"94cb7a9e302af64974e26df272bab56837a217a5917c6e9687c5b93b6c661388","thumb":"/unified-atlas/clamshell-b537f3b6d29629aa-thumb.webp","detail":"/unified-atlas/clamshell-6170f283aec43340-detail.webp","inkThumb":"/unified-atlas/clamshell-a3d4e4a74eeedf3a-inkThumb.webp","inkDetail":"/unified-atlas/clamshell-46f406b33b313443-inkDetail.webp","fillThumb":"/unified-atlas/clamshell-5aace7d9f1eeac3d-fillThumb.webp","fillDetail":"/unified-atlas/clamshell-02a4fee38e9ea183-fillDetail.webp"},"sourceSha256":"94cb7a9e302af64974e26df272bab56837a217a5917c6e9687c5b93b6c661388","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"97c05c37907f701c":{"fields":{"id":"clamshell","cz":"Škeble","en":"Clamshell","pat":"ohyb","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Pánev se neotáčí. Otevírá se jen koleno.","The pelvis never rolls. Only the knee opens."],"startPosition":["Lehni si na bok, podepři hlavu a pokrč obě kolena. Ramena a pánev srovnej nad sebe, chodidla nech u sebe. Začni bez gumy.","Lie on your side, support your head and bend both knees. Stack the shoulders and pelvis and keep the feet together. Start without a band."],"execution":["Pomalu otevři horní koleno, jen dokud se pánev nepřeklápí dozadu. Chodidla zůstávají v kontaktu. Vrať koleno dolů; otevření a návrat je jedno opakování horní nohy. Po sérii se otoč na druhý bok.","Slowly open the top knee only as far as the pelvis stays still. Keep the feet in contact. Lower the knee; one opening and return is one repetition of the top leg. Turn onto the other side after the set."],"watchFor":["Pohyb veď pomalu. Paty drž u sebe a trup neotáčej dozadu.","Move slowly. Keep the heels together and avoid rolling the torso backward."]},"progression":["Lehčí: menší otevření. Náročnější: pomalejší návrat nebo krátká pauza. Smyčka nad koleny je volitelná odporová úprava; poznamenej její použití a nepřeváděj barvu gumy na kilogramy.","Easier: open through a smaller range. More demanding: lower more slowly or pause briefly. A loop above the knees is an optional resisted modification; note its use and do not convert band colour to kilograms."]}}},"sideleg":{"id":"sideleg","segment":"C","edits":{"pos":["Lehni si na bok a podepři hlavu. Horní nohu nech nataženou v prodloužení trupu, spodní můžeš pro oporu lehce pokrčit. Volnou dlaň polož před sebe a srovnej pánev nad sebe.","Lie on your side and support your head. Keep the top leg straight in line with the trunk; the lower leg may bend slightly for support. Place the free palm in front and stack the pelvis."],"exe":["Zvedni horní nohu do strany jen tak vysoko, aby se pánev nepřeklápěla a pas nezkracoval. Koleno nech natažené bez násilného propnutí. Pomalu vrať nohu k výchozí poloze; zdvih a návrat je jedno opakování horní nohy. Potom vystřídej bok.","Lift the top leg sideways only as high as you can keep the pelvis still without shortening the waist. Keep the knee straight without forcing it back. Slowly return toward the starting position; one lift and return is one repetition of the top leg. Then change sides."],"foc":["Pohybuj horní nohou z kyčle, špička míří přibližně vpřed. Výšku nezískávej nakláněním pánve.","Move the top leg from the hip with the toes roughly forward. Do not gain height by tilting the pelvis."],"pro":["Lehčí: menší zdvih a odpočinek mezi opakováními. Náročnější: krátká pauza nebo pomalejší návrat při stejné poloze. Volně položené závaží na stehno není součástí této varianty.","Easier: a smaller lift and a rest between repetitions. More demanding: a short pause or slower lowering in the same position. A loose weight resting on the thigh is not part of this version."],"source":{"author":"American Academy of Orthopaedic Surgeons","document":"Hip Conditioning Program — Hip Abduction","url":"https://orthoinfo.aaos.org/globalassets/pdfs/2017-rehab_hip.pdf","scope":"Side-lying straight top-leg abduction and a quiet hip position. No fixed angle, clinical frequency, five-second hold or ankle-weight prescription is transferred. Local count convention preserves existing records."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["side_lying"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"sideleg","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/sideleg-103eaba582d2647b.mp4"]},"art":{"appId":"sideleg","atlasId":"sideleg","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"1e943a3a66dbd93ee15913bbf5ba2e639aca36955e801b9a4e1b8deaf80ff236","thumb":"/unified-atlas/sideleg-197f6bcc08918168-thumb.webp","detail":"/unified-atlas/sideleg-41a54fe7c83420ef-detail.webp","inkThumb":"/unified-atlas/sideleg-ac243f5f880d2bc6-inkThumb.webp","inkDetail":"/unified-atlas/sideleg-a0d224b1a46c2576-inkDetail.webp","fillThumb":"/unified-atlas/sideleg-ab1b2dd7d5d08d15-fillThumb.webp","fillDetail":"/unified-atlas/sideleg-34d0191409726c1f-fillDetail.webp"},"sourceSha256":"1e943a3a66dbd93ee15913bbf5ba2e639aca36955e801b9a4e1b8deaf80ff236","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"98b5f122e4ce9ca2":{"fields":{"id":"sideleg","cz":"Unožování vleže","en":"Side-Lying Leg Raise","pat":"ohyb","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Pohybuj horní nohou z kyčle, špička míří přibližně vpřed. Výšku nezískávej nakláněním pánve.","Move the top leg from the hip with the toes roughly forward. Do not gain height by tilting the pelvis."],"startPosition":["Lehni si na bok a podepři hlavu. Horní nohu nech nataženou v prodloužení trupu, spodní můžeš pro oporu lehce pokrčit. Volnou dlaň polož před sebe a srovnej pánev nad sebe.","Lie on your side and support your head. Keep the top leg straight in line with the trunk; the lower leg may bend slightly for support. Place the free palm in front and stack the pelvis."],"execution":["Zvedni horní nohu do strany jen tak vysoko, aby se pánev nepřeklápěla a pas nezkracoval. Koleno nech natažené bez násilného propnutí. Pomalu vrať nohu k výchozí poloze; zdvih a návrat je jedno opakování horní nohy. Potom vystřídej bok.","Lift the top leg sideways only as high as you can keep the pelvis still without shortening the waist. Keep the knee straight without forcing it back. Slowly return toward the starting position; one lift and return is one repetition of the top leg. Then change sides."],"watchFor":["Trup se nekývá. Pohyb dělá bok, ne švih.","The torso never rocks. The hip does the work, not momentum."]},"progression":["Lehčí: menší zdvih a odpočinek mezi opakováními. Náročnější: krátká pauza nebo pomalejší návrat při stejné poloze. Volně položené závaží na stehno není součástí této varianty.","Easier: a smaller lift and a rest between repetitions. More demanding: a short pause or slower lowering in the same position. A loose weight resting on the thigh is not part of this version."]}}},"ex26_firehydrant":{"id":"ex26_firehydrant","segment":"C","edits":{"exe":["Zvedni pokrčené koleno do strany, aniž by se výrazně otočila pánev. Obě dlaně a druhé koleno zůstávají opřené. Pomalu vrať koleno pod kyčel. Jeden zdvih a návrat je jedno opakování; levou a pravou pracovní nohu zapisuj zvlášť.","Lift one bent knee sideways without substantially rotating the pelvis. Keep both palms and the other knee supported. Slowly return the knee beneath the hip. One lift and return is one repetition; record the left and right working legs separately."],"equipmentDetail":["Pevná neklouzavá podlaha; podložení kolen je volitelné podle pohodlí. Guma z náročnější úpravy není nutná pro základní cvik.","Use a firm non-slip floor; knee cushioning is optional for comfort. The band in the harder modification is not required for the basic exercise."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["quadruped"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_firehydrant","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_firehydrant-7457817f59cea9a9.mp4"]},"art":{"appId":"ex26_firehydrant","atlasId":"ex26_firehydrant","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5663639dffa6a8ec21bad7aeb8ce6fc10e26e410b93ec249edfdef9abb53ef84","thumb":"/expansion-atlas/ex26_firehydrant-original-256.webp","detail":"/expansion-atlas/ex26_firehydrant-original-960.webp","inkThumb":"/expansion-atlas/ex26_firehydrant-ink-256.webp","inkDetail":"/expansion-atlas/ex26_firehydrant-ink-960.webp","fillThumb":"/expansion-atlas/ex26_firehydrant-fill-256.webp","fillDetail":"/expansion-atlas/ex26_firehydrant-fill-960.webp"},"sourceSha256":"5663639dffa6a8ec21bad7aeb8ce6fc10e26e410b93ec249edfdef9abb53ef84","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"1c402b625d759e4f":{"fields":{"id":"ex26_firehydrant","cz":"Unožování pokrčené nohy na čtyřech","en":"Quadruped Fire Hydrant","pat":"ohyb","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Zvedni pokrčené koleno do strany, aniž by se výrazně otočila pánev.","Lift one bent knee sideways without substantially rotating the pelvis."],"startPosition":["Na čtyřech dej ruce pod ramena a kolena pod kyčle. Záda drž v pohodlné neutrální poloze.","On all fours, place hands below shoulders and knees below hips. Keep a comfortable neutral back."],"execution":["Zvedni pokrčené koleno do strany, aniž by se výrazně otočila pánev. Obě dlaně a druhé koleno zůstávají opřené. Pomalu vrať koleno pod kyčel. Jeden zdvih a návrat je jedno opakování; levou a pravou pracovní nohu zapisuj zvlášť.","Lift one bent knee sideways without substantially rotating the pelvis. Keep both palms and the other knee supported. Slowly return the knee beneath the hip. One lift and return is one repetition; record the left and right working legs separately."],"watchFor":["Výška není cíl. Zastav dříve, než musíš vytočit celý trup nebo se prohnout.","Height is not the goal. Stop before turning the whole torso or arching the back."]},"progression":["Lehčí: menší rozsah nebo škeble vleže. Těžší: pauza v horní poloze, následně lehká guma nad koleny.","Easier: a smaller range or side-lying clamshells. Harder: pause at the top, then add a light band above the knees."]}}},"ig27_quadruped_straight_abduction":{"id":"ig27_quadruped_straight_abduction","segment":"C","edits":{"exe":["Zvedni nataženou nohu jen o kousek, krátce ji podrž a pomalu polož. Obě dlaně i druhé koleno zůstávají opřené, pánev a hrudník míří k podlaze. Odlepení a položení je jedno opakování pracovní nohy. Levou a pravou sérii zapisuj zvlášť; pauza nahoře není další opakování.","Lift the straight leg a small distance, pause briefly and lower it slowly. Keep both palms and the other knee supported, with the pelvis and chest facing the floor. One lift and return is one repetition of the working leg. Record left and right sets separately; the pause does not count as another repetition."],"equipmentDetail":["Pevná neklouzavá podlaha a prostor pro nohu do strany. Volitelná tenká podložka pod opěrné koleno nesmí klouzat.","Use a firm non-slip floor with room for the leg to the side. An optional thin pad under the supporting knee must not slide."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["quadruped"],"supports":["hand_support"],"priority":2,"equipmentRequirements":[["telo"]]},"policy":{"id":"ig27_quadruped_straight_abduction","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ig27_quadruped_straight_abduction-237423c160764425.mp4"]},"art":{"appId":"ig27_quadruped_straight_abduction","atlasId":"ig27_quadruped_straight_abduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"e7e2354a27ca0a84d1b28a0ae22e561e65a69f0a056ecee49489a8075c6fa8c9","thumb":"/expansion-atlas/ig27_quadruped_straight_abduction-original-256.webp","detail":"/expansion-atlas/ig27_quadruped_straight_abduction-original-960.webp","inkThumb":"/expansion-atlas/ig27_quadruped_straight_abduction-ink-256.webp","inkDetail":"/expansion-atlas/ig27_quadruped_straight_abduction-ink-960.webp","fillThumb":"/expansion-atlas/ig27_quadruped_straight_abduction-fill-256.webp","fillDetail":"/expansion-atlas/ig27_quadruped_straight_abduction-fill-960.webp"},"sourceSha256":"e7e2354a27ca0a84d1b28a0ae22e561e65a69f0a056ecee49489a8075c6fa8c9","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"d20951b2038fc331":{"fields":{"id":"ig27_quadruped_straight_abduction","cz":"Unožování natažené nohy v kleku na čtyřech","en":"Quadruped Straight-Leg Hip Abduction","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":20,"unilateral":true,"sideMode":"perSide","focus":["Zvedni nataženou nohu jen o kousek, krátce ji podrž a pomalu polož.","Lift the straight leg a small distance, pause briefly and lower slowly."],"startPosition":["Začni na čtyřech s dlaněmi pod rameny. Jednu nohu natáhni do strany a chodidlo lehce polož. Druhé koleno zůstává pod kyčlí.","Begin on all fours with the palms below the shoulders. Extend one leg out to the side and lightly rest its foot on the floor. Keep the other knee below its hip."],"execution":["Zvedni nataženou nohu jen o kousek, krátce ji podrž a pomalu polož. Obě dlaně i druhé koleno zůstávají opřené, pánev a hrudník míří k podlaze. Odlepení a položení je jedno opakování pracovní nohy. Levou a pravou sérii zapisuj zvlášť; pauza nahoře není další opakování.","Lift the straight leg a small distance, pause briefly and lower it slowly. Keep both palms and the other knee supported, with the pelvis and chest facing the floor. One lift and return is one repetition of the working leg. Record left and right sets separately; the pause does not count as another repetition."],"watchFor":["Zdvih nevytvářej otevřením pánve ani záklonem beder. Špičku drž přibližně vpřed ve směru trupu, netoč ji násilím vzhůru. Malé odlepení chodidla stačí.","Do not create height by opening the pelvis or arching the lower back. Keep the toes roughly forward in the direction of the torso rather than forcing them upward. A small foot lift is enough."]},"progression":["Lehčí: kratší výdrž a menší odlepení, případně unožování s pokrčeným kolenem. Těžší: delší pauza nebo pomalejší spouštění při stejné poloze pánve.","Easier: a shorter hold and smaller lift, or hip abduction with a bent knee. Harder: a longer pause or slower lowering with the pelvis unchanged."]}}},"ig26_band_hip_abduction":{"id":"ig26_band_hip_abduction","segment":"C","edits":{"eq":["guma","fixed_anchor","ankle_cuff","fixed_support"],"pos":["Stůj na pevné neklouzavé podlaze bokem k nízké pevné kotvě gumy. Připoj gumu přes vhodnou kotníkovou manžetu ke vzdálenější noze. Bližší rukou se přidrž pevné opory nebo zdi. Chodidla míří přibližně vpřed.","Stand on a firm non-slip floor side-on to a secure low band anchor. Use a suitable ankle cuff to attach the band to the farther leg. Hold a fixed support or wall with the nearer hand. Point both feet roughly forward."],"exe":["Veď pracovní nohu pomalu do strany v malém rozsahu. Vrať ji bez škubnutí gumy. Pánev zůstává vodorovně a trup nad stojnou nohou. Unožení a návrat je jedno opakování; každou pracovní nohu zapisuj zvlášť.","Move the working leg slowly sideways through a small range and return without letting the band jerk. Keep the pelvis level and torso over the supporting leg. One outward movement and return is one repetition; record each working leg separately."],"equipmentDetail":["Guma, kotníková manžeta, pevná nízká kotva a opora ruky. Jedna pevně ukotvená konstrukce může sloužit jako kotva i opora; lehký volný stojan nestačí. Před začátkem zkontroluj uchycení a volnou dráhu gumy před stojnou nohou.","A resistance band, ankle cuff, secure low anchor and hand support are required. One securely fixed structure may provide both anchor and support; a light freestanding post is insufficient. Check the attachment and a clear band path in front of the supporting leg."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["standing"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["guma"],["fixed_anchor"],["ankle_cuff"],["fixed_support","zed"]]},"policy":{"id":"ig26_band_hip_abduction","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["guma"],["fixed_anchor"],["ankle_cuff"],["fixed_support","zed"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ig26_band_hip_abduction-e70595076d478ffc.mp4"]},"art":{"appId":"ig26_band_hip_abduction","atlasId":"ig26_band_hip_abduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"180da4ba6782cc8026718173a73b28506595817442f6bd8e3ea72b53da0914d1","thumb":"/expansion-atlas/ig26_band_hip_abduction-original-256.webp","detail":"/expansion-atlas/ig26_band_hip_abduction-original-960.webp","inkThumb":"/expansion-atlas/ig26_band_hip_abduction-ink-256.webp","inkDetail":"/expansion-atlas/ig26_band_hip_abduction-ink-960.webp","fillThumb":"/expansion-atlas/ig26_band_hip_abduction-fill-256.webp","fillDetail":"/expansion-atlas/ig26_band_hip_abduction-fill-960.webp"},"sourceSha256":"180da4ba6782cc8026718173a73b28506595817442f6bd8e3ea72b53da0914d1","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"a9557162a9f9878a":{"fields":{"id":"ig26_band_hip_abduction","cz":"Unožování ve stoji s gumou a oporou","en":"Supported Standing Band Hip Abduction","pat":"drep","eq":["guma","fixed_anchor","ankle_cuff","fixed_support"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Pohyb vychází z kyčle, trup se neuklání.","Move from the hip without leaning the torso."],"startPosition":["Stůj na pevné neklouzavé podlaze bokem k nízké pevné kotvě gumy. Připoj gumu přes vhodnou kotníkovou manžetu ke vzdálenější noze. Bližší rukou se přidrž pevné opory nebo zdi. Chodidla míří přibližně vpřed.","Stand on a firm non-slip floor side-on to a secure low band anchor. Use a suitable ankle cuff to attach the band to the farther leg. Hold a fixed support or wall with the nearer hand. Point both feet roughly forward."],"execution":["Veď pracovní nohu pomalu do strany v malém rozsahu. Vrať ji bez škubnutí gumy. Pánev zůstává vodorovně a trup nad stojnou nohou. Unožení a návrat je jedno opakování; každou pracovní nohu zapisuj zvlášť.","Move the working leg slowly sideways through a small range and return without letting the band jerk. Keep the pelvis level and torso over the supporting leg. One outward movement and return is one repetition; record each working leg separately."],"watchFor":["Nezvedej celý bok a nevytáčej špičku vzhůru. Guma nesmí odírat stojnou nohu ani se zachytit o chodidlo.","Do not hike the hip or turn the toes upward. Keep the band from rubbing or catching the supporting leg or foot."]},"progression":["Lehčí: bez gumy nebo slabší odpor. Těžší: malý nárůst odporu při stejném rozsahu. Ztráta opory není nutná pro zatížení kyčle.","Easier: no band or lighter resistance. Harder: a small resistance increase at the same range. Removing hand support is unnecessary for loading the hip."]}}},"ig29_standing_leg_abduction_hold":{"id":"ig29_standing_leg_abduction_hold","segment":"C","edits":{"exe":["Volnou nataženou nohu zvedni nízko do strany. Čas začni měřit až ve stabilní poloze a klidně dýchej. Výdrž ukonči při ztrátě polohy; kontrolovaně polož nohu. Zapisuj skutečně udržené sekundy levé a pravé pracovní nohy zvlášť, nikoli dobu přechodu mezi stranami.","Lift the free straight leg a short distance sideways. Start timing only once the position is stable and breathe calmly. End the hold when the position is lost, then lower under control. Record the seconds actually held by the left and right working legs separately, excluding the change of sides."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ig29_standing_leg_abduction_hold","measurementType":"DURATION","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig29_standing_leg_abduction_hold","atlasId":"ig29_standing_leg_abduction_hold","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"8a80e76fbe0f4a15ca637b9cf019b228fda7a4a2ad5f729205df23e3401302e3","thumb":"/expansion-atlas/ig29_standing_leg_abduction_hold-original-256.webp","detail":"/expansion-atlas/ig29_standing_leg_abduction_hold-original-960.webp","inkThumb":"/expansion-atlas/ig29_standing_leg_abduction_hold-ink-256.webp","inkDetail":"/expansion-atlas/ig29_standing_leg_abduction_hold-ink-960.webp","fillThumb":"/expansion-atlas/ig29_standing_leg_abduction_hold-fill-256.webp","fillDetail":"/expansion-atlas/ig29_standing_leg_abduction_hold-fill-960.webp"},"sourceSha256":"8a80e76fbe0f4a15ca637b9cf019b228fda7a4a2ad5f729205df23e3401302e3","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"013f88d92fe62635":{"fields":{"id":"ig29_standing_leg_abduction_hold","cz":"Výdrž v unožení ve stoji","en":"Standing Hip-Abduction Hold","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Drž nízké unožení bez úklonu a zvedání pánve.","Hold a low side raise without leaning or hiking the pelvis."],"startPosition":["Stůj vzpřímeně a podle potřeby se lehce přidrž pevné opory. Přenes váhu na jednu nohu, koleno nech měkké. Pánev i špičky směřují vpřed.","Stand upright and use light hand support if needed. Shift weight onto one leg with a soft knee. Face the pelvis and toes forward."],"execution":["Volnou nataženou nohu zvedni nízko do strany. Čas začni měřit až ve stabilní poloze a klidně dýchej. Výdrž ukonči při ztrátě polohy; kontrolovaně polož nohu. Zapisuj skutečně udržené sekundy levé a pravé pracovní nohy zvlášť, nikoli dobu přechodu mezi stranami.","Lift the free straight leg a short distance sideways. Start timing only once the position is stable and breathe calmly. End the hold when the position is lost, then lower under control. Record the seconds actually held by the left and right working legs separately, excluding the change of sides."],"watchFor":["Neukláněj trup, nezvedej celý bok a nevytáčej špičku vzhůru. Výdrž ukonči, jakmile polohu držíš kompenzací místo klidné práce kyčle.","Avoid leaning the torso, hiking the hip or turning the toes upward. End the hold when compensation replaces steady hip control."]},"progression":["Lehčí: nižší unožení, kratší výdrž a větší opora ruky. Těžší: nejprve několik sekund navíc, potom nepatrně vyšší unožení. Neměň oba nároky současně.","Easier: a lower raise, shorter hold and more hand support. Harder: first add a few seconds, then slightly more height. Do not increase both demands together."]}}},"ex26_lateral_bandwalk":{"id":"ex26_lateral_bandwalk","segment":"C","edits":{"eq":["short_loop_band","prostor"],"exe":["Udělej malý krok do strany vedoucí nohou a potom kontrolovaně přibliž druhou, aby mezi chodidly zůstala mezera a guma byla lehce napnutá. Pro nový předpis počítej tento krok a přisunutí jako jedno opakování. Zapiš zvlášť postup doleva (L) a doprava (R); obě nohy při něm pracují.","Take a small side step with the leading foot, then bring the other foot closer under control, leaving a gap and light band tension. For a new prescription, count this step and follow as one repetition. Record travel to the left (L) and right (R) separately; both legs work in each direction."],"wat":["Nekolébej trupem a netlač kolena násilím ven. Měj volnou rovnou dráhu na obě strany. Starší počty kroků nepřepočítávej; pokud měl trénink jinou domluvenou konvenci, zachovej ji v poznámce.","Do not sway the torso or force the knees outward. Keep a clear level route in both directions. Do not recalculate older step counts; if a session used another agreed convention, keep it in its note."],"equipmentDetail":["Krátká odporová smyčka nad koleny a volný neklouzavý prostor pro kroky do obou stran. Smyčka na kotnících zůstává zvlášť poznamenaná náročnější úprava, ne automatická záměna.","Use a short resistance loop above the knees and clear non-slip space for steps in both directions. An ankle-level loop remains a separately noted harder modification, not an automatic substitution."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["standing"],"supports":[],"priority":1,"equipmentRequirements":[["short_loop_band"],["prostor"]]},"policy":{"id":"ex26_lateral_bandwalk","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["short_loop_band"],["prostor"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_lateral_bandwalk","atlasId":"ex26_lateral_bandwalk","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"db4ceacca910b82624de210bbf5c18710913f79e219b8592a5f5d66f9761d79d","thumb":"/expansion-atlas/ex26_lateral_bandwalk-original-256.webp","detail":"/expansion-atlas/ex26_lateral_bandwalk-original-960.webp","inkThumb":"/expansion-atlas/ex26_lateral_bandwalk-ink-256.webp","inkDetail":"/expansion-atlas/ex26_lateral_bandwalk-ink-960.webp","fillThumb":"/expansion-atlas/ex26_lateral_bandwalk-fill-256.webp","fillDetail":"/expansion-atlas/ex26_lateral_bandwalk-fill-960.webp"},"sourceSha256":"db4ceacca910b82624de210bbf5c18710913f79e219b8592a5f5d66f9761d79d","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"e6e864989d41b6b3":{"fields":{"id":"ex26_lateral_bandwalk","cz":"Boční chůze s gumou","en":"Lateral Band Walk","pat":"prenos","eq":["short_loop_band","prostor"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Dělej malé boční kroky.","Take small lateral steps."],"startPosition":["Dej lehkou smyčku nad kolena. Mírně pokrč kyčle a kolena, chodidla přibližně rovnoběžně.","Place a light loop above the knees. Slightly bend hips and knees with feet roughly parallel."],"execution":["Udělej malý krok do strany vedoucí nohou a potom kontrolovaně přibliž druhou, aby mezi chodidly zůstala mezera a guma byla lehce napnutá. Pro nový předpis počítej tento krok a přisunutí jako jedno opakování. Zapiš zvlášť postup doleva (L) a doprava (R); obě nohy při něm pracují.","Take a small side step with the leading foot, then bring the other foot closer under control, leaving a gap and light band tension. For a new prescription, count this step and follow as one repetition. Record travel to the left (L) and right (R) separately; both legs work in each direction."],"watchFor":["Nekolébej trupem a netlač kolena násilím ven. Měj volnou rovnou dráhu na obě strany. Starší počty kroků nepřepočítávej; pokud měl trénink jinou domluvenou konvenci, zachovej ji v poznámce.","Do not sway the torso or force the knees outward. Keep a clear level route in both directions. Do not recalculate older step counts; if a session used another agreed convention, keep it in its note."]},"progression":["Lehčí: slabší guma a vyšší postoj. Těžší: více kvalitních kroků nebo guma u kotníků s nižším odporem; neposouvej ji níže a zároveň neposiluj.","Easier: a lighter band and taller stance. Harder: more controlled steps or a lighter band at the ankles; do not lower placement and increase resistance together."]}}},"hipabduction":{"id":"hipabduction","segment":"C","edits":{"eq":["hip_abduction_machine"],"load":"ext","measurementType":"WEIGHT_REPS","pos":["Nastav stroj pro unožování podle jeho návodu: polstry jsou vně stehen u kolen. Sedni se zády opřenými, chodidla polož na určené opory a uchop madla. Výchozí šířku nastav pohodlně, bez nuceného sevření nebo roztažení.","Set the machine for hip abduction according to its instructions, with pads outside the thighs near the knees. Sit against the backrest, place the feet on the intended supports and hold the handles. Choose a comfortable starting width without forcing the legs together or apart."],"exe":["Pomalu odtlač obě stehna od sebe jen do ovládaného rozsahu. Krátce zastav a vrať je bez nárazu závaží. Společné rozevření a návrat obou nohou je jedno opakování. Zapisuj zvolenou zátěž z ukazatele stejného stroje, ne dvojnásobek za dvě nohy.","Slowly press both thighs apart through a controlled range. Pause briefly and return without letting the weights slam. Opening and returning both legs together is one repetition. Record the selected load shown on the same machine, not twice that value for two legs."],"wat":["Neodrážej se zády a nezvedej pánev ze sedadla. Zátěž, nastavení a rozsah drž při porovnávání stejné; stejné číslo na jiném stroji nemusí znamenat stejný odpor. Při bolesti rozsah zmenši nebo sérii ukonči.","Do not bounce off the backrest or lift the pelvis from the seat. Keep the machine, settings and range consistent when comparing sessions; the same number on another machine may not represent the same resistance. Reduce the range or stop the set if it hurts."],"pro":["Lehčí: nižší zátěž a kratší pohodlný rozsah. Náročnější: nejprve plynulý návrat při stejném nastavení, potom podle kontroly malý krok zátěže daného stroje. Širší rozevření ani záklon nejsou podmínkou.","Easier: use less load and a shorter comfortable range. More demanding: first control the return at the same settings, then consider a small load increment on that machine. A wider spread or leaning back is not required."],"source":{"author":"Life Fitness","document":"Optima Series User Manual — OSHAA Hip Abductor, printed page 8","url":"https://www.lifefitness.com.au/wp-content/uploads/2015/02/Optima_user_manual_for_all_strength_2_585_1371787541.pdf","scope":"Manufacturer example of seated bilateral abduction, outward-facing pads, foot supports, handles and controlled return. Follow the actual model instructions; its exact dimensions, stack total and lever settings are not universal. The recorded load convention is a local clarification, not a force calibration."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["seated"],"supports":["machine"],"priority":1,"equipmentRequirements":[["hip_abduction_machine"]]},"policy":{"id":"hipabduction","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["hip_abduction_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"hipabduction","atlasId":"hipabduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"607e87cd97a89870d3a470b48d804b018f31226d55ad7e47ff75af37dac3912b","thumb":"/unified-atlas/hipabduction-b4d2ec73137da15b-thumb.webp","detail":"/unified-atlas/hipabduction-894fee138e4070e4-detail.webp","inkThumb":"/unified-atlas/hipabduction-c754526c83ce2024-inkThumb.webp","inkDetail":"/unified-atlas/hipabduction-45ecc7a5399db8f7-inkDetail.webp","fillThumb":"/unified-atlas/hipabduction-842608d2ebfc6547-fillThumb.webp","fillDetail":"/unified-atlas/hipabduction-a4c48c8889b50838-fillDetail.webp"},"sourceSha256":"607e87cd97a89870d3a470b48d804b018f31226d55ad7e47ff75af37dac3912b","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"15e0f26d21c80323":{"fields":{"id":"hipabduction","cz":"Abdukce kyčlí na stroji","en":"Hip Abduction Machine","pat":"drep","eq":["hip_abduction_machine"],"measurementType":"WEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Roztlač kolena od sebe, trup zůstane klidný.","Push the knees apart. The torso stays still."],"startPosition":["Nastav stroj pro unožování podle jeho návodu: polstry jsou vně stehen u kolen. Sedni se zády opřenými, chodidla polož na určené opory a uchop madla. Výchozí šířku nastav pohodlně, bez nuceného sevření nebo roztažení.","Set the machine for hip abduction according to its instructions, with pads outside the thighs near the knees. Sit against the backrest, place the feet on the intended supports and hold the handles. Choose a comfortable starting width without forcing the legs together or apart."],"execution":["Pomalu odtlač obě stehna od sebe jen do ovládaného rozsahu. Krátce zastav a vrať je bez nárazu závaží. Společné rozevření a návrat obou nohou je jedno opakování. Zapisuj zvolenou zátěž z ukazatele stejného stroje, ne dvojnásobek za dvě nohy.","Slowly press both thighs apart through a controlled range. Pause briefly and return without letting the weights slam. Opening and returning both legs together is one repetition. Record the selected load shown on the same machine, not twice that value for two legs."],"watchFor":["Neodrážej se zády a nezvedej pánev ze sedadla. Zátěž, nastavení a rozsah drž při porovnávání stejné; stejné číslo na jiném stroji nemusí znamenat stejný odpor. Při bolesti rozsah zmenši nebo sérii ukonči.","Do not bounce off the backrest or lift the pelvis from the seat. Keep the machine, settings and range consistent when comparing sessions; the same number on another machine may not represent the same resistance. Reduce the range or stop the set if it hurts."]},"progression":["Lehčí: nižší zátěž a kratší pohodlný rozsah. Náročnější: nejprve plynulý návrat při stejném nastavení, potom podle kontroly malý krok zátěže daného stroje. Širší rozevření ani záklon nejsou podmínkou.","Easier: use less load and a shorter comfortable range. More demanding: first control the return at the same settings, then consider a small load increment on that machine. A wider spread or leaning back is not required."]}}},"ex26_cable_abduction":{"id":"ex26_cable_abduction","segment":"C","edits":{"eq":["low_cable","cable_ankle_cuff","fixed_support"],"pos":["Připoj vhodnou kotníkovou manžetu ke spodnímu vývodu kladky a připni ji na vzdálenější nohu. Stůj bokem na pevné podlaze, bližší rukou drž pevné madlo nebo vhodnou část konstrukce. Kabel musí mít volnou dráhu před stojnou nohou.","Connect a suitable ankle cuff to the low cable outlet and fasten it to the farther leg. Stand side-on on a firm floor, holding a fixed handle or suitable part of the frame with the nearer hand. Keep a clear cable path in front of the supporting leg."],"exe":["Veď připnutou nohu pomalu do strany v malém rozsahu, špička přibližně vpřed. Vrať ji bez nárazu závaží. Unožení a návrat je jedno opakování pracovní nohy. Každou stranu zapisuj zvlášť se zátěží z ukazatele stejné kladky, ne přepočtenou silou na kotníku.","Move the attached leg slowly sideways through a small range with the toes roughly forward. Return without letting the weights slam. One outward movement and return is one repetition of the working leg. Record each side separately using the selected load shown on the same pulley, not a calculated force at the ankle."],"equipmentDetail":["Spodní nebo nízko nastavitelná kladka, kotníková manžeta určená pro kladku a pevná opora ruky. Vestavěné madlo může splnit oporu; samotná horní kladka, holé lanko ani manžeta bez vhodného uchycení nestačí.","A low or height-adjustable cable pulley, a cable-compatible ankle cuff and fixed hand support are required. An integrated handle may provide the support; a high pulley alone, bare cable or cuff without a suitable connector is insufficient."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["standing"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]]},"policy":{"id":"ex26_cable_abduction","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_cable_abduction-5c95d1aed799878e.mp4"]},"art":{"appId":"ex26_cable_abduction","atlasId":"ex26_cable_abduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3df2f66af2bdf2f76f43d75dbfe206afb36ec81a11d060f35e13e79a3e4b5934","thumb":"/expansion-atlas/ex26_cable_abduction-original-256.webp","detail":"/expansion-atlas/ex26_cable_abduction-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_abduction-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_abduction-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_abduction-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_abduction-fill-960.webp"},"sourceSha256":"3df2f66af2bdf2f76f43d75dbfe206afb36ec81a11d060f35e13e79a3e4b5934","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"16d0fefb09cbca07":{"fields":{"id":"ex26_cable_abduction","cz":"Unožování na spodní kladce","en":"Standing Cable Hip Abduction","pat":"drep","eq":["low_cable","cable_ankle_cuff","fixed_support"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Veď připnutou nohu do strany v malém rozsahu, špička přibližně vpřed.","Move the working leg sideways through a small range with the toes roughly forward."],"startPosition":["Připoj vhodnou kotníkovou manžetu ke spodnímu vývodu kladky a připni ji na vzdálenější nohu. Stůj bokem na pevné podlaze, bližší rukou drž pevné madlo nebo vhodnou část konstrukce. Kabel musí mít volnou dráhu před stojnou nohou.","Connect a suitable ankle cuff to the low cable outlet and fasten it to the farther leg. Stand side-on on a firm floor, holding a fixed handle or suitable part of the frame with the nearer hand. Keep a clear cable path in front of the supporting leg."],"execution":["Veď připnutou nohu pomalu do strany v malém rozsahu, špička přibližně vpřed. Vrať ji bez nárazu závaží. Unožení a návrat je jedno opakování pracovní nohy. Každou stranu zapisuj zvlášť se zátěží z ukazatele stejné kladky, ne přepočtenou silou na kotníku.","Move the attached leg slowly sideways through a small range with the toes roughly forward. Return without letting the weights slam. One outward movement and return is one repetition of the working leg. Record each side separately using the selected load shown on the same pulley, not a calculated force at the ankle."],"watchFor":["Neukláněj trup a nevytahuj bok vzhůru. Kabel veď bezpečně před stojnou nohou.","Do not lean the torso or hike the hip. Keep the cable safely in front of the supporting leg."]},"progression":["Lehčí: menší odpor nebo unožení bez zátěže s oporou. Těžší: krátká pauza v krajní poloze, pak malý přírůstek odporu.","Easier: less resistance or an unloaded supported leg raise. Harder: pause at the end of the range, then add a little resistance."]}}},"hipadduction":{"id":"hipadduction","segment":"D","edits":{"eq":["hip_adduction_machine"],"load":"ext","measurementType":"WEIGHT_REPS","cz":"Přinožování na stroji vsedě","en":"Seated Machine Hip Adduction","foc":["Přitahuj stehna k sobě a kontroluj návrat bez odrážení trupu.","Bring the thighs together and control the return without bouncing the torso."],"pos":["Nastav stroj pro přinožování podle jeho návodu. Sedni se zády opřenými, polstry na vnitřní straně stehen u kolen a chodidly na určených oporách. Uchop madla a zvol pohodlnou výchozí šířku.","Set the machine for adduction according to its instructions. Sit against the backrest with the pads inside the thighs near the knees and feet on the intended supports. Hold the handles and choose a comfortable starting width."],"exe":["Plynule přitáhni obě stehna k sobě a pomalu se vrať bez nárazu závaží. Sevření a návrat obou nohou dohromady jsou jedno opakování; údaj zátěže zapisuj jednou, ne za každou nohu. Po sérii vrať zátěž a uvolni výstup podle návodu stroje.","Bring both thighs inward smoothly, then return slowly without slamming the weights. Closing and returning both legs together counts as one repetition; enter the displayed load once, not for each leg. After the set, return the load and release the exit mechanism as the machine instructs."],"wat":["Nenatahuj třísla násilím do krajní šířky a nezvedej pánev ze sedadla. Při ostré bolesti pohyb ukonči. Nastavení měň až po odložení zátěže.","Do not force the groin into an extreme opening or lift the pelvis off the seat. Stop for sharp pain. Change settings only after unloading the machine."],"pro":["Lehčí: menší zátěž nebo kratší pohodlný rozsah. Náročnější: malý přírůstek odporu při stejném stroji, nastavení a ovládaném návratu. Větší rozevření není podmínkou; údaje různých strojů nejsou přímo srovnatelné.","Easier: less load or a shorter comfortable range. More demanding: a small resistance increase on the same machine and settings with a controlled return. Opening farther is not required; readings from different machines are not directly comparable."],"equipmentDetail":["Stroj na přinožování vsedě, případně kombinovaný stroj nastavený na přinožování. Zapisuj údaj z jeho zátěžového ukazatele jednou, ne za každou nohu; stejné číslo na jiném stroji nemusí znamenat stejný odpor.","A seated hip-adduction machine, including a combined machine set to adduction. Record its displayed load once, not for each leg; the same number on another machine may represent a different resistance."],"source":{"author":"Life Fitness","document":"Optima Series User Manual — OSHAA hip adductor, printed page 8","url":"https://www.lifefitness.com.au/wp-content/uploads/2015/02/Optima_user_manual_for_all_strength_2_585_1371787541.pdf","scope":"Manufacturer example of seated bilateral adduction and entry/exit settings. Follow the actual model instructions; exact lever placement and machine calibration are not universal. Counting and displayed-load conventions are Tanmay editorial clarifications."}},"taxonomy":{"regions":["thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["strength"],"positions":["seated"],"supports":["machine"],"equipmentRequirements":[["hip_adduction_machine"]],"priority":1,"aliases":["hip adduction machine","Addukce kyčlí na stroji","Hip Adduction Machine"]},"policy":{"id":"hipadduction","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"none","requirements":[["hip_adduction_machine"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"hipadduction","atlasId":"hipadduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3cfa72be832c6115d5bf04e241679da14bc21c2c2030b40b7033db6cdecbeeec","thumb":"/unified-atlas/hipadduction-146577f2862d4b57-thumb.webp","detail":"/unified-atlas/hipadduction-3f58601178b1a4b7-detail.webp","inkThumb":"/unified-atlas/hipadduction-6ac0af56836e66b6-inkThumb.webp","inkDetail":"/unified-atlas/hipadduction-346a83264e7b653e-inkDetail.webp","fillThumb":"/unified-atlas/hipadduction-bab1f7ba0eb296a9-fillThumb.webp","fillDetail":"/unified-atlas/hipadduction-9a975310aaef5990-fillDetail.webp"},"sourceSha256":"3cfa72be832c6115d5bf04e241679da14bc21c2c2030b40b7033db6cdecbeeec","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"ca3f9cf16ff56bae":{"fields":{"id":"hipadduction","cz":"Přinožování na stroji vsedě","en":"Seated Machine Hip Adduction","pat":"drep","eq":["hip_adduction_machine"],"measurementType":"WEIGHT_REPS","defaultRestSec":45,"unilateral":false,"sideMode":"none","focus":["Přitahuj stehna k sobě a kontroluj návrat bez odrážení trupu.","Bring the thighs together and control the return without bouncing the torso."],"startPosition":["Nastav stroj pro přinožování podle jeho návodu. Sedni se zády opřenými, polstry na vnitřní straně stehen u kolen a chodidly na určených oporách. Uchop madla a zvol pohodlnou výchozí šířku.","Set the machine for adduction according to its instructions. Sit against the backrest with the pads inside the thighs near the knees and feet on the intended supports. Hold the handles and choose a comfortable starting width."],"execution":["Plynule přitáhni obě stehna k sobě a pomalu se vrať bez nárazu závaží. Sevření a návrat obou nohou dohromady jsou jedno opakování; údaj zátěže zapisuj jednou, ne za každou nohu. Po sérii vrať zátěž a uvolni výstup podle návodu stroje.","Bring both thighs inward smoothly, then return slowly without slamming the weights. Closing and returning both legs together counts as one repetition; enter the displayed load once, not for each leg. After the set, return the load and release the exit mechanism as the machine instructs."],"watchFor":["Nenatahuj třísla násilím do krajní šířky a nezvedej pánev ze sedadla. Při ostré bolesti pohyb ukonči. Nastavení měň až po odložení zátěže.","Do not force the groin into an extreme opening or lift the pelvis off the seat. Stop for sharp pain. Change settings only after unloading the machine."]},"progression":["Lehčí: menší zátěž nebo kratší pohodlný rozsah. Náročnější: malý přírůstek odporu při stejném stroji, nastavení a ovládaném návratu. Větší rozevření není podmínkou; údaje různých strojů nejsou přímo srovnatelné.","Easier: less load or a shorter comfortable range. More demanding: a small resistance increase on the same machine and settings with a controlled return. Opening farther is not required; readings from different machines are not directly comparable."]}}},"ex26_cable_adduction":{"id":"ex26_cable_adduction","segment":"D","edits":{"pos":["Připoj kotníkovou manžetu ke spodnímu vývodu kladky a připni ji na nohu blíže stroji. Stůj bokem na pevné podlaze, drž pevné madlo a mírně povol stojné koleno. Nastav odstup tak, aby lanko mělo volnou dráhu.","Connect an ankle cuff to the low pulley and fasten it to the leg nearest the machine. Stand side-on on a firm floor, hold a fixed handle and soften the supporting knee. Choose a distance that gives the cable a clear path."],"exe":["Přitáhni připnutou nohu ke středu a jen mírně před stojnou nohu. Pomalu ji vrať do strany, pánev nech klidnou. Přitažení a návrat jsou jedno opakování připnuté nohy. Po sérii vystřídej stranu.","Draw the attached leg inward and just in front of the supporting leg. Return it slowly to the side with a steady pelvis. One inward movement and return is one repetition of the attached leg. Change sides after the set."],"wat":["Manžeta musí držet a lanko se nesmí zachytávat o stojnou nohu; nepohybuj se švihem. Zapisuj nastavenou zátěž stejné kladky zvlášť pro každou stranu. Číslo na závaží není odhad síly u kotníku.","Secure the cuff and keep the cable clear of the supporting leg; avoid swinging. Record the selected load on the same pulley separately for each side. The stack reading is not an estimate of force at the ankle."],"pro":["Lehčí: menší odpor a kratší rozsah; stroj vsedě je jiný úkol s větší oporou. Náročnější: malý přírůstek zátěže při stejné poloze a kladce. Opora ruky může zůstat.","Easier: less resistance and a shorter range; the seated machine is a different task with more support. More demanding: a small load increase with the same setup and pulley. Hand support may stay."],"equipmentDetail":["Spodní nebo nízko nastavitelná kladka, manžeta s úchytem pro kladku a pevná opora ruky; vestavěné madlo oporu splňuje. Zapisuj nastavenou zátěž stejné kladky zvlášť pro každou stranu, ne odhad síly u kotníku.","A low or height-adjustable pulley, a cable-compatible ankle cuff and fixed hand support; an integrated handle provides the support. Record the selected load on the same pulley separately for each side, not an estimate of force at the ankle."]},"taxonomy":{"regions":["thighs"],"secondaryRegions":["hips"],"movements":["joint"],"focus":["strength"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]],"priority":1,"aliases":["standing cable hip adduction","přinožení na kladce"]},"policy":{"id":"ex26_cable_adduction","measurementType":"WEIGHT_REPS","loadMode":"ext","sideMode":"perSide","requirements":[["low_cable","adjustable_cable"],["cable_ankle_cuff"],["fixed_support"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":false,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_cable_adduction","atlasId":"ex26_cable_adduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"50d6e163992fc36292cfe601ea6fee03e6604bff8d63a4c287c60ff3b941720e","thumb":"/expansion-atlas/ex26_cable_adduction-original-256.webp","detail":"/expansion-atlas/ex26_cable_adduction-original-960.webp","inkThumb":"/expansion-atlas/ex26_cable_adduction-ink-256.webp","inkDetail":"/expansion-atlas/ex26_cable_adduction-ink-960.webp","fillThumb":"/expansion-atlas/ex26_cable_adduction-fill-256.webp","fillDetail":"/expansion-atlas/ex26_cable_adduction-fill-960.webp"},"sourceSha256":"50d6e163992fc36292cfe601ea6fee03e6604bff8d63a4c287c60ff3b941720e","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"e4c2ce4009c490e4":{"fields":{"id":"ex26_cable_adduction","cz":"Přinožování na spodní kladce","en":"Standing Cable Hip Adduction","pat":"drep","eq":["kladka"],"measurementType":"WEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Táhni připnutou nohu směrem ke stojné noze a jen mírně přes střed.","Draw the working leg toward and slightly across the supporting leg."],"startPosition":["Připoj kotníkovou manžetu ke spodnímu vývodu kladky a připni ji na nohu blíže stroji. Stůj bokem na pevné podlaze, drž pevné madlo a mírně povol stojné koleno. Nastav odstup tak, aby lanko mělo volnou dráhu.","Connect an ankle cuff to the low pulley and fasten it to the leg nearest the machine. Stand side-on on a firm floor, hold a fixed handle and soften the supporting knee. Choose a distance that gives the cable a clear path."],"execution":["Přitáhni připnutou nohu ke středu a jen mírně před stojnou nohu. Pomalu ji vrať do strany, pánev nech klidnou. Přitažení a návrat jsou jedno opakování připnuté nohy. Po sérii vystřídej stranu.","Draw the attached leg inward and just in front of the supporting leg. Return it slowly to the side with a steady pelvis. One inward movement and return is one repetition of the attached leg. Change sides after the set."],"watchFor":["Manžeta musí držet a lanko se nesmí zachytávat o stojnou nohu; nepohybuj se švihem. Zapisuj nastavenou zátěž stejné kladky zvlášť pro každou stranu. Číslo na závaží není odhad síly u kotníku.","Secure the cuff and keep the cable clear of the supporting leg; avoid swinging. Record the selected load on the same pulley separately for each side. The stack reading is not an estimate of force at the ankle."]},"progression":["Lehčí: menší odpor a kratší rozsah; stroj vsedě je jiný úkol s větší oporou. Náročnější: malý přírůstek zátěže při stejné poloze a kladce. Opora ruky může zůstat.","Easier: less resistance and a shorter range; the seated machine is a different task with more support. More demanding: a small load increase with the same setup and pulley. Hand support may stay."]}}},"ex26_side_adduction":{"id":"ex26_side_adduction","segment":"D","edits":{"cz":"Přinožování spodní nohy vleže na boku","exe":["Zvedni spodní nataženou nohu kousek nad podlahu a pomalu ji vrať. Pánev nepřetáčej kvůli většímu zdvihu. Zdvih a návrat jsou jedno opakování spodní nohy; po sérii se otoč a vystřídej stranu.","Lift the straight lower leg just clear of the floor, then lower it slowly. Do not roll the pelvis to lift higher. One lift and return is one repetition of the lower leg; turn over and change sides after the set."],"pro":["Lehčí: menší zdvih a opora horní dlaně před tělem. Náročnější: pomalejší návrat nebo krátká pauza nahoře. Tato karta používá vlastní váhu; přidanou zátěž nebo jinou oporu zaznamenej jako odlišné provedení.","Easier: a smaller lift and the upper palm supporting you in front. More demanding: slower lowering or a brief pause at the top. This card uses bodyweight; record added load or a different support as a separate execution setup."],"equipmentDetail":["Bez povinné pomůcky, na pevné podlaze; podložka a podložení hlavy jsou volitelné. Horní pokrčená noha poskytuje oporu, pracuje spodní natažená noha.","No required equipment, on a firm floor; a mat and head support are optional. The bent upper leg provides support while the straight lower leg works."],"source":{"author":"American Academy of Orthopaedic Surgeons","document":"Hip Conditioning Program — Hip Adduction","url":"https://www.orthoinfo.org/recovery/hip-conditioning-program/","scope":"Supports the specific crossed, bent upper-leg setup shown in this card. General exercise adaptation: no injury designation, rehabilitation dose, added-weight prescription or clinical benefit is imported. The prior ACE page describes a different two-straight-leg setup and is retained only in the review baseline."}},"taxonomy":{"regions":["thighs"],"secondaryRegions":["trunk"],"movements":["joint"],"focus":["strength"],"positions":["side_lying"],"supports":[],"equipmentRequirements":[["telo"]],"priority":1,"aliases":["Přitahování spodní nohy vleže na boku","side lying lower leg raise"]},"policy":{"id":"ex26_side_adduction","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_side_adduction-fe442baa1dc1a5db.mp4"]},"art":{"appId":"ex26_side_adduction","atlasId":"ex26_side_adduction","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"092143a942700a499c6046319aa838baaffdff489b010021d808fdd70bfbf493","thumb":"/expansion-atlas/ex26_side_adduction-original-256.webp","detail":"/expansion-atlas/ex26_side_adduction-original-960.webp","inkThumb":"/expansion-atlas/ex26_side_adduction-ink-256.webp","inkDetail":"/expansion-atlas/ex26_side_adduction-ink-960.webp","fillThumb":"/expansion-atlas/ex26_side_adduction-fill-256.webp","fillDetail":"/expansion-atlas/ex26_side_adduction-fill-960.webp"},"sourceSha256":"092143a942700a499c6046319aa838baaffdff489b010021d808fdd70bfbf493","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"24eadf73832d9b71":{"fields":{"id":"ex26_side_adduction","cz":"Přinožování spodní nohy vleže na boku","en":"Side-Lying Hip Adduction","pat":"ohyb","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Zvedni spodní nohu několik centimetrů, krátce zastav a pomalu ji polož.","Lift the lower leg a few centimetres, pause briefly and lower slowly."],"startPosition":["Lehni na bok a podepři hlavu. Spodní nohu natáhni, horní koleno pokrč a horní chodidlo polož na zem před spodní koleno. Pánev drž bez přetáčení.","Lie on your side with the head supported. Straighten the lower leg, bend the upper knee and place its foot on the floor in front of the lower knee. Keep the pelvis from rolling."],"execution":["Zvedni spodní nataženou nohu kousek nad podlahu a pomalu ji vrať. Pánev nepřetáčej kvůli většímu zdvihu. Zdvih a návrat jsou jedno opakování spodní nohy; po sérii se otoč a vystřídej stranu.","Lift the straight lower leg just clear of the floor, then lower it slowly. Do not roll the pelvis to lift higher. One lift and return is one repetition of the lower leg; turn over and change sides after the set."],"watchFor":["Neotáčej pánev dozadu a nezvedej nohu za cenu úklonu trupu.","Do not roll the pelvis backward or lift by side-bending the trunk."]},"progression":["Lehčí: menší zdvih a opora horní dlaně před tělem. Náročnější: pomalejší návrat nebo krátká pauza nahoře. Tato karta používá vlastní váhu; přidanou zátěž nebo jinou oporu zaznamenej jako odlišné provedení.","Easier: a smaller lift and the upper palm supporting you in front. More demanding: slower lowering or a brief pause at the top. This card uses bodyweight; record added load or a different support as a separate execution setup."]}}},"ex26_copenhagen_short":{"id":"ex26_copenhagen_short","segment":"D","edits":{"cz":"Kodaňská výdrž s oporou kolena","en":"Knee-Supported Copenhagen Hold","foc":["Tlač horní opřenou nohou do lavice a drž pánev v linii trupu.","Press the upper supported leg into the bench and hold the pelvis in line with the torso."],"pos":["Lehni bokem k nízké pevné lavici, která se neposune ani nepřevrátí. Vnitřní stranu horního pokrčeného kolena a přilehlého stehna opři o polstrovaný vršek; spodní předloktí polož na zem s loktem pod ramenem.","Lie beside a low stable bench that cannot slide or tip. Support the inside of the bent upper knee and adjacent thigh on its padded top; place the lower forearm on the floor with the elbow under the shoulder."],"exe":["Tlakem horní nohy do opory zvedni pánev a spodní nohu přibliž k horní. Drž bez přetáčení pánve a klidně dýchej; potom se pomalu polož. Zapisuj sekundy výdrže na stranu horní opřené nohy. Po sérii stranu vystřídej.","Press the upper leg into the support to raise the pelvis and bring the lower leg toward it. Hold without rotating the pelvis and breathe calmly, then lower slowly. Record hold seconds for the side of the upper supported leg. Change sides after the set."],"wat":["Opora má být široká a měkká, bez bodového tlaku či bolesti kolena. Při bolesti třísla nebo ramene se vrať na zem. Delší výdrž nenahrazuje klidnou polohu a dech.","Use broad, padded contact without focal pressure or knee pain. Return to the floor if the groin or shoulder hurts. A longer hold does not replace a steady position and breathing."],"pro":["Lehčí: kratší výdrž a dopomoc spodní nohy ze země. Náročnější: menší dopomoc při stejné opoře. Dlouhá páka s oporou kotníku je samostatný cvik; výsledky těchto provedení přímo neporovnávej.","Easier: a shorter hold with assistance from the lower leg on the floor. More demanding: less assistance with the same support. The ankle-supported long lever is a separate exercise; do not directly compare results between these setups."],"equipmentDetail":["Nízká stabilní lavice nebo bedna s dostatečnou polstrovanou plochou pro horní koleno a část stehna. Tvrdou plochu lze vypodložit složeným ručníkem; podložka pod předloktí je volitelná.","A low stable bench or box with enough padded surface for the upper knee and adjacent thigh. A folded towel can pad a hard surface; a mat under the forearm is optional."],"source":{"author":"The Prehab Guys","document":"Copenhagen Plank — On Knees","url":"https://library.theprehabguys.com/vimeo-video/copenhagen-plank-on-knee/","scope":"The source teaches repeated hip lifts and lowers with the upper knee supported. This existing Tanmay card is the isometric hold adaptation; its duration measurement is retained. No repetition-to-seconds conversion or clinical outcome claim."}},"taxonomy":{"regions":["thighs"],"secondaryRegions":["trunk","shoulders"],"movements":["joint","trunk_stability"],"focus":["strength"],"positions":["side_support"],"supports":["chair_bench","forearm_support"],"equipmentRequirements":[["lavice","flat_bench","box_support"]],"priority":2,"aliases":["Kodaňské prkno s oporou kolena","Short-Lever Copenhagen Plank","short lever Copenhagen hold","knee-supported Copenhagen plank"]},"policy":{"id":"ex26_copenhagen_short","measurementType":"DURATION","loadMode":"none","sideMode":"perSide","requirements":[["lavice","flat_bench","box_support"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_copenhagen_short","atlasId":"ex26_copenhagen_short","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"31f9657e82496cb2f2aed39766c42ef0d92de7a074a85086cee85b7200c06920","thumb":"/expansion-atlas/ex26_copenhagen_short-audit20261013-original-256.webp","detail":"/expansion-atlas/ex26_copenhagen_short-audit20261013-original-960.webp","inkThumb":"/expansion-atlas/ex26_copenhagen_short-audit20261013-ink-256.webp","inkDetail":"/expansion-atlas/ex26_copenhagen_short-audit20261013-ink-960.webp","fillThumb":"/expansion-atlas/ex26_copenhagen_short-audit20261013-fill-256.webp","fillDetail":"/expansion-atlas/ex26_copenhagen_short-audit20261013-fill-960.webp"},"sourceSha256":"31f9657e82496cb2f2aed39766c42ef0d92de7a074a85086cee85b7200c06920","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"0d26532789e054ed":{"fields":{"id":"ex26_copenhagen_short","cz":"Kodaňská výdrž s oporou kolena","en":"Knee-Supported Copenhagen Hold","pat":"stred","eq":["lavice"],"measurementType":"DURATION","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Tlač horní opřenou nohou do lavice a drž pánev v linii trupu.","Press the upper supported leg into the bench and hold the pelvis in line with the torso."],"startPosition":["Lehni bokem k nízké pevné lavici, která se neposune ani nepřevrátí. Vnitřní stranu horního pokrčeného kolena a přilehlého stehna opři o polstrovaný vršek; spodní předloktí polož na zem s loktem pod ramenem.","Lie beside a low stable bench that cannot slide or tip. Support the inside of the bent upper knee and adjacent thigh on its padded top; place the lower forearm on the floor with the elbow under the shoulder."],"execution":["Tlakem horní nohy do opory zvedni pánev a spodní nohu přibliž k horní. Drž bez přetáčení pánve a klidně dýchej; potom se pomalu polož. Zapisuj sekundy výdrže na stranu horní opřené nohy. Po sérii stranu vystřídej.","Press the upper leg into the support to raise the pelvis and bring the lower leg toward it. Hold without rotating the pelvis and breathe calmly, then lower slowly. Record hold seconds for the side of the upper supported leg. Change sides after the set."],"watchFor":["Opora má být široká a měkká, bez bodového tlaku či bolesti kolena. Při bolesti třísla nebo ramene se vrať na zem. Delší výdrž nenahrazuje klidnou polohu a dech.","Use broad, padded contact without focal pressure or knee pain. Return to the floor if the groin or shoulder hurts. A longer hold does not replace a steady position and breathing."]},"progression":["Lehčí: kratší výdrž a dopomoc spodní nohy ze země. Náročnější: menší dopomoc při stejné opoře. Dlouhá páka s oporou kotníku je samostatný cvik; výsledky těchto provedení přímo neporovnávej.","Easier: a shorter hold with assistance from the lower leg on the floor. More demanding: less assistance with the same support. The ankle-supported long lever is a separate exercise; do not directly compare results between these setups."]}}},"hipcars":{"id":"hipcars","segment":"E","edits":{"cz":"Kontrolovaný kruh kyčlí ve stoji s oporou","en":"Supported Standing Hip CAR","pos":["Přidrž se pevné opory a přenes váhu na jednu nohu. Trup drž klidný, stojné koleno nezamykej a druhé koleno pokrč.","Hold a stable support and shift weight onto one leg. Keep the trunk steady, avoid locking the standing knee and bend the other knee."],"exe":["Zvedni pokrčené koleno vpřed a otevři ho do strany. Otáčej stehno v kyčli tak, aby se chodidlo zvedalo za tebe, a veď koleno dozadu, dolů a zpět vedle stojné nohy. Jeden celý okruh je jedno opakování. Nacvič také opačný směr a druhou nohu podle plánu.","Lift the bent knee forward and open it to the side. Rotate the thigh in the hip so the foot rises behind you, then guide the knee back, down and beside the standing leg. One complete circle is one repetition. Practice the reverse direction and other leg as planned."],"wat":["Kruh zmenši, pokud se kvůli němu otáčí pánev nebo prohýbají bedra. Nepřetlačuj sevření či bolest v kyčli a nezadržuj dech. Směr mění kyčel, ne kroucení kolena.","Make the circle smaller if the pelvis turns or the lower back arches to gain range. Do not force through hip pinching or pain, and keep breathing. Turn from the hip rather than twisting the knee."],"pro":["Lehčí: menší kruh a jistější opora. Náročnější: plynulejší nebo pomalejší kruh ve stejném zvládnutém rozsahu. Větší rozsah není povinný další krok.","Easier: a smaller circle and firmer support. More demanding: a smoother or slower circle within the same controlled range. A larger range is not a required next step."],"foc":["Pomalu obkružuj kyčel zvednuté nohy, pánev nech klidnou.","Slowly circle the raised hip while keeping the pelvis steady."],"equipmentDetail":["Zeď nebo pevná opora pro ruku, případně stabilní židle zajištěná proti posunutí. Opora je součástí této varianty; žádná přídavná zátěž.","A wall or fixed hand support, or a stable chair secured against sliding. Support is part of this version; no added load."],"source":{"author":"Strive & Uplift","document":"Exercise Demo — Standing Hip CARs","url":"https://vimeo.com/378944380","scope":"Independent supported adaptation of publicly available written instructions. No video-specific cues, tension percentage, treatment claim or prescribed dose imported."}},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility","coordination"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["telo"],["zed","fixed_support","chair"]],"priority":2,"aliases":["hip CARs","controlled articular rotation","kontrolované kroužení kyčlí","standing hip circle"]},"policy":{"id":"hipcars","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["telo"],["zed","fixed_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_rotation_control"},"art":{"appId":"hipcars","atlasId":"hipcars","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"b8d6f43751f9202e7c25204e91b07a54d02c3b2735ccb78c65894303c3e3f446","thumb":"/unified-atlas/hipcars-c64c95d7e28bc7be-thumb.webp","detail":"/unified-atlas/hipcars-0851fa19ead1de31-detail.webp","inkThumb":"/unified-atlas/hipcars-cc35b16b47eecaa6-inkThumb.webp","inkDetail":"/unified-atlas/hipcars-ae29ada70b25be5a-inkDetail.webp","fillThumb":"/unified-atlas/hipcars-b5e751a7cfbf7441-fillThumb.webp","fillDetail":"/unified-atlas/hipcars-7670069e08ded4c8-fillDetail.webp"},"sourceSha256":"b8d6f43751f9202e7c25204e91b07a54d02c3b2735ccb78c65894303c3e3f446","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"0fa0b39af9c11158":{"fields":{"id":"hipcars","cz":"Kontrolovaný kruh kyčlí ve stoji s oporou","en":"Supported Standing Hip CAR","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Pomalu obkružuj kyčel zvednuté nohy, pánev nech klidnou.","Slowly circle the raised hip while keeping the pelvis steady."],"startPosition":["Přidrž se pevné opory a přenes váhu na jednu nohu. Trup drž klidný, stojné koleno nezamykej a druhé koleno pokrč.","Hold a stable support and shift weight onto one leg. Keep the trunk steady, avoid locking the standing knee and bend the other knee."],"execution":["Zvedni pokrčené koleno vpřed a otevři ho do strany. Otáčej stehno v kyčli tak, aby se chodidlo zvedalo za tebe, a veď koleno dozadu, dolů a zpět vedle stojné nohy. Jeden celý okruh je jedno opakování. Nacvič také opačný směr a druhou nohu podle plánu.","Lift the bent knee forward and open it to the side. Rotate the thigh in the hip so the foot rises behind you, then guide the knee back, down and beside the standing leg. One complete circle is one repetition. Practice the reverse direction and other leg as planned."],"watchFor":["Kruh zmenši, pokud se kvůli němu otáčí pánev nebo prohýbají bedra. Nepřetlačuj sevření či bolest v kyčli a nezadržuj dech. Směr mění kyčel, ne kroucení kolena.","Make the circle smaller if the pelvis turns or the lower back arches to gain range. Do not force through hip pinching or pain, and keep breathing. Turn from the hip rather than twisting the knee."]},"progression":["Lehčí: menší kruh a jistější opora. Náročnější: plynulejší nebo pomalejší kruh ve stejném zvládnutém rozsahu. Větší rozsah není povinný další krok.","Easier: a smaller circle and firmer support. More demanding: a smoother or slower circle within the same controlled range. A larger range is not a required next step."]}}},"ex26_gate_opener":{"id":"ex26_gate_opener","segment":"E","edits":{"cz":"Otevírání kyčle ve stoji s oporou","en":"Supported Standing Hip Gate Opener","hd":null,"pos":["Stůj vzpřímeně u pevné opory a přidrž se jednou rukou. Odlehči druhou nohu a zvedni pokrčené koleno před sebe do pohodlné výšky.","Stand upright beside a fixed support and hold it with one hand. Unload the other leg and lift its bent knee in front to a comfortable height."],"exe":["Veď zvednuté koleno krátce přes střed těla, pak zpět ven do strany a polož chodidlo na zem. Celá tato sekvence je jedno opakování na pohybující se nohu. Druhou stranu proveď podle plánu.","Move the raised knee a short distance across the body, then back outward to the side and lower the foot. This whole sequence is one repetition for the moving leg. Perform the other side as planned."],"wat":["Stojné chodidlo zůstává na místě a pánev se neotáčí spolu s kolenem. Koleno nemusí být ve výšce kyčle; zvol malý pohodlný oblouk bez sevření v třísle.","Keep the standing foot in place and avoid turning the pelvis with the knee. The knee need not reach hip height; choose a small comfortable arc without groin pinching."],"pro":["Lehčí: nižší koleno, kratší oblouk a pevnější opora. Náročnější: pomalejší vedení kolena při stejném klidu trupu. Celý kruh kyčlí je jiný nácvik, nikoli povinné pokračování.","Easier: a lower knee, shorter arc and firmer support. More demanding: slower knee movement with the same steady trunk. A full hip circle is a different drill, not a required progression."],"foc":["Pokrčené koleno dovnitř a ven; pánev klidná.","Bent knee inward and outward; keep the pelvis steady."],"equipmentDetail":["Zeď nebo pevná opora pro ruku, případně stabilní židle zajištěná proti posunutí. Opora je součástí této varianty; žádná přídavná zátěž.","A wall or fixed hand support, or a stable chair secured against sliding. Support is part of this version; no added load."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility","coordination"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["telo"],["zed","fixed_support","chair"]],"priority":1,"aliases":["gate opener","otevírání kyčlí"]},"policy":{"id":"ex26_gate_opener","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"],["zed","fixed_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_gate_opener-e6547b851fa99f17.mp4"]},"art":{"appId":"ex26_gate_opener","atlasId":"ex26_gate_opener","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"f1f07f1d74adc53880f0ed55c66dbedef0f5e945653e1cd5c00cec359ee2f92b","thumb":"/expansion-atlas/ex26_gate_opener-original-256.webp","detail":"/expansion-atlas/ex26_gate_opener-original-960.webp","inkThumb":"/expansion-atlas/ex26_gate_opener-ink-256.webp","inkDetail":"/expansion-atlas/ex26_gate_opener-ink-960.webp","fillThumb":"/expansion-atlas/ex26_gate_opener-fill-256.webp","fillDetail":"/expansion-atlas/ex26_gate_opener-fill-960.webp"},"sourceSha256":"f1f07f1d74adc53880f0ed55c66dbedef0f5e945653e1cd5c00cec359ee2f92b","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"7ec4413aaa351c3e":{"fields":{"id":"ex26_gate_opener","cz":"Otevírání kyčle ve stoji s oporou","en":"Supported Standing Hip Gate Opener","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"perSide","focus":["Pokrčené koleno dovnitř a ven; pánev klidná.","Bent knee inward and outward; keep the pelvis steady."],"startPosition":["Stůj vzpřímeně u pevné opory a přidrž se jednou rukou. Odlehči druhou nohu a zvedni pokrčené koleno před sebe do pohodlné výšky.","Stand upright beside a fixed support and hold it with one hand. Unload the other leg and lift its bent knee in front to a comfortable height."],"execution":["Veď zvednuté koleno krátce přes střed těla, pak zpět ven do strany a polož chodidlo na zem. Celá tato sekvence je jedno opakování na pohybující se nohu. Druhou stranu proveď podle plánu.","Move the raised knee a short distance across the body, then back outward to the side and lower the foot. This whole sequence is one repetition for the moving leg. Perform the other side as planned."],"watchFor":["Stojné chodidlo zůstává na místě a pánev se neotáčí spolu s kolenem. Koleno nemusí být ve výšce kyčle; zvol malý pohodlný oblouk bez sevření v třísle.","Keep the standing foot in place and avoid turning the pelvis with the knee. The knee need not reach hip height; choose a small comfortable arc without groin pinching."]},"progression":["Lehčí: nižší koleno, kratší oblouk a pevnější opora. Náročnější: pomalejší vedení kolena při stejném klidu trupu. Celý kruh kyčlí je jiný nácvik, nikoli povinné pokračování.","Easier: a lower knee, shorter arc and firmer support. More demanding: slower knee movement with the same steady trunk. A full hip circle is a different drill, not a required progression."]}}},"ex26_hip_airplane":{"id":"ex26_hip_airplane","segment":"E","edits":{"pos":["Přidrž se pevné opory a předkloň se z kyčle na jedné noze. Druhou nohu veď dozadu, stojné koleno mírně pokrč. Zvol jen takový předklon, ve kterém se udržíš bez záklonu beder.","Hold a stable support and hinge over one leg. Reach the other leg behind and soften the standing knee. Use only a hinge depth you can maintain without arching the lower back."],"exe":["Pomalu otevři pánev ke straně zvednuté nohy a potom ji otoč zpět směrem k podlaze. Hrudník, pánev a volná noha se otáčejí společně kolem kyčle stojné nohy. Otevření a návrat jsou jedno opakování; zaznamenaná strana označuje stojnou nohu.","Slowly open the pelvis toward the raised-leg side, then turn it back toward the floor. Chest, pelvis and free leg turn together around the standing hip. One opening and return is one repetition; the recorded side refers to the standing leg."],"wat":["Stojné chodidlo nech na podlaze, koleno nesmí vynucovat rotaci místo kyčle. Netáhni se za oporu do většího rozsahu a neotáčej pouze rameny. Menší předklon i malá rotace stačí.","Keep the standing foot grounded; do not force rotation through the knee instead of the hip. Do not pull on the support to gain range or turn only the shoulders. A shallower hinge and small rotation are enough."],"pro":["Lehčí: více opory, menší předklon a menší rotace. Náročnější: pomalejší návrat při stejné opoře. Verzi bez opory řeš zvlášť; není nutné k ní přecházet.","Easier: more support, a shallower hinge and a smaller rotation. More demanding: a slower return with the same support. Treat an unsupported version separately; progressing to it is optional."],"equipmentDetail":["Zeď nebo pevná opora pro ruku, případně stabilní židle zajištěná proti posunutí. Opora je součástí této varianty; žádná přídavná zátěž.","A wall or fixed hand support, or a stable chair secured against sliding. Support is part of this version; no added load."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["trunk","thighs"],"movements":["joint","balance"],"focus":["coordination","mobility"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["telo"],["zed","fixed_support","chair"]],"priority":2,"aliases":["hip airplane","letadlo","rotace na stojné kyčli"]},"policy":{"id":"ex26_hip_airplane","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"],["zed","fixed_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_hip_airplane","atlasId":"ex26_hip_airplane","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"220c455bcc9a7826b0865c48fc06d1abf8c18d46110f9d4a9ac984fd62083761","thumb":"/expansion-atlas/ex26_hip_airplane-original-256.webp","detail":"/expansion-atlas/ex26_hip_airplane-original-960.webp","inkThumb":"/expansion-atlas/ex26_hip_airplane-ink-256.webp","inkDetail":"/expansion-atlas/ex26_hip_airplane-ink-960.webp","fillThumb":"/expansion-atlas/ex26_hip_airplane-fill-256.webp","fillDetail":"/expansion-atlas/ex26_hip_airplane-fill-960.webp"},"sourceSha256":"220c455bcc9a7826b0865c48fc06d1abf8c18d46110f9d4a9ac984fd62083761","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"3db6d348f6468a77":{"fields":{"id":"ex26_hip_airplane","cz":"Rotace pánve ve stoji jednonož s oporou","en":"Supported Hip Airplane","pat":"mobilita","eq":["telo","zed"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"perSide","focus":["Pomalu otevírej a zavírej pánev kolem kyčle stojné nohy.","Slowly open and close the pelvis around the supporting hip."],"startPosition":["Přidrž se pevné opory a předkloň se z kyčle na jedné noze. Druhou nohu veď dozadu, stojné koleno mírně pokrč. Zvol jen takový předklon, ve kterém se udržíš bez záklonu beder.","Hold a stable support and hinge over one leg. Reach the other leg behind and soften the standing knee. Use only a hinge depth you can maintain without arching the lower back."],"execution":["Pomalu otevři pánev ke straně zvednuté nohy a potom ji otoč zpět směrem k podlaze. Hrudník, pánev a volná noha se otáčejí společně kolem kyčle stojné nohy. Otevření a návrat jsou jedno opakování; zaznamenaná strana označuje stojnou nohu.","Slowly open the pelvis toward the raised-leg side, then turn it back toward the floor. Chest, pelvis and free leg turn together around the standing hip. One opening and return is one repetition; the recorded side refers to the standing leg."],"watchFor":["Stojné chodidlo nech na podlaze, koleno nesmí vynucovat rotaci místo kyčle. Netáhni se za oporu do většího rozsahu a neotáčej pouze rameny. Menší předklon i malá rotace stačí.","Keep the standing foot grounded; do not force rotation through the knee instead of the hip. Do not pull on the support to gain range or turn only the shoulders. A shallower hinge and small rotation are enough."]},"progression":["Lehčí: více opory, menší předklon a menší rotace. Náročnější: pomalejší návrat při stejné opoře. Verzi bez opory řeš zvlášť; není nutné k ní přecházet.","Easier: more support, a shallower hinge and a smaller rotation. More demanding: a slower return with the same support. Treat an unsupported version separately; progressing to it is optional."]}}},"ex26_mob_leg_swing_sagittal":{"id":"ex26_mob_leg_swing_sagittal","segment":"E","edits":{"pos":["Stůj vedle pevné opory, lehce se přidrž a odlehči jednu nohu. Nech si před ní i za ní volný prostor, stojné koleno nezamykej.","Stand beside a fixed support, hold lightly and unload one leg. Leave space in front and behind it, and avoid locking the standing knee."],"exe":["Kývej volnou nohou plynule vpřed a vzad z kyčle, koleno zůstává téměř natažené. Začni malým obloukem. Jeden pohyb vpřed a zpět je jedno opakování na pohybující se nohu; potom vystřídej stranu podle plánu.","Swing the free leg smoothly forward and backward from the hip, keeping the knee nearly straight. Begin with a small arc. One forward-and-back cycle is one repetition for the moving leg; then change sides as planned."],"wat":["Nesnaž se nohu vykopnout vysoko. Pokud se trup zaklání nebo předklání s nohou, zmenši oblouk. Kývání má být plynulé, ne trhavé.","Do not try to kick the leg high. Reduce the arc if the trunk leans backward or forward with the leg. Keep the swing smooth rather than jerky."],"pro":["Lehčí: menší a klidnější oblouk. Podle pocitu můžeš rozsah mírně zvětšit, pokud se trup stále nekývá. Maximální výška ani přídavná zátěž nejsou cílem.","Easier: a smaller, gentler arc. You may increase the range slightly if comfortable and the trunk stays steady. Maximum height and added load are not the goal."],"foc":["Plynule vpřed a vzad, trup klidný.","Smoothly forward and back, with a steady trunk."],"equipmentDetail":["Zeď nebo pevná opora pro ruku, případně stabilní židle zajištěná proti posunutí. Opora je součástí této varianty; žádná přídavná zátěž.","A wall or fixed hand support, or a stable chair secured against sliding. Support is part of this version; no added load."],"source":{"author":"John M. Cissik","document":"Specific Warm Ups and Strength Training","url":"https://www.cissik.com/blog/2021/12/specific-warm-ups-and-strength-training/","scope":"Original first-person warm-up instructions: supported front-to-back leg swings. Independent wording and count convention; no injury-prevention claim or fixed dose imported."}},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["telo"],["zed","fixed_support","chair"]],"priority":1,"aliases":["front to back leg swing","sagittal leg swing","kývání nohou vpřed vzad"]},"policy":{"id":"ex26_mob_leg_swing_sagittal","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"],["zed","fixed_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_flexion_extension_control"},"art":{"appId":"ex26_mob_leg_swing_sagittal","atlasId":"ex26_mob_leg_swing_sagittal","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"c2ab4f970574d0d4e1ff5dd64f2ddf4165f6645b46340a6e209fb126a2547259","thumb":"/expansion-atlas/ex26_mob_leg_swing_sagittal-original-256.webp","detail":"/expansion-atlas/ex26_mob_leg_swing_sagittal-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_leg_swing_sagittal-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_leg_swing_sagittal-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_leg_swing_sagittal-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_leg_swing_sagittal-fill-960.webp"},"sourceSha256":"c2ab4f970574d0d4e1ff5dd64f2ddf4165f6645b46340a6e209fb126a2547259","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"8709ddaa8905f46a":{"fields":{"id":"ex26_mob_leg_swing_sagittal","cz":"Kontrolované kývání nohou vpřed a vzad","en":"Supported Front-to-Back Leg Swing","pat":"mobilita","eq":["zed"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Plynule vpřed a vzad, trup klidný.","Smoothly forward and back, with a steady trunk."],"startPosition":["Stůj vedle pevné opory, lehce se přidrž a odlehči jednu nohu. Nech si před ní i za ní volný prostor, stojné koleno nezamykej.","Stand beside a fixed support, hold lightly and unload one leg. Leave space in front and behind it, and avoid locking the standing knee."],"execution":["Kývej volnou nohou plynule vpřed a vzad z kyčle, koleno zůstává téměř natažené. Začni malým obloukem. Jeden pohyb vpřed a zpět je jedno opakování na pohybující se nohu; potom vystřídej stranu podle plánu.","Swing the free leg smoothly forward and backward from the hip, keeping the knee nearly straight. Begin with a small arc. One forward-and-back cycle is one repetition for the moving leg; then change sides as planned."],"watchFor":["Nesnaž se nohu vykopnout vysoko. Pokud se trup zaklání nebo předklání s nohou, zmenši oblouk. Kývání má být plynulé, ne trhavé.","Do not try to kick the leg high. Reduce the arc if the trunk leans backward or forward with the leg. Keep the swing smooth rather than jerky."]},"progression":["Lehčí: menší a klidnější oblouk. Podle pocitu můžeš rozsah mírně zvětšit, pokud se trup stále nekývá. Maximální výška ani přídavná zátěž nejsou cílem.","Easier: a smaller, gentler arc. You may increase the range slightly if comfortable and the trunk stays steady. Maximum height and added load are not the goal."]}}},"ex26_mob_leg_swing_lateral":{"id":"ex26_mob_leg_swing_lateral","segment":"E","edits":{"pos":["Stůj čelem k pevné opoře, přidrž se oběma rukama a odlehči jednu nohu. Nech dost místa, aby před stojnou nohou i do strany prošla bez překážky.","Face a fixed support, hold it with both hands and unload one leg. Leave room for it to pass in front of the standing leg and out to the side."],"exe":["Kývej volnou nohou do strany a zpět mírně přes střed těla před stojnou nohou. Koleno nech téměř natažené, pánev přibližně čelem k opoře. Jeden pohyb ven a zpět je jedno opakování na pohybující se nohu; pak vystřídej stranu podle plánu.","Swing the free leg out to the side and back slightly across the body in front of the standing leg. Keep the knee nearly straight and pelvis roughly facing the support. One outward-and-back cycle is one repetition for the moving leg; then change sides as planned."],"wat":["Nesnaž se dosáhnout výšky úklonem ani otáčením stojného chodidla. Zmenši oblouk, pokud pohyb tahá trup do stran nebo vyvolává nepříjemné sevření.","Do not gain height by side-bending or turning the standing foot. Reduce the arc if it pulls the trunk sideways or causes uncomfortable pinching."],"pro":["Lehčí: malý pomalý oblouk. Plynulejší nebo mírně širší pohyb může následovat jen při zachované kontrole a pohodlí. Opora zůstává součástí varianty.","Easier: a small, slow arc. A smoother or slightly wider movement is optional while control and comfort remain. Support remains part of this version."],"foc":["Noha ven a přes střed, pánev stále k opoře.","Leg outward and across, pelvis still facing the support."],"equipmentDetail":["Zeď nebo pevná opora pro ruku, případně stabilní židle zajištěná proti posunutí. Opora je součástí této varianty; žádná přídavná zátěž.","A wall or fixed hand support, or a stable chair secured against sliding. Support is part of this version; no added load."],"source":{"author":"SOS Orthopedic and Sports Therapy","document":"Dynamic Golf Warm-up — Leg Swing: Side","url":"https://www.sosbones.com/media/1449/golfdynamicwarmup.pdf","scope":"Primary therapy handout: facing wall support and medial-to-lateral swing in front of the body. Independent gentle adaptation; no mandatory full swing, ankle angle, golf program or fixed dose imported."}},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility"],"positions":["standing"],"supports":["hand_support"],"equipmentRequirements":[["telo"],["zed","fixed_support","chair"]],"priority":1,"aliases":["side to side leg swing","lateral leg swing","kývání nohou do stran"]},"policy":{"id":"ex26_mob_leg_swing_lateral","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"],["zed","fixed_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_abduction_adduction_control"},"art":{"appId":"ex26_mob_leg_swing_lateral","atlasId":"ex26_mob_leg_swing_lateral","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"95f5500385f60aac6699953ac774a5b5227a4096e659473a99c2869350a61dcd","thumb":"/expansion-atlas/ex26_mob_leg_swing_lateral-original-256.webp","detail":"/expansion-atlas/ex26_mob_leg_swing_lateral-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_leg_swing_lateral-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_leg_swing_lateral-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_leg_swing_lateral-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_leg_swing_lateral-fill-960.webp"},"sourceSha256":"95f5500385f60aac6699953ac774a5b5227a4096e659473a99c2869350a61dcd","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"e34e10f96a31f185":{"fields":{"id":"ex26_mob_leg_swing_lateral","cz":"Kontrolované kývání nohou do stran","en":"Supported Side-to-Side Leg Swing","pat":"mobilita","eq":["zed"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Noha ven a přes střed, pánev stále k opoře.","Leg outward and across, pelvis still facing the support."],"startPosition":["Stůj čelem k pevné opoře, přidrž se oběma rukama a odlehči jednu nohu. Nech dost místa, aby před stojnou nohou i do strany prošla bez překážky.","Face a fixed support, hold it with both hands and unload one leg. Leave room for it to pass in front of the standing leg and out to the side."],"execution":["Kývej volnou nohou do strany a zpět mírně přes střed těla před stojnou nohou. Koleno nech téměř natažené, pánev přibližně čelem k opoře. Jeden pohyb ven a zpět je jedno opakování na pohybující se nohu; pak vystřídej stranu podle plánu.","Swing the free leg out to the side and back slightly across the body in front of the standing leg. Keep the knee nearly straight and pelvis roughly facing the support. One outward-and-back cycle is one repetition for the moving leg; then change sides as planned."],"watchFor":["Nesnaž se dosáhnout výšky úklonem ani otáčením stojného chodidla. Zmenši oblouk, pokud pohyb tahá trup do stran nebo vyvolává nepříjemné sevření.","Do not gain height by side-bending or turning the standing foot. Reduce the arc if it pulls the trunk sideways or causes uncomfortable pinching."]},"progression":["Lehčí: malý pomalý oblouk. Plynulejší nebo mírně širší pohyb může následovat jen při zachované kontrole a pohodlí. Opora zůstává součástí varianty.","Easier: a small, slow arc. A smoother or slightly wider movement is optional while control and comfort remain. Support remains part of this version."]}}},"hip9090":{"id":"hip9090","segment":"F","edits":{"pos":["Sedni na pevnou podlahu s jednou nohou pokrčenou před sebou a druhou do strany za sebou. Kolena jsou přibližně v pravém úhlu; nemusí dosáhnout na zem. Podepři se dlaněmi podle potřeby.","Sit on a firm floor with one leg bent in front and the other to the side behind you. Keep the knees near right angles; they do not have to reach the floor. Support yourself with your hands as needed."],"exe":["Lehce se nakloň z kyčlí nad přední nohu a vrať se. Zvedni kolena a pomalu přesuň obě nohy na druhou stranu; pánev se přitom může otočit a přenést váhu. Zopakuj náklon. Pro nový předpis měř jeden společný interval tohoto střídání včetně krátkých zastavení; delší odpočinek nezapočítávej.","Lean gently from the hips over the front leg and return. Lift the knees and slowly switch both legs to the other side, allowing the pelvis to turn and transfer weight. Repeat the lean. For a new prescription, time one shared interval of this alternating practice, including brief pauses; exclude longer rests."],"wat":["Nenuť obě sedací kosti ani kolena současně na zem. Nezískávej polohu tlakem ruky na koleno nebo kroucením kotníku. Při bolesti kolene či nepříjemném sevření kyčle zmenši rozsah nebo skonči. Starší sekundy a jejich původní význam zůstávají beze změny.","Do not force both sitting bones or knees to the floor at once. Do not press on a knee or twist an ankle to reach the position. Reduce the range or stop for knee pain or uncomfortable hip pinching. Earlier seconds retain their original meaning."],"pro":["Lehčí: ruce za tělem, menší přesed a mělký náklon. Pevné nízké podložení pánve je volitelná úprava. Náročnější: plynulejší přechod s menší pomocí rukou; hlubší náklon není podmínkou.","Easier: place the hands behind you, shorten the switch and keep the lean shallow. Firm low support under the pelvis is an optional modification. More demanding: make the transition smoother with less hand support; a deeper lean is not required."],"source":{"author":"[P]rehab","document":"90/90 Hip Switch Stretch","url":"https://theprehabguys.com/vimeo-video/90-90-hip-switch-stretch/","scope":"Switching the bent legs and leaning over the front leg. The existing timed identity is retained; the source repetition dose and five-second stretch are not adopted. Hand support, comfortable range and the local timing convention are coaching clarifications."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"priority":0,"equipmentRequirements":[["telo"]]},"policy":{"id":"hip9090","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"hip9090","atlasId":"hip9090","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"8e3de732ee64fccc845805da7a6a1fd73bf2fc5a69e7419717b95b7bd4599dfb","thumb":"/unified-atlas/hip9090-5162bde39ac88d45-thumb.webp","detail":"/unified-atlas/hip9090-7a2b7f12772f7cd7-detail.webp","inkThumb":"/unified-atlas/hip9090-120d950f2ed64d1c-inkThumb.webp","inkDetail":"/unified-atlas/hip9090-ddf4c286fd3d0364-inkDetail.webp","fillThumb":"/unified-atlas/hip9090-f0e51b2c4a758b4b-fillThumb.webp","fillDetail":"/unified-atlas/hip9090-a072c045341b30c5-fillDetail.webp"},"sourceSha256":"8e3de732ee64fccc845805da7a6a1fd73bf2fc5a69e7419717b95b7bd4599dfb","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"e8a87bef72d82314":{"fields":{"id":"hip9090","cz":"Kyčle 90/90","en":"90/90 Hip Switch","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Obě kyčle pracují najednou — jedna vnější, druhá vnitřní rotace.","Both hips work at once — one in external, one in internal rotation."],"startPosition":["Sedni na pevnou podlahu s jednou nohou pokrčenou před sebou a druhou do strany za sebou. Kolena jsou přibližně v pravém úhlu; nemusí dosáhnout na zem. Podepři se dlaněmi podle potřeby.","Sit on a firm floor with one leg bent in front and the other to the side behind you. Keep the knees near right angles; they do not have to reach the floor. Support yourself with your hands as needed."],"execution":["Lehce se nakloň z kyčlí nad přední nohu a vrať se. Zvedni kolena a pomalu přesuň obě nohy na druhou stranu; pánev se přitom může otočit a přenést váhu. Zopakuj náklon. Pro nový předpis měř jeden společný interval tohoto střídání včetně krátkých zastavení; delší odpočinek nezapočítávej.","Lean gently from the hips over the front leg and return. Lift the knees and slowly switch both legs to the other side, allowing the pelvis to turn and transfer weight. Repeat the lean. For a new prescription, time one shared interval of this alternating practice, including brief pauses; exclude longer rests."],"watchFor":["Nenuť obě sedací kosti ani kolena současně na zem. Nezískávej polohu tlakem ruky na koleno nebo kroucením kotníku. Při bolesti kolene či nepříjemném sevření kyčle zmenši rozsah nebo skonči. Starší sekundy a jejich původní význam zůstávají beze změny.","Do not force both sitting bones or knees to the floor at once. Do not press on a knee or twist an ankle to reach the position. Reduce the range or stop for knee pain or uncomfortable hip pinching. Earlier seconds retain their original meaning."]},"progression":["Lehčí: ruce za tělem, menší přesed a mělký náklon. Pevné nízké podložení pánve je volitelná úprava. Náročnější: plynulejší přechod s menší pomocí rukou; hlubší náklon není podmínkou.","Easier: place the hands behind you, shorten the switch and keep the lean shallow. Firm low support under the pelvis is an optional modification. More demanding: make the transition smoother with less hand support; a deeper lean is not required."]}}},"shinbox":{"id":"shinbox","segment":"F","edits":{"pos":["Sedni na podlahu s oběma koleny pokrčenými a chodidly před sebou. Přesuň kolena na jednu stranu do přibližné polohy 90/90. Podle potřeby opři dlaně za tělem.","Sit on the floor with both knees bent and the feet in front. Move the knees to one side into an approximate 90/90 position. Place the hands behind you for support as needed."],"exe":["Plynule zvedni obě kolena přes střed a spusť je na druhou stranu. Pánev se může otočit a váha přesunout mezi sedacími kostmi. Pro nový předpis je jeden přesed z jedné krajní polohy do druhé jedno opakování; cesta zpět je druhé.","Smoothly lift both knees through the centre and lower them to the other side. Allow the pelvis to turn and weight to transfer between the sitting bones. For a new prescription, one switch from one end position to the other is one repetition; the return is the second."],"wat":["Přesed nezískávej švihem, tlakem do kolen ani násilným držením pánve na zemi. Pomoc rukou je v pořádku. Zvol pohodlné rozestavení chodidel a rozsah; starší počty nepřepočítávej a nedohaduj k nim stranu.","Do not use momentum, press on the knees or force the pelvis to stay on the floor. Hand support is fine. Choose comfortable foot spacing and range; do not recalculate earlier counts or infer a side for them."],"pro":["Lehčí: menší přesed s oporou rukou. Náročnější: méně pomoci rukou a pomalý přechod. Vztyk do kleku je samostatný cvik; není nutnou součástí tohoto opakování.","Easier: a smaller switch with hand support. More demanding: less help from the hands and a slow transition. Rising to kneeling is a separate exercise and is not required in this repetition."],"source":{"author":"Jair Lee; Craig Liebenson","document":"The shin box get-up (2016), seated rotation portion, pages 450–451","url":"https://firstprinciplesofmovement.com/wp-content/uploads/2020/09/The-shin-box-get-up.pdf","scope":"Only the controlled seated switch and hand-supported regression; the subsequent kneeling/standing sequence and added weights are not adopted. One crossing per repetition is a local new-prescription convention, not a conversion of older records."}},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"priority":2,"equipmentRequirements":[["telo"]]},"policy":{"id":"shinbox","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"shinbox","atlasId":"shinbox","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"0818be705e375f915a41e23e6311f5a4eacd700391b5ddc095543a7ed23d37e3","thumb":"/unified-atlas/shinbox-2cee978d22d3afa6-thumb.webp","detail":"/unified-atlas/shinbox-2cc80a6858e5b378-detail.webp","inkThumb":"/unified-atlas/shinbox-e8247f260c0fc4fa-inkThumb.webp","inkDetail":"/unified-atlas/shinbox-3ea1fbc4d4afb04a-inkDetail.webp","fillThumb":"/unified-atlas/shinbox-3fc217926f33c601-fillThumb.webp","fillDetail":"/unified-atlas/shinbox-d79e71a3f637c054-fillDetail.webp"},"sourceSha256":"0818be705e375f915a41e23e6311f5a4eacd700391b5ddc095543a7ed23d37e3","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"3a07dec03da2b14d":{"fields":{"id":"shinbox","cz":"Přesed 90/90","en":"Shinbox Switch","pat":"mobilita","eq":["telo"],"measurementType":"REPS_ONLY","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Vnitřní a vnější rotace kyčle střídavě.","Internal and external hip rotation, alternating."],"startPosition":["Sedni na podlahu s oběma koleny pokrčenými a chodidly před sebou. Přesuň kolena na jednu stranu do přibližné polohy 90/90. Podle potřeby opři dlaně za tělem.","Sit on the floor with both knees bent and the feet in front. Move the knees to one side into an approximate 90/90 position. Place the hands behind you for support as needed."],"execution":["Plynule zvedni obě kolena přes střed a spusť je na druhou stranu. Pánev se může otočit a váha přesunout mezi sedacími kostmi. Pro nový předpis je jeden přesed z jedné krajní polohy do druhé jedno opakování; cesta zpět je druhé.","Smoothly lift both knees through the centre and lower them to the other side. Allow the pelvis to turn and weight to transfer between the sitting bones. For a new prescription, one switch from one end position to the other is one repetition; the return is the second."],"watchFor":["Přesed nezískávej švihem, tlakem do kolen ani násilným držením pánve na zemi. Pomoc rukou je v pořádku. Zvol pohodlné rozestavení chodidel a rozsah; starší počty nepřepočítávej a nedohaduj k nim stranu.","Do not use momentum, press on the knees or force the pelvis to stay on the floor. Hand support is fine. Choose comfortable foot spacing and range; do not recalculate earlier counts or infer a side for them."]},"progression":["Lehčí: menší přesed s oporou rukou. Náročnější: méně pomoci rukou a pomalý přechod. Vztyk do kleku je samostatný cvik; není nutnou součástí tohoto opakování.","Easier: a smaller switch with hand support. More demanding: less help from the hands and a slow transition. Rising to kneeling is a separate exercise and is not required in this repetition."]}}},"ex26_mob_hip_ir_liftoff":{"id":"ex26_mob_hip_ir_liftoff","segment":"F","edits":{"pos":["Sedni do pohodlné polohy 90/90 a opři dlaně tak, aby ses mohl lehce nadlehčit. Zadní koleno zůstává opřené; jeho chodidlo je pracovní. Přibližné úhly uprav bez tlaku v koleni.","Sit in a comfortable 90/90 position and place your hands where they can support some weight. Keep the rear knee supported; its foot is the working foot. Adjust the approximate angles without pressure in the knee."],"exe":["Pomalu odlehči a zvedni zadní chodidlo malý kousek od země, aniž zvedneš zadní koleno nebo přetočíš celou pánev. Krátce zastav a polož chodidlo. Jeden zdvih a položení je jedno opakování; zapisuj stranu zadní pracovní nohy.","Slowly unload and lift the rear foot a small distance without lifting the rear knee or rolling the whole pelvis. Pause briefly and lower the foot. One lift and lowering is one repetition; record the side of the rear working leg."],"wat":["Výška není cílem. Pokud se místo chodidla zvedá koleno nebo pánev, zmenši pokus. Netlač koleno rukou do podlahy a nevytáčej samotný kotník. Klidně dýchej; při bolesti skonči.","Height is not the goal. Reduce the attempt if the knee or pelvis lifts instead of the foot. Do not push the knee into the floor with a hand or twist only the ankle. Breathe normally and stop if it hurts."],"pro":["Lehčí: více opory rukou, pohodlnější rozestavení nohou a jen odlehčení chodidla bez viditelného zdvihu. Náročnější: krátká kontrolovaná pauza nebo menší pomoc rukou. Zátěž na kotník není součástí základu.","Easier: use more hand support, a more comfortable leg position and simply unload the foot without a visible lift. More demanding: a brief controlled pause or less hand support. An ankle weight is not part of the basic version."],"foc":["Zadní chodidlo se zvedá, zadní koleno zůstává opřené. Pohyb vychází z kyčle.","The rear foot lifts while the rear knee stays supported. Move from the hip."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_hip_ir_liftoff","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_hip_ir_liftoff","atlasId":"ex26_mob_hip_ir_liftoff","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"819fbbe3ae3a5860e1a73cfd72393a2bc6503f2319d0d18fbe88944d858510cc","thumb":"/expansion-atlas/ex26_mob_hip_ir_liftoff-original-256.webp","detail":"/expansion-atlas/ex26_mob_hip_ir_liftoff-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_hip_ir_liftoff-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_hip_ir_liftoff-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_hip_ir_liftoff-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_hip_ir_liftoff-fill-960.webp"},"sourceSha256":"819fbbe3ae3a5860e1a73cfd72393a2bc6503f2319d0d18fbe88944d858510cc","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"0cf1806abb52324d":{"fields":{"id":"ex26_mob_hip_ir_liftoff","cz":"Aktivní zdvih zadního chodidla v sedu 90/90","en":"90/90 Rear-Foot Internal-Rotation Lift-Off","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Zadní chodidlo se zvedá, zadní koleno zůstává opřené. Pohyb vychází z kyčle.","The rear foot lifts while the rear knee stays supported. Move from the hip."],"startPosition":["Sedni do pohodlné polohy 90/90 a opři dlaně tak, aby ses mohl lehce nadlehčit. Zadní koleno zůstává opřené; jeho chodidlo je pracovní. Přibližné úhly uprav bez tlaku v koleni.","Sit in a comfortable 90/90 position and place your hands where they can support some weight. Keep the rear knee supported; its foot is the working foot. Adjust the approximate angles without pressure in the knee."],"execution":["Pomalu odlehči a zvedni zadní chodidlo malý kousek od země, aniž zvedneš zadní koleno nebo přetočíš celou pánev. Krátce zastav a polož chodidlo. Jeden zdvih a položení je jedno opakování; zapisuj stranu zadní pracovní nohy.","Slowly unload and lift the rear foot a small distance without lifting the rear knee or rolling the whole pelvis. Pause briefly and lower the foot. One lift and lowering is one repetition; record the side of the rear working leg."],"watchFor":["Výška není cílem. Pokud se místo chodidla zvedá koleno nebo pánev, zmenši pokus. Netlač koleno rukou do podlahy a nevytáčej samotný kotník. Klidně dýchej; při bolesti skonči.","Height is not the goal. Reduce the attempt if the knee or pelvis lifts instead of the foot. Do not push the knee into the floor with a hand or twist only the ankle. Breathe normally and stop if it hurts."]},"progression":["Lehčí: více opory rukou, pohodlnější rozestavení nohou a jen odlehčení chodidla bez viditelného zdvihu. Náročnější: krátká kontrolovaná pauza nebo menší pomoc rukou. Zátěž na kotník není součástí základu.","Easier: use more hand support, a more comfortable leg position and simply unload the foot without a visible lift. More demanding: a brief controlled pause or less hand support. An ankle weight is not part of the basic version."]}}},"ex26_mob_hip_er_liftoff":{"id":"ex26_mob_hip_er_liftoff","segment":"F","edits":{"pos":["Sedni do pohodlné polohy 90/90 a opři dlaně o podlahu. Přední koleno zůstává opřené; jeho chodidlo je pracovní. Přibližné úhly uprav bez tlaku v koleni.","Sit in a comfortable 90/90 position with the hands supported on the floor. Keep the front knee supported; its foot is the working foot. Adjust the approximate angles without pressure in the knee."],"exe":["Pomalu odlehči a zvedni přední chodidlo malý kousek. Přední koleno zůstává dole a pánev se výrazně nepřeklápí. Chodidlo kontrolovaně polož. Jeden zdvih a položení je jedno opakování; zapisuj stranu přední pracovní nohy.","Slowly unload and lift the front foot a small distance. Keep the front knee down without substantially rolling the pelvis. Lower the foot under control. One lift and lowering is one repetition; record the side of the front working leg."],"wat":["Nadzvednutí celé přední nohy je jiný úkol. Netlač koleno rukou dolů a nesnaž se zdvih získat samotným kotníkem. Malý nebo sotva viditelný pohyb stačí; při bolesti skonči.","Lifting the whole front leg is a different task. Do not press the knee down with a hand or try to lift by moving only the ankle. A small or barely visible movement is enough; stop if it hurts."],"pro":["Lehčí: více opory rukou a pouze odlehčení chodidla. Náročnější: krátká pauza v ovládané výšce nebo menší pomoc rukou. Nenahrazuj zdvih tlačením ruky do nohy.","Easier: use more hand support and only unload the foot. More demanding: pause briefly at a controlled height or use less hand support. Do not replace the lift by pushing the leg with a hand."],"foc":["Přední chodidlo se zvedá, přední koleno zůstává opřené.","The front foot lifts while the front knee stays supported."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_hip_er_liftoff","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_hip_er_liftoff","atlasId":"ex26_mob_hip_er_liftoff","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"bcfecb057020dde879b93b5f5a8200ba05cb017ddfd3b6c24a2250587b4092f3","thumb":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-original-256.webp","detail":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_hip_er_liftoff-audit20261013-fill-960.webp"},"sourceSha256":"bcfecb057020dde879b93b5f5a8200ba05cb017ddfd3b6c24a2250587b4092f3","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"129f038294394eb7":{"fields":{"id":"ex26_mob_hip_er_liftoff","cz":"Aktivní zdvih předního chodidla v sedu 90/90","en":"90/90 Front-Foot External-Rotation Lift-Off","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Přední chodidlo se zvedá, přední koleno zůstává opřené.","The front foot lifts while the front knee stays supported."],"startPosition":["Sedni do pohodlné polohy 90/90 a opři dlaně o podlahu. Přední koleno zůstává opřené; jeho chodidlo je pracovní. Přibližné úhly uprav bez tlaku v koleni.","Sit in a comfortable 90/90 position with the hands supported on the floor. Keep the front knee supported; its foot is the working foot. Adjust the approximate angles without pressure in the knee."],"execution":["Pomalu odlehči a zvedni přední chodidlo malý kousek. Přední koleno zůstává dole a pánev se výrazně nepřeklápí. Chodidlo kontrolovaně polož. Jeden zdvih a položení je jedno opakování; zapisuj stranu přední pracovní nohy.","Slowly unload and lift the front foot a small distance. Keep the front knee down without substantially rolling the pelvis. Lower the foot under control. One lift and lowering is one repetition; record the side of the front working leg."],"watchFor":["Nadzvednutí celé přední nohy je jiný úkol. Netlač koleno rukou dolů a nesnaž se zdvih získat samotným kotníkem. Malý nebo sotva viditelný pohyb stačí; při bolesti skonči.","Lifting the whole front leg is a different task. Do not press the knee down with a hand or try to lift by moving only the ankle. A small or barely visible movement is enough; stop if it hurts."]},"progression":["Lehčí: více opory rukou a pouze odlehčení chodidla. Náročnější: krátká pauza v ovládané výšce nebo menší pomoc rukou. Nenahrazuj zdvih tlačením ruky do nohy.","Easier: use more hand support and only unload the foot. More demanding: pause briefly at a controlled height or use less hand support. Do not replace the lift by pushing the leg with a hand."]}}},"ex26_mob_shinbox_rise":{"id":"ex26_mob_shinbox_rise","segment":"F","edits":{"pos":["Sedni na pevnou neklouzavou podlahu do pohodlné polohy 90/90. Připrav si oporu rukou podle potřeby. Kolena a holeně musí snášet opření bez bolesti; tenké podložení je volitelné.","Sit in a comfortable 90/90 position on a firm non-slip floor. Use hand support as needed. The knees and shins must tolerate support without pain; thin cushioning is optional."],"exe":["Přenes váhu nad kolena a pomalu zvedni pánev nahoru a mírně vpřed do vyššího kleku v tomto rozestavení. Potom ji spusť zpět do stejného sedu. Vztyk a návrat je jedno opakování; stranu označ podle nohy, která byla v sedu vpředu. Obě nohy pracují.","Transfer weight over the knees and slowly lift the pelvis up and slightly forward into higher kneeling in this leg arrangement. Then lower into the same seated position. One rise and return is one repetition; label the side by the leg that was in front while seated. Both legs work."],"wat":["Pánev se zde záměrně zvedá; nezaměňuj to za zdvih samotného chodidla. Nezískávej výšku prudkým záklonem. Rukama si můžeš pomoci. Přechod do polokleku nebo stoje do tohoto opakování nepatří.","The pelvis deliberately rises here; this is different from lifting only a foot. Do not gain height by sharply arching backwards. Hand assistance is allowed. Moving into half-kneeling or standing is not part of this repetition."],"pro":["Lehčí: částečný vztyk s pomocí rukou. Pokud kolena nesnášejí opření, vrať se k pohodlnému přesedu bez vztyku. Náročnější: plynulý pomalý návrat s menší pomocí rukou, ne nutně větší výška.","Easier: a partial rise with hand assistance. If knee support is uncomfortable, return to a comfortable seated switch without rising. More demanding: a smooth slow return with less hand assistance, not necessarily more height."],"foc":["Pánev nahoru a zpět do stejného sedu, kolena a holeně tvoří oporu.","Lift the pelvis and return to the same seat, using the knees and shins for support."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated","kneeling"],"supports":["hand_support"],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_shinbox_rise","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_shinbox_rise","atlasId":"ex26_mob_shinbox_rise","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"9d6223e19519d0a70d1544405bf66aac1e0c6f54cc26bc63d3efba0caa3a953a","thumb":"/expansion-atlas/ex26_mob_shinbox_rise-original-256.webp","detail":"/expansion-atlas/ex26_mob_shinbox_rise-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_shinbox_rise-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_shinbox_rise-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_shinbox_rise-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_shinbox_rise-fill-960.webp"},"sourceSha256":"9d6223e19519d0a70d1544405bf66aac1e0c6f54cc26bc63d3efba0caa3a953a","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"27c42cf2596068f1":{"fields":{"id":"ex26_mob_shinbox_rise","cz":"Vztyk z polohy 90/90 do kleku","en":"Shinbox Hip Rise","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Pánev nahoru a zpět do stejného sedu, kolena a holeně tvoří oporu.","Lift the pelvis and return to the same seat, using the knees and shins for support."],"startPosition":["Sedni na pevnou neklouzavou podlahu do pohodlné polohy 90/90. Připrav si oporu rukou podle potřeby. Kolena a holeně musí snášet opření bez bolesti; tenké podložení je volitelné.","Sit in a comfortable 90/90 position on a firm non-slip floor. Use hand support as needed. The knees and shins must tolerate support without pain; thin cushioning is optional."],"execution":["Přenes váhu nad kolena a pomalu zvedni pánev nahoru a mírně vpřed do vyššího kleku v tomto rozestavení. Potom ji spusť zpět do stejného sedu. Vztyk a návrat je jedno opakování; stranu označ podle nohy, která byla v sedu vpředu. Obě nohy pracují.","Transfer weight over the knees and slowly lift the pelvis up and slightly forward into higher kneeling in this leg arrangement. Then lower into the same seated position. One rise and return is one repetition; label the side by the leg that was in front while seated. Both legs work."],"watchFor":["Pánev se zde záměrně zvedá; nezaměňuj to za zdvih samotného chodidla. Nezískávej výšku prudkým záklonem. Rukama si můžeš pomoci. Přechod do polokleku nebo stoje do tohoto opakování nepatří.","The pelvis deliberately rises here; this is different from lifting only a foot. Do not gain height by sharply arching backwards. Hand assistance is allowed. Moving into half-kneeling or standing is not part of this repetition."]},"progression":["Lehčí: částečný vztyk s pomocí rukou. Pokud kolena nesnášejí opření, vrať se k pohodlnému přesedu bez vztyku. Náročnější: plynulý pomalý návrat s menší pomocí rukou, ne nutně větší výška.","Easier: a partial rise with hand assistance. If knee support is uncomfortable, return to a comfortable seated switch without rising. More demanding: a smooth slow return with less hand assistance, not necessarily more height."]}}},"ex26_mob_prone_hip_rotation":{"id":"ex26_mob_prone_hip_rotation","segment":"F","edits":{"pos":["Lehni si na břicho, hlavu pohodlně opři a jednu nohu nech nataženou. Druhé koleno ohni přibližně do pravého úhlu, chodidlo nad kolenem. Stehno a přední část pánve zůstávají opřené.","Lie on your front with the head comfortably supported and one leg straight. Bend the other knee near a right angle, with its foot above the knee. Keep the thigh and front of the pelvis supported."],"exe":["Otáčej stehno v kyčli: chodidlo pomalu ven, zpět nad koleno, mírně dovnitř a zpět. Pro nový předpis počítej tento celý cyklus jako jedno opakování pracovní nohy. Levou a pravou zapisuj zvlášť; starší počty nepřepočítávej.","Rotate the thigh at the hip: slowly move the foot out, back above the knee, slightly inward and back. For a new prescription, count this full cycle as one repetition of the working leg. Record left and right separately; do not recalculate earlier counts."],"wat":["Chodidlo ven znamená vnitřní rotaci kyčle, dovnitř zevní. Koleno necestuje do strany a pánev se výrazně nepřeklápí. Nejde o kroucení kotníku ani o co největší oblouk. Při sevření kyčle nebo bolesti kolene zmenši rozsah či skonči.","Moving the foot out means internal hip rotation; inward means external rotation. Keep the knee from travelling sideways and the pelvis from substantially rolling. This is not ankle twisting or a search for the largest arc. Reduce the range or stop for hip pinching or knee pain."],"pro":["Lehčí: malý oblouk kolem svislé polohy. Náročnější: krátká klidná pauza na konci obou směrů při stejné poloze. Guma, popruh kolem stehen ani závaží nejsou součástí této varianty.","Easier: a small arc around the vertical position. More demanding: pause briefly at each end while keeping the same position. A band, strap around the thighs or weight is not part of this version."],"foc":["Stehno se otáčí v kyčli; koleno zůstává na místě a chodidlo opisuje malý oblouk.","The thigh rotates at the hip; the knee stays in place while the foot traces a small arc."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["prone"],"supports":[],"priority":1,"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_prone_hip_rotation","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_prone_hip_rotation","atlasId":"ex26_mob_prone_hip_rotation","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"f7e38784618e835690dff0a8f2114588e4f3defd6ac195e9a19ca444e42970c6","thumb":"/expansion-atlas/ex26_mob_prone_hip_rotation-original-256.webp","detail":"/expansion-atlas/ex26_mob_prone_hip_rotation-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_prone_hip_rotation-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_prone_hip_rotation-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_prone_hip_rotation-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_prone_hip_rotation-fill-960.webp"},"sourceSha256":"f7e38784618e835690dff0a8f2114588e4f3defd6ac195e9a19ca444e42970c6","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"e9e3ec4b47307df7":{"fields":{"id":"ex26_mob_prone_hip_rotation","cz":"Aktivní rotace kyčle vleže na břiše","en":"Prone Active Hip Rotation","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Stehno se otáčí v kyčli; koleno zůstává na místě a chodidlo opisuje malý oblouk.","The thigh rotates at the hip; the knee stays in place while the foot traces a small arc."],"startPosition":["Lehni si na břicho, hlavu pohodlně opři a jednu nohu nech nataženou. Druhé koleno ohni přibližně do pravého úhlu, chodidlo nad kolenem. Stehno a přední část pánve zůstávají opřené.","Lie on your front with the head comfortably supported and one leg straight. Bend the other knee near a right angle, with its foot above the knee. Keep the thigh and front of the pelvis supported."],"execution":["Otáčej stehno v kyčli: chodidlo pomalu ven, zpět nad koleno, mírně dovnitř a zpět. Pro nový předpis počítej tento celý cyklus jako jedno opakování pracovní nohy. Levou a pravou zapisuj zvlášť; starší počty nepřepočítávej.","Rotate the thigh at the hip: slowly move the foot out, back above the knee, slightly inward and back. For a new prescription, count this full cycle as one repetition of the working leg. Record left and right separately; do not recalculate earlier counts."],"watchFor":["Chodidlo ven znamená vnitřní rotaci kyčle, dovnitř zevní. Koleno necestuje do strany a pánev se výrazně nepřeklápí. Nejde o kroucení kotníku ani o co největší oblouk. Při sevření kyčle nebo bolesti kolene zmenši rozsah či skonči.","Moving the foot out means internal hip rotation; inward means external rotation. Keep the knee from travelling sideways and the pelvis from substantially rolling. This is not ankle twisting or a search for the largest arc. Reduce the range or stop for hip pinching or knee pain."]},"progression":["Lehčí: malý oblouk kolem svislé polohy. Náročnější: krátká klidná pauza na konci obou směrů při stejné poloze. Guma, popruh kolem stehen ani závaží nejsou součástí této varianty.","Easier: a small arc around the vertical position. More demanding: pause briefly at each end while keeping the same position. A band, strap around the thighs or weight is not part of this version."]}}},"ex26_mob_seated_hip_rotation":{"id":"ex26_mob_seated_hip_rotation","segment":"F","edits":{"eq":["flat_bench"],"pos":["Sedni na stabilní rovnou lavičku nebo židli tak vysoko, aby pracovní chodidlo mělo volnou dráhu nad podlahou. Stehno je podepřené, koleno přibližně v pravém úhlu. Rukama se můžeš přidržet sedadla.","Sit on a stable flat bench or chair high enough for the working foot to move clear of the floor. Support the thigh with the knee near a right angle. Hold the seat with your hands if helpful."],"exe":["Otáčej stehno v kyčli a pomalu veď chodidlo ven, přes svislou polohu dovnitř a zpět do středu. Pro nový předpis počítej tento celý cyklus jako jedno opakování pracovní nohy. Levou a pravou zapisuj zvlášť; starší počty nepřepočítávej.","Rotate the thigh at the hip, slowly moving the foot out, through vertical inward and back to centre. For a new prescription, count this full cycle as one repetition of the working leg. Record left and right separately; do not recalculate earlier counts."],"wat":["Chodidlo ven znamená vnitřní rotaci kyčle, dovnitř zevní. Koleno nemá cestovat do strany; stehno se přesto otáčí kolem své osy. Nenahrazuj pohyb úklonem trupu nebo kotníkem. Zvol pohodlný rozsah bez sevření kyčle.","Moving the foot out means internal hip rotation; inward means external rotation. The knee should not travel sideways, although the thigh rotates around its axis. Do not substitute trunk leaning or ankle movement. Use a comfortable range without hip pinching."],"pro":["Lehčí: menší oblouk a ruce lehce kontrolující polohu stehna. Náročnější: krátká pauza v obou směrech. Nezvětšuj rozsah tlačením rukou do chodidla; nejde o test úhlu ani odporovou variantu.","Easier: a smaller arc with the hands lightly monitoring thigh position. More demanding: a brief pause in both directions. Do not push the foot with a hand to increase range; this is neither an angle test nor a resisted version."],"foc":["Koleno zůstává přibližně na místě, stehno se otáčí a chodidlo má volnou dráhu.","Keep the knee roughly in place while the thigh rotates and the foot moves freely."],"equipmentDetail":["Stabilní rovná lavička nebo židle bez koleček, s dostatečnou výškou a bez příčky v dráze chodidla. Samotné označení židle nezaručuje vhodnou výšku; pokud chodidlo drhne o zem, zvol jiné sedadlo.","Use a stable flat bench or non-wheeled chair high enough, with no crossbar in the foot path. A chair label alone does not guarantee suitable height; choose another seat if the foot catches the floor."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["chair_bench"],"priority":1,"equipmentRequirements":[["flat_bench","chair"]]},"policy":{"id":"ex26_mob_seated_hip_rotation","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["flat_bench","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/ex26_mob_seated_hip_rotation-6fadeaee8f06f076.mp4"]},"art":{"appId":"ex26_mob_seated_hip_rotation","atlasId":"ex26_mob_seated_hip_rotation","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"2edf9888417289621034dd324354078498d8a31e1576135001839946f7698e79","thumb":"/expansion-atlas/ex26_mob_seated_hip_rotation-original-256.webp","detail":"/expansion-atlas/ex26_mob_seated_hip_rotation-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_seated_hip_rotation-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_seated_hip_rotation-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_seated_hip_rotation-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_seated_hip_rotation-fill-960.webp"},"sourceSha256":"2edf9888417289621034dd324354078498d8a31e1576135001839946f7698e79","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"6f63a9ac9eb365e2":{"fields":{"id":"ex26_mob_seated_hip_rotation","cz":"Aktivní vnitřní a zevní rotace kyčle v sedu","en":"Seated Active Hip Rotation","pat":"mobilita","eq":["flat_bench"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Koleno zůstává přibližně na místě, stehno se otáčí a chodidlo má volnou dráhu.","Keep the knee roughly in place while the thigh rotates and the foot moves freely."],"startPosition":["Sedni na stabilní rovnou lavičku nebo židli tak vysoko, aby pracovní chodidlo mělo volnou dráhu nad podlahou. Stehno je podepřené, koleno přibližně v pravém úhlu. Rukama se můžeš přidržet sedadla.","Sit on a stable flat bench or chair high enough for the working foot to move clear of the floor. Support the thigh with the knee near a right angle. Hold the seat with your hands if helpful."],"execution":["Otáčej stehno v kyčli a pomalu veď chodidlo ven, přes svislou polohu dovnitř a zpět do středu. Pro nový předpis počítej tento celý cyklus jako jedno opakování pracovní nohy. Levou a pravou zapisuj zvlášť; starší počty nepřepočítávej.","Rotate the thigh at the hip, slowly moving the foot out, through vertical inward and back to centre. For a new prescription, count this full cycle as one repetition of the working leg. Record left and right separately; do not recalculate earlier counts."],"watchFor":["Chodidlo ven znamená vnitřní rotaci kyčle, dovnitř zevní. Koleno nemá cestovat do strany; stehno se přesto otáčí kolem své osy. Nenahrazuj pohyb úklonem trupu nebo kotníkem. Zvol pohodlný rozsah bez sevření kyčle.","Moving the foot out means internal hip rotation; inward means external rotation. The knee should not travel sideways, although the thigh rotates around its axis. Do not substitute trunk leaning or ankle movement. Use a comfortable range without hip pinching."]},"progression":["Lehčí: menší oblouk a ruce lehce kontrolující polohu stehna. Náročnější: krátká pauza v obou směrech. Nezvětšuj rozsah tlačením rukou do chodidla; nejde o test úhlu ani odporovou variantu.","Easier: a smaller arc with the hands lightly monitoring thigh position. More demanding: a brief pause in both directions. Do not push the foot with a hand to increase range; this is neither an angle test nor a resisted version."]}}},"ig27_seated_band_hip_ir":{"id":"ig27_seated_band_hip_ir","segment":"F","edits":{"eq":["flat_bench","short_loop_band","valec"],"exe":["Pracovní chodidlo nadlehči a veď je ven proti smyčce, potom pomalu vrať. Koleno zůstává u válce, druhé chodidlo opřené a stehno se otáčí v kyčli. Pohyb ven a návrat je jedno opakování; stranu zapisuj podle pracovní nohy.","Unload the working foot and move it out against the loop, then return slowly. Keep its knee beside the roller and the other foot supported as the thigh rotates at the hip. One outward movement and return is one repetition; record the side of the working leg."],"pro":["Lehčí: slabší smyčka a menší rozsah; bez gumy použij volnou rotaci vsedě. Náročnější: nejprve plynulý návrat, potom malý nárůst odporu. Pro porovnání si poznamenej smyčku a její umístění; barvu ani napětí nepřeváděj na kilogramy.","Easier: a lighter loop and smaller range; use free seated rotation when working without a band. More demanding: first control the return, then increase resistance slightly. Note the loop and its placement for comparison; do not convert its colour or tension to kilograms."],"equipmentDetail":["Stabilní rovná lavička nebo židle bez koleček, krátká odporová smyčka kolem kotníků a měkký válec mezi koleny. Nepracovní chodidlo musí dosáhnout na podlahu; pracovní má prostor nad zemí. Tato přijatá varianta používá smyčku přes obě nohy, nikoli vnější kotvu.","Use a stable flat bench or non-wheeled chair, a short resistance loop around the ankles and a soft roller between the knees. The nonworking foot must reach the floor while the working foot has clearance. This accepted version uses a loop around both legs, not an external anchor."]},"taxonomy":{"regions":["hips"],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["chair_bench"],"priority":1,"equipmentRequirements":[["flat_bench","chair"],["short_loop_band"],["valec"]]},"policy":{"id":"ig27_seated_band_hip_ir","measurementType":"REPS_ONLY","loadMode":"none","sideMode":"perSide","requirements":[["flat_bench","chair"],["short_loop_band"],["valec"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_seated_band_hip_ir","atlasId":"ig27_seated_band_hip_ir","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a15561674da34fbc06e774276399e0aa07d52c870e283a886d44db6be4396db8","thumb":"/expansion-atlas/ig27_seated_band_hip_ir-original-256.webp","detail":"/expansion-atlas/ig27_seated_band_hip_ir-original-960.webp","inkThumb":"/expansion-atlas/ig27_seated_band_hip_ir-ink-256.webp","inkDetail":"/expansion-atlas/ig27_seated_band_hip_ir-ink-960.webp","fillThumb":"/expansion-atlas/ig27_seated_band_hip_ir-fill-256.webp","fillDetail":"/expansion-atlas/ig27_seated_band_hip_ir-fill-960.webp"},"sourceSha256":"a15561674da34fbc06e774276399e0aa07d52c870e283a886d44db6be4396db8","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"45b86b86cf8cf875":{"fields":{"id":"ig27_seated_band_hip_ir","cz":"Vnitřní rotace kyčle vsedě s gumou","en":"Seated Banded Hip Internal Rotation","pat":"mobilita","eq":["flat_bench","short_loop_band","valec"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":true,"sideMode":"perSide","focus":["Koleno stojí, chodidlo se pohybuje ven.","Keep the knee still as the foot moves outward."],"startPosition":["Sedni na okraj pevné lavičky. Mezi kolena dej měkký válec a gumu kolem kotníků. Stehna nech vpřed, kolena přibližně v pravém úhlu. Nepracovní chodidlo opři.","Sit at the edge of a stable bench. Place a soft roller between the knees and a band around the ankles. Point the thighs forward, knees near a right angle. Ground the nonworking foot."],"execution":["Pracovní chodidlo nadlehči a veď je ven proti smyčce, potom pomalu vrať. Koleno zůstává u válce, druhé chodidlo opřené a stehno se otáčí v kyčli. Pohyb ven a návrat je jedno opakování; stranu zapisuj podle pracovní nohy.","Unload the working foot and move it out against the loop, then return slowly. Keep its knee beside the roller and the other foot supported as the thigh rotates at the hip. One outward movement and return is one repetition; record the side of the working leg."],"watchFor":["Pohyb chodidla ven při klidném koleni znamená vnitřní rotaci kyčle. Neodtahuj celé koleno a neukláněj trup. Netlač přes nepříjemný tlak v kyčli.","Outward foot movement with the knee still produces internal hip rotation. Do not move the whole knee sideways or lean the torso. Do not force through uncomfortable hip pressure."]},"progression":["Lehčí: slabší smyčka a menší rozsah; bez gumy použij volnou rotaci vsedě. Náročnější: nejprve plynulý návrat, potom malý nárůst odporu. Pro porovnání si poznamenej smyčku a její umístění; barvu ani napětí nepřeváděj na kilogramy.","Easier: a lighter loop and smaller range; use free seated rotation when working without a band. More demanding: first control the return, then increase resistance slightly. Note the loop and its placement for comparison; do not convert its colour or tension to kilograms."]}}},"ex26_plank_hiprotation":{"id":"ex26_plank_hiprotation","segment":"G","edits":{"cz":"Rotace pokrčené nohy ve vzporu","en":"Bent-Knee Hip Rotation in High Plank","ez":null,"pos":["Opři dlaně přibližně pod ramena a chodidla o špičky jako v horní poloze kliku. Najdi pevnou polohu trupu, ve které se nepropadáš v bedrech.","Place the hands roughly under the shoulders and support the feet on the toes as at the top of a push-up. Find a steady trunk position without sagging through the lower back."],"exe":["Přitáhni jedno koleno pod trup, veď ho krátce dovnitř a potom ven z kyčle. Vrať chodidlo do vzporu. Přitažení, oba směry a návrat tvoří jedno opakování na pohybující se nohu; strany vystřídej podle plánu.","Draw one knee under the torso, guide it briefly inward and then outward from the hip. Return the foot to the plank. The tuck, both directions and return form one repetition for the moving leg; change sides as planned."],"wat":["Pánev a ramena drž přibližně vodorovně. Není potřeba opisovat velký kruh, dotknout se lokte nebo vytočit celé tělo za kolenem. Pokud opora rukou není pohodlná, tuto variantu vynech.","Keep the pelvis and shoulders roughly level. There is no need to make a large circle, touch the elbow or turn the whole body after the knee. Skip this version if hand support is uncomfortable."],"pro":["Lehčí: menší vedení kolena nebo samostatný nácvik na čtyřech. Náročnější: pomalejší pohyb při klidném trupu. Varianta na čtyřech má jinou oporu; neposuzuj ji jako stejný výkon.","Easier: a smaller knee sweep or separate practice on all fours. More demanding: slower movement with a steady trunk. The all-fours version has different support; do not compare it as the same performance."],"foc":["Koleno dovnitř a ven, trup zůstává klidný.","Knee inward and outward, with a steady trunk."],"equipmentDetail":["Bez povinné pomůcky, na pevném neklouzavém podkladu. Podložka je volitelná; lavice není součást této podlahové varianty.","No required equipment; use a firm non-slip surface. A mat is optional; a bench is not part of this floor version."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["trunk","shoulders"],"movements":["joint","trunk_stability"],"focus":["mobility","coordination"],"equipmentRequirements":[["telo"]],"priority":2,"positions":["high_plank"],"supports":["hand_support"],"aliases":["high plank hip rotation","push up hip rotation","pokrčené koleno ve vzporu"]},"policy":{"id":"ex26_plank_hiprotation","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_plank_hiprotation","atlasId":"ex26_plank_hiprotation","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"6de9bd4d69beb679de872c08564b0244752a233b7d382db636d7516f8e06cdc0","thumb":"/expansion-atlas/ex26_plank_hiprotation-original-256.webp","detail":"/expansion-atlas/ex26_plank_hiprotation-original-960.webp","inkThumb":"/expansion-atlas/ex26_plank_hiprotation-ink-256.webp","inkDetail":"/expansion-atlas/ex26_plank_hiprotation-ink-960.webp","fillThumb":"/expansion-atlas/ex26_plank_hiprotation-fill-256.webp","fillDetail":"/expansion-atlas/ex26_plank_hiprotation-fill-960.webp"},"sourceSha256":"6de9bd4d69beb679de872c08564b0244752a233b7d382db636d7516f8e06cdc0","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"b102d1220ac832f8":{"fields":{"id":"ex26_plank_hiprotation","cz":"Rotace pokrčené nohy ve vzporu","en":"Bent-Knee Hip Rotation in High Plank","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":90,"unilateral":true,"sideMode":"perSide","focus":["Koleno dovnitř a ven, trup zůstává klidný.","Knee inward and outward, with a steady trunk."],"startPosition":["Opři dlaně přibližně pod ramena a chodidla o špičky jako v horní poloze kliku. Najdi pevnou polohu trupu, ve které se nepropadáš v bedrech.","Place the hands roughly under the shoulders and support the feet on the toes as at the top of a push-up. Find a steady trunk position without sagging through the lower back."],"execution":["Přitáhni jedno koleno pod trup, veď ho krátce dovnitř a potom ven z kyčle. Vrať chodidlo do vzporu. Přitažení, oba směry a návrat tvoří jedno opakování na pohybující se nohu; strany vystřídej podle plánu.","Draw one knee under the torso, guide it briefly inward and then outward from the hip. Return the foot to the plank. The tuck, both directions and return form one repetition for the moving leg; change sides as planned."],"watchFor":["Pánev a ramena drž přibližně vodorovně. Není potřeba opisovat velký kruh, dotknout se lokte nebo vytočit celé tělo za kolenem. Pokud opora rukou není pohodlná, tuto variantu vynech.","Keep the pelvis and shoulders roughly level. There is no need to make a large circle, touch the elbow or turn the whole body after the knee. Skip this version if hand support is uncomfortable."]},"progression":["Lehčí: menší vedení kolena nebo samostatný nácvik na čtyřech. Náročnější: pomalejší pohyb při klidném trupu. Varianta na čtyřech má jinou oporu; neposuzuj ji jako stejný výkon.","Easier: a smaller knee sweep or separate practice on all fours. More demanding: slower movement with a steady trunk. The all-fours version has different support; do not compare it as the same performance."]}}},"ex26_mob_supine_hip_circle":{"id":"ex26_mob_supine_hip_circle","segment":"G","edits":{"pos":["Lehni na záda a nech hlavu pohodlně položenou. Jedno koleno pokrč, chodidlo opři o zem a druhou nohu zvedni s téměř nataženým kolenem. Ruce nech vedle trupu.","Lie on your back with the head resting comfortably. Bend one knee with its foot on the floor and raise the other leg with the knee nearly straight. Rest the arms beside the trunk."],"exe":["Zvednutou nohou opisuj malý plynulý kruh z kyčle. Jeden celý kruh je jedno opakování na zvednutou nohu. Podle plánu změň směr a potom nohu; směr kruhu není levá nebo pravá strana.","Trace a small smooth circle from the raised hip. One full circle is one repetition for the raised leg. Change direction and then legs as planned; circle direction is not the left or right side."],"wat":["Pánev se nepřeklápí ze strany na stranu a záda zůstávají pohodlně opřená. Zmenši kruh, než se začne zvedat hlava nebo prohýbat trup. Koleno nepropínej silou.","Keep the pelvis from rocking side to side and the back comfortably supported. Make the circle smaller before the head lifts or trunk arches. Do not force the knee straight."],"pro":["Lehčí: menší kruh nebo trochu pokrčenější zvednutá noha. Náročnější: plynulejší či pomalejší kruh bez změny opory. Větší kruh je možnost, ne povinný cíl.","Easier: a smaller circle or slightly more bend in the raised leg. More demanding: a smoother or slower circle without changing support. A larger circle is an option, not a required goal."],"foc":["Malý kruh zvednutou nohou, klidná pánev.","A small circle with the raised leg and a steady pelvis."],"equipmentDetail":["Bez povinné pomůcky. Pohodlná podložka je volitelná.","No required equipment. A comfortable mat is optional."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["trunk"],"movements":["joint"],"focus":["mobility"],"equipmentRequirements":[["telo"]],"priority":1,"positions":["supine"],"supports":["unsupported"],"aliases":["supine leg circle","single leg circle","kroužení nataženou nohou vleže"]},"policy":{"id":"ex26_mob_supine_hip_circle","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_supine_hip_circle","atlasId":"ex26_mob_supine_hip_circle","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"49042668b32faa9c334746662292e2b89d9c042be60d2dabf1ef9eecedaf31df","thumb":"/expansion-atlas/ex26_mob_supine_hip_circle-original-256.webp","detail":"/expansion-atlas/ex26_mob_supine_hip_circle-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_supine_hip_circle-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_supine_hip_circle-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_supine_hip_circle-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_supine_hip_circle-fill-960.webp"},"sourceSha256":"49042668b32faa9c334746662292e2b89d9c042be60d2dabf1ef9eecedaf31df","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"9dfb78e5897e0d8a":{"fields":{"id":"ex26_mob_supine_hip_circle","cz":"Kroužení nataženou nohou vleže","en":"Supine Leg Circle","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Malý kruh zvednutou nohou, klidná pánev.","A small circle with the raised leg and a steady pelvis."],"startPosition":["Lehni na záda a nech hlavu pohodlně položenou. Jedno koleno pokrč, chodidlo opři o zem a druhou nohu zvedni s téměř nataženým kolenem. Ruce nech vedle trupu.","Lie on your back with the head resting comfortably. Bend one knee with its foot on the floor and raise the other leg with the knee nearly straight. Rest the arms beside the trunk."],"execution":["Zvednutou nohou opisuj malý plynulý kruh z kyčle. Jeden celý kruh je jedno opakování na zvednutou nohu. Podle plánu změň směr a potom nohu; směr kruhu není levá nebo pravá strana.","Trace a small smooth circle from the raised hip. One full circle is one repetition for the raised leg. Change direction and then legs as planned; circle direction is not the left or right side."],"watchFor":["Pánev se nepřeklápí ze strany na stranu a záda zůstávají pohodlně opřená. Zmenši kruh, než se začne zvedat hlava nebo prohýbat trup. Koleno nepropínej silou.","Keep the pelvis from rocking side to side and the back comfortably supported. Make the circle smaller before the head lifts or trunk arches. Do not force the knee straight."]},"progression":["Lehčí: menší kruh nebo trochu pokrčenější zvednutá noha. Náročnější: plynulejší či pomalejší kruh bez změny opory. Větší kruh je možnost, ne povinný cíl.","Easier: a smaller circle or slightly more bend in the raised leg. More demanding: a smoother or slower circle without changing support. A larger circle is an option, not a required goal."]}}},"ex26_mob_squat_hip_ir":{"id":"ex26_mob_squat_hip_ir","segment":"G","edits":{"cz":"Vnitřní rotace kyčle vsedě na opoře","en":"Seated Hip Internal Rotation on a Support","pos":["Sedni na pevnou stoličku, židli nebo vhodně vysokou lavici. Chodidla postav šířeji než boky, sedací opora nese většinu váhy. Výšku zvol tak, aby ses nemusel držet v hlubokém dřepu.","Sit on a stable stool, chair or suitably high bench. Place the feet wider than the hips, with the seat carrying most of your weight. Choose a height that does not require holding a deep squat."],"exe":["S váhou na sedadle pomalu otoč jedno stehno dovnitř a nech koleno klesnout mírně ke středu. Chodidlo se smí pootočit s nohou. Vrať se a vystřídej stranu. Jedno sklopení a návrat je jedno opakování; levá a pravá jsou dvě opakování celkem.","With weight on the seat, slowly turn one thigh inward and let the knee move slightly toward the centre. Allow the foot to pivot with the leg. Return and change sides. One inward turn and return is one repetition; left and right are two total repetitions."],"wat":["Koleno netlač rukou k zemi a neopírej do něj plnou váhu. Neponechávej chodidlo násilně přilepené k podlaze. Zvol menší pohyb nebo vyšší sed, pokud se v koleni či kyčli objeví nepříjemný tlak.","Do not push the knee toward the floor with a hand or load it with full body weight. Do not force the foot to stay fixed to the floor. Use a smaller movement or higher seat if the knee or hip feels uncomfortable pressure."],"pro":["Lehčí: vyšší pevný sed a kratší rotace. Dál můžeš zlepšovat plynulost při stejné výšce. Nižší stolička ani dotyk kolena se zemí nejsou povinným postupem.","Easier: a higher stable seat and shorter rotation. You can work on smoothness at the same height. A lower stool or knee touching the floor is not a required progression."],"foc":["Sed nese váhu; pomalu otoč stehno dovnitř a vrať.","Let the seat carry the weight; slowly turn the thigh inward and return."],"equipmentDetail":["Jedna pevná stolička či židle bez koleček, nebo stabilní lavice/bedna vhodné výšky. Sedák musí nést váhu bez kývání či posouvání. Jde o alternativy, nikoli více pomůcek současně.","One stable stool or non-wheeled chair, or a stable bench/box at a suitable height. The seat must bear weight without rocking or sliding. These are alternatives, not multiple required items."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility"],"equipmentRequirements":[["lavice","flat_bench","box_support","chair"]],"priority":1,"positions":["seated"],"supports":["chair_bench"],"aliases":["squat hip internal rotation","squatting internal rotations","řízené sklopení kolena v podřepu","vnitřní rotace kyčle na stoličce"]},"policy":{"id":"ex26_mob_squat_hip_ir","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"alternating","requirements":[["lavice","flat_bench","box_support","chair"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_squat_hip_ir","atlasId":"ex26_mob_squat_hip_ir","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ab91a35b1342ee14d0530f0ec84efb18eb288ff35d241170c877b992ec804cdf","thumb":"/expansion-atlas/ex26_mob_squat_hip_ir-original-256.webp","detail":"/expansion-atlas/ex26_mob_squat_hip_ir-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_squat_hip_ir-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_squat_hip_ir-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_squat_hip_ir-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_squat_hip_ir-fill-960.webp"},"sourceSha256":"ab91a35b1342ee14d0530f0ec84efb18eb288ff35d241170c877b992ec804cdf","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"2d87083a713db65c":{"fields":{"id":"ex26_mob_squat_hip_ir","cz":"Vnitřní rotace kyčle vsedě na opoře","en":"Seated Hip Internal Rotation on a Support","pat":"mobilita","eq":["lavice"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"alternating","focus":["Sed nese váhu; pomalu otoč stehno dovnitř a vrať.","Let the seat carry the weight; slowly turn the thigh inward and return."],"startPosition":["Sedni na pevnou stoličku, židli nebo vhodně vysokou lavici. Chodidla postav šířeji než boky, sedací opora nese většinu váhy. Výšku zvol tak, aby ses nemusel držet v hlubokém dřepu.","Sit on a stable stool, chair or suitably high bench. Place the feet wider than the hips, with the seat carrying most of your weight. Choose a height that does not require holding a deep squat."],"execution":["S váhou na sedadle pomalu otoč jedno stehno dovnitř a nech koleno klesnout mírně ke středu. Chodidlo se smí pootočit s nohou. Vrať se a vystřídej stranu. Jedno sklopení a návrat je jedno opakování; levá a pravá jsou dvě opakování celkem.","With weight on the seat, slowly turn one thigh inward and let the knee move slightly toward the centre. Allow the foot to pivot with the leg. Return and change sides. One inward turn and return is one repetition; left and right are two total repetitions."],"watchFor":["Koleno netlač rukou k zemi a neopírej do něj plnou váhu. Neponechávej chodidlo násilně přilepené k podlaze. Zvol menší pohyb nebo vyšší sed, pokud se v koleni či kyčli objeví nepříjemný tlak.","Do not push the knee toward the floor with a hand or load it with full body weight. Do not force the foot to stay fixed to the floor. Use a smaller movement or higher seat if the knee or hip feels uncomfortable pressure."]},"progression":["Lehčí: vyšší pevný sed a kratší rotace. Dál můžeš zlepšovat plynulost při stejné výšce. Nižší stolička ani dotyk kolena se zemí nejsou povinným postupem.","Easier: a higher stable seat and shorter rotation. You can work on smoothness at the same height. A lower stool or knee touching the floor is not a required progression."]}}},"couch":{"id":"couch","segment":"H","edits":{"cz":"Protažení přední strany kyčle u zdi","en":"Wall Couch Stretch","mp":["qua","hipflex"],"foc":["Najdi mírný tah vpředu v kyčli a stehně zadní nohy při klidném dechu.","Find a mild stretch at the front of the rear hip and thigh while breathing easily."],"pos":["Podlož zadní koleno a zaujmi klek zády ke zdi. Zadní nárt opři o zeď s holení směřující vzhůru, druhé chodidlo polož vpředu. Vzdálenost kolena od zdi zvol podle pohodlí; začni s rukama opřenýma o zem nebo přední stehno.","Pad the rear knee and kneel with your back to a wall. Rest the rear instep against the wall with the shin pointing upward and plant the other foot in front. Choose a comfortable knee-to-wall distance; start with your hands on the floor or front thigh."],"exe":["Lehce zapoj hýždi zadní nohy a uprav pánev tak, aby se tah soustředil vpředu v kyčli a stehně. Trup zvedni jen do pohodlné polohy a klidně dýchej. Zapisuj sekundy na stranu zadní nohy. Před výměnou se opři o ruce, odlehči koleno a uvolni nohu od zdi.","Gently engage the rear glute and adjust the pelvis to feel the stretch at the front of the hip and thigh. Raise the torso only to a comfortable position and breathe easily. Record seconds for the rear-leg side. Before switching, support yourself with your hands, unload the knee and release the foot from the wall."],"wat":["Nezískávej větší rozsah výrazným záklonem v bedrech. Bolest kolena, brnění ani ostrý tah nejsou cílem; z pozice vyjdi. Podložení kolena samo o sobě neřeší každou bolest.","Do not gain range by strongly arching the lower back. Knee pain, tingling or a sharp pull are not the goal; leave the position. Knee padding alone does not resolve every painful response."],"pro":["Lehčí: koleno dál od zdi, menší pokrčení zadního kolena a větší opora rukou. Náročnější: po malém kroku uprav vzdálenost nebo vzpřímení při stejném pohodlí. Dotknout se zády zdi ani vydržet pevný počet minut není podmínkou.","Easier: place the knee farther from the wall, bend the rear knee less and use more hand support. More demanding: adjust the distance or torso height slightly while remaining comfortable. Touching the wall with your back or holding for a fixed number of minutes is not required."],"source":{"author":"Mathias Method","document":"The Couch Hip Flexor Stretch","url":"https://mathiasmethod.com/mobility-exercises/hip-flexor-stretch/","scope":"Primary wall-supported setup and controlled hip/knee positioning only. Existing Tanmay static hold is retained rather than importing the source dynamic stages, dose, mandatory end position, medical or performance claims. Padding and comfortable-range cues are local adaptations."}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["kneeling"],"supports":["wall"],"equipmentRequirements":[["zed"],["knee_pad","exercise_mat","towel"]],"priority":2,"aliases":["Otevření kyčlí","Couch Stretch","couch stretch u zdi"]},"policy":{"id":"couch","measurementType":"DURATION","loadMode":"none","sideMode":"perSide","requirements":[["zed"],["knee_pad","exercise_mat","towel"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"couch","atlasId":"couch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"aedaa1b3707f9de1968a0c6fbf4b8d43bc2755773d0b72cec01679ee054a41f5","thumb":"/unified-atlas/couch-fd8e43921e0b8263-thumb.webp","detail":"/unified-atlas/couch-dce05b1487a615ab-detail.webp","inkThumb":"/unified-atlas/couch-15e2aaaeb14961b9-inkThumb.webp","inkDetail":"/unified-atlas/couch-9354fae393bfc0ad-inkDetail.webp","fillThumb":"/unified-atlas/couch-abfef9ac804c7b88-fillThumb.webp","fillDetail":"/unified-atlas/couch-4c55eaf2c751e5a2-fillDetail.webp"},"sourceSha256":"aedaa1b3707f9de1968a0c6fbf4b8d43bc2755773d0b72cec01679ee054a41f5","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"946fc83c888d352b":{"fields":{"id":"couch","cz":"Protažení přední strany kyčle u zdi","en":"Wall Couch Stretch","pat":"mobilita","eq":["zed"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Najdi mírný tah vpředu v kyčli a stehně zadní nohy při klidném dechu.","Find a mild stretch at the front of the rear hip and thigh while breathing easily."],"startPosition":["Podlož zadní koleno a zaujmi klek zády ke zdi. Zadní nárt opři o zeď s holení směřující vzhůru, druhé chodidlo polož vpředu. Vzdálenost kolena od zdi zvol podle pohodlí; začni s rukama opřenýma o zem nebo přední stehno.","Pad the rear knee and kneel with your back to a wall. Rest the rear instep against the wall with the shin pointing upward and plant the other foot in front. Choose a comfortable knee-to-wall distance; start with your hands on the floor or front thigh."],"execution":["Lehce zapoj hýždi zadní nohy a uprav pánev tak, aby se tah soustředil vpředu v kyčli a stehně. Trup zvedni jen do pohodlné polohy a klidně dýchej. Zapisuj sekundy na stranu zadní nohy. Před výměnou se opři o ruce, odlehči koleno a uvolni nohu od zdi.","Gently engage the rear glute and adjust the pelvis to feel the stretch at the front of the hip and thigh. Raise the torso only to a comfortable position and breathe easily. Record seconds for the rear-leg side. Before switching, support yourself with your hands, unload the knee and release the foot from the wall."],"watchFor":["Nezískávej větší rozsah výrazným záklonem v bedrech. Bolest kolena, brnění ani ostrý tah nejsou cílem; z pozice vyjdi. Podložení kolena samo o sobě neřeší každou bolest.","Do not gain range by strongly arching the lower back. Knee pain, tingling or a sharp pull are not the goal; leave the position. Knee padding alone does not resolve every painful response."]},"progression":["Lehčí: koleno dál od zdi, menší pokrčení zadního kolena a větší opora rukou. Náročnější: po malém kroku uprav vzdálenost nebo vzpřímení při stejném pohodlí. Dotknout se zády zdi ani vydržet pevný počet minut není podmínkou.","Easier: place the knee farther from the wall, bend the rear knee less and use more hand support. More demanding: adjust the distance or torso height slightly while remaining comfortable. Touching the wall with your back or holding for a fixed number of minutes is not required."]}}},"pigeon":{"id":"pigeon","segment":"H","edits":{"cz":"Holub · přípravné protažení","en":"Pigeon Stretch","ms":["hipflex"],"foc":["Opři ruce a najdi pohodlnou polohu přední kyčle bez tlaku v koleni.","Use hand support and find a comfortable front-hip position without knee pressure."],"pos":["Ze čtyř přesuň jedno koleno vpřed a chodidlo šikmo před opačný bok. Zadní nohu posuň vzad s nártem na zemi. Přední patu nech podle potřeby blíž k tělu; holeň nemusí být rovnoběžně s okrajem podložky. Opři se o ruce, případně podlož přední bok.","From all fours bring one knee forward and place the foot diagonally in front of the opposite hip. Slide the rear leg back with its instep on the floor. Keep the front heel closer to your body as needed; the shin need not be parallel to the mat edge. Use your hands for support and optionally pad under the front hip."],"exe":["Z pohodlné opory nakloň trup nad přední nohu jen do mírného tahu v hýždi. Můžeš zůstat vysoko na dlaních nebo se opřít o předloktí; klidně dýchej. Zapisuj skutečné sekundy výdrže. Potom se s oporou rukou vrať na čtyři a vystřídej nohy.","From a comfortable support lean over the front leg only to a mild buttock stretch. Stay higher on the palms or rest on the forearms and breathe calmly. Record the actual hold seconds. Then use your hands to return to all fours and change legs."],"wat":["Nenuť holeň do pravého úhlu ani nestlačuj boky k zemi. Při bolesti či tlaku v koleni pozici uvolni a zvol jiné pohodlné provedení; samotné vyšší podložení nemusí stačit. Netlač na koleno ani nepáč chodidlo.","Do not force a right angle at the front knee or press the hips to the floor. Release the position if the knee hurts or feels pressure and choose another comfortable setup; extra padding alone may not be enough. Do not press the knee or lever the foot."],"pro":["Lehčí: přední patu blíž k tělu, menší předklon a stabilní podložení boku; jinou možností je čtyřka vleže. Náročnější: o trochu větší předklon při stejné pohodlné poloze. Hloubka ani délka výdrže nejsou samy o sobě známkou lepší mobility.","Easier: keep the front heel closer, fold less and use stable hip support; a supine figure four is another option. More demanding: a slightly deeper fold in the same comfortable position. Depth or hold time alone does not establish better mobility."],"source":{"author":"YogaEasy / EkhartYoga","document":"Pigeon Pose — step by step, tips and variations","url":"https://www.yogaeasy.com/artikel/pigeon-pose","scope":"Supported preparatory pigeon and adjustable front-foot position; not the full king-pigeon posture. No source breath count, mandatory shin angle, treatment or mind-calming claim is imported. Existing duration measurement and historical unspecified-side mode are retained."}},"taxonomy":{"regions":["hips"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["other"],"supports":["hand_support","forearm_support"],"equipmentRequirements":[["telo"]],"priority":2,"aliases":["Holub","Pigeon Pose","pigeon stretch","přípravný holub"]},"policy":{"id":"pigeon","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"pigeon","atlasId":"pigeon","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5c56d9e3ba2712ae9c60ac5ad498501fd36d513de4a34e442556a61638aa572a","thumb":"/unified-atlas/pigeon-0ca9e3c1a1af7e19-thumb.webp","detail":"/unified-atlas/pigeon-4682b7f79d124701-detail.webp","inkThumb":"/unified-atlas/pigeon-5caa24e0d91eb32a-inkThumb.webp","inkDetail":"/unified-atlas/pigeon-c1a20767cf70e9b2-inkDetail.webp","fillThumb":"/unified-atlas/pigeon-8df203fd0a7a1835-fillThumb.webp","fillDetail":"/unified-atlas/pigeon-5ec502ac9de4b47f-fillDetail.webp"},"sourceSha256":"5c56d9e3ba2712ae9c60ac5ad498501fd36d513de4a34e442556a61638aa572a","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"8427e3872a241433":{"fields":{"id":"pigeon","cz":"Holub · přípravné protažení","en":"Pigeon Stretch","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Opři ruce a najdi pohodlnou polohu přední kyčle bez tlaku v koleni.","Use hand support and find a comfortable front-hip position without knee pressure."],"startPosition":["Ze čtyř přesuň jedno koleno vpřed a chodidlo šikmo před opačný bok. Zadní nohu posuň vzad s nártem na zemi. Přední patu nech podle potřeby blíž k tělu; holeň nemusí být rovnoběžně s okrajem podložky. Opři se o ruce, případně podlož přední bok.","From all fours bring one knee forward and place the foot diagonally in front of the opposite hip. Slide the rear leg back with its instep on the floor. Keep the front heel closer to your body as needed; the shin need not be parallel to the mat edge. Use your hands for support and optionally pad under the front hip."],"execution":["Z pohodlné opory nakloň trup nad přední nohu jen do mírného tahu v hýždi. Můžeš zůstat vysoko na dlaních nebo se opřít o předloktí; klidně dýchej. Zapisuj skutečné sekundy výdrže. Potom se s oporou rukou vrať na čtyři a vystřídej nohy.","From a comfortable support lean over the front leg only to a mild buttock stretch. Stay higher on the palms or rest on the forearms and breathe calmly. Record the actual hold seconds. Then use your hands to return to all fours and change legs."],"watchFor":["Nenuť holeň do pravého úhlu ani nestlačuj boky k zemi. Při bolesti či tlaku v koleni pozici uvolni a zvol jiné pohodlné provedení; samotné vyšší podložení nemusí stačit. Netlač na koleno ani nepáč chodidlo.","Do not force a right angle at the front knee or press the hips to the floor. Release the position if the knee hurts or feels pressure and choose another comfortable setup; extra padding alone may not be enough. Do not press the knee or lever the foot."]},"progression":["Lehčí: přední patu blíž k tělu, menší předklon a stabilní podložení boku; jinou možností je čtyřka vleže. Náročnější: o trochu větší předklon při stejné pohodlné poloze. Hloubka ani délka výdrže nejsou samy o sobě známkou lepší mobility.","Easier: keep the front heel closer, fold less and use stable hip support; a supine figure four is another option. More demanding: a slightly deeper fold in the same comfortable position. Depth or hold time alone does not establish better mobility."]}}},"ig27_floor_figure_four":{"id":"ig27_floor_figure_four","segment":"H","edits":{"foc":["S oporou dlaní najdi mírný tah v hýždi překřížené nohy bez tlaku v koleni.","Use palm support to find a mild stretch in the crossed-leg buttock without knee pressure."],"exe":["S oporou rukou se posaď o trochu vzpřímeněji, až ucítíš pohodlný tah v hýždi překřížené nohy. Klidně dýchej; sekundy zapisuj na stranu této nohy. Uvolni křížení a potom vystřídej stranu.","Use the hands to sit a little taller until you feel a comfortable stretch in the crossed-leg buttock. Breathe easily and record seconds for that leg. Release the crossing before changing sides."],"pro":["Lehčí: opěrné chodidlo dál od těla a větší opora rukou; pokud vadí zápěstí, zvol čtyřku vleže. Náročnější: přibliž chodidlo po malých krocích bez páčení kolena a tlačení trupu do nepohodlí. Není nutné zvyšovat délku výdrže.","Easier: move the supporting foot farther away and use more hand support; choose a supine figure four if the wrists are uncomfortable. More demanding: bring the foot closer in small steps without levering the knee or forcing the torso into discomfort. A longer hold is not required."]},"taxonomy":{"regions":["hips"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"equipmentRequirements":[["telo"]],"priority":1,"aliases":["floor figure four"]},"policy":{"id":"ig27_floor_figure_four","measurementType":"DURATION","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_floor_figure_four","atlasId":"ig27_floor_figure_four","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"f29a0b8bc64c65fac0356a0e688bf3b4cae457dae827f19621035f0ab58a962f","thumb":"/expansion-atlas/ig27_floor_figure_four-original-256.webp","detail":"/expansion-atlas/ig27_floor_figure_four-original-960.webp","inkThumb":"/expansion-atlas/ig27_floor_figure_four-ink-256.webp","inkDetail":"/expansion-atlas/ig27_floor_figure_four-ink-960.webp","fillThumb":"/expansion-atlas/ig27_floor_figure_four-fill-256.webp","fillDetail":"/expansion-atlas/ig27_floor_figure_four-fill-960.webp"},"sourceSha256":"f29a0b8bc64c65fac0356a0e688bf3b4cae457dae827f19621035f0ab58a962f","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"307a2572b65b1cb0":{"fields":{"id":"ig27_floor_figure_four","cz":"Čtyřka v sedu na zemi","en":"Floor-Seated Figure-Four Stretch","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":20,"unilateral":true,"sideMode":"perSide","focus":["S oporou dlaní najdi mírný tah v hýždi překřížené nohy bez tlaku v koleni.","Use palm support to find a mild stretch in the crossed-leg buttock without knee pressure."],"startPosition":["Sedni na zem, opři dlaně za boky a pokrč obě kolena. Pravý kotník polož přes levé stehno těsně nad kolenem. Levé chodidlo zůstává opřené.","Sit on the floor with palms behind the hips and both knees bent. Rest the right ankle across the left thigh just above the knee. Keep the left foot grounded."],"execution":["S oporou rukou se posaď o trochu vzpřímeněji, až ucítíš pohodlný tah v hýždi překřížené nohy. Klidně dýchej; sekundy zapisuj na stranu této nohy. Uvolni křížení a potom vystřídej stranu.","Use the hands to sit a little taller until you feel a comfortable stretch in the crossed-leg buttock. Breathe easily and record seconds for that leg. Release the crossing before changing sides."],"watchFor":["Netlač rukou na křížené koleno ani nepáč chodidlo. Kotník leží na stehně, ne přímo na čéšce. Při tlaku v koleni pozici uvolni.","Do not press on the crossed knee or lever the foot. Rest the ankle on the thigh, not directly on the kneecap. Ease out if you feel pressure in the knee."]},"progression":["Lehčí: opěrné chodidlo dál od těla a větší opora rukou; pokud vadí zápěstí, zvol čtyřku vleže. Náročnější: přibliž chodidlo po malých krocích bez páčení kolena a tlačení trupu do nepohodlí. Není nutné zvyšovat délku výdrže.","Easier: move the supporting foot farther away and use more hand support; choose a supine figure four if the wrists are uncomfortable. More demanding: bring the foot closer in small steps without levering the knee or forcing the torso into discomfort. A longer hold is not required."]}}},"ig27_bench_hip_flexor":{"id":"ig27_bench_hip_flexor","segment":"H","edits":{"eq":["flat_bench"],"pos":["Sedni na konec nízké pevné lavice dostatečně dlouhé a široké pro celé tělo. S oporou rukou přejdi do lehu; hlava, trup i pánev zůstávají podepřené. Přitáhni obě nohy k trupu a jedno stehno přidrž rukama.","Sit at the end of a low stable bench long and wide enough to support the body. Use your hands to move into lying; keep the head, trunk and pelvis supported. Draw both legs toward the trunk and hold one thigh with the hands."],"exe":["Druhou nohu nech pomalu klesat za konec lavice s volně pokrčeným kolenem. Zastav při mírném tahu vpředu v kyčli a klidně dýchej; zapisuj sekundy na stranu klesající nohy. Před výměnou nebo posazením vrať nohu na lavici a použij oporu rukou.","Slowly lower the other leg past the end of the bench with the knee comfortably bent. Stop at a mild front-hip stretch and breathe easily; record seconds for the lowered leg. Return the leg to the bench and use hand support before switching or sitting up."],"wat":["Pánev nesmí sklouznout z konce a větší pokles nezískávej výrazným prohnutím beder. Chodidlo nemusí dosáhnout země. Nenech druhého člověka tlačit stehno dolů; při nejistém vstupu nebo opoře zvol dostupnější polohu na zemi.","Keep the pelvis from sliding off the end and do not gain a larger drop by strongly arching the lower back. The foot need not reach the floor. Do not let another person push the thigh down; choose a more accessible floor position if entry or support feels uncertain."],"pro":["Lehčí: menší pokles nebo stabilní opora pod klesajícím chodidlem. Náročnější: malá změna poklesu při stejné opoře trupu a pánve. Závaží ani delší čas nejsou povinnou progresí.","Easier: a smaller drop or stable support under the lowered foot. More demanding: a small change in the drop with the same trunk and pelvic support. Added weights or longer holds are not required progression."],"equipmentDetail":["Nízká pevná rovná lavice s dostatečnou délkou a šířkou pro hlavu, trup i pánev; samotná malá bedna nestačí. Opora pod chodidlem je volitelná regrese.","A low stable flat bench long and wide enough to support the head, trunk and pelvis; a small box alone is insufficient. Foot support is an optional regression."]},"taxonomy":{"regions":["hips"],"secondaryRegions":["thighs"],"movements":["joint"],"focus":["mobility"],"positions":["supine"],"supports":["chair_bench"],"equipmentRequirements":[["flat_bench"]],"priority":2,"aliases":["bench hip flexor stretch"]},"policy":{"id":"ig27_bench_hip_flexor","measurementType":"DURATION","loadMode":"none","sideMode":"perSide","requirements":[["flat_bench"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ig27_bench_hip_flexor","atlasId":"ig27_bench_hip_flexor","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"aedb26d7867fb8f7d48455ba40e1cff7069371e663aa79733ee11a8f4f5d798a","thumb":"/expansion-atlas/ig27_bench_hip_flexor-original-256.webp","detail":"/expansion-atlas/ig27_bench_hip_flexor-original-960.webp","inkThumb":"/expansion-atlas/ig27_bench_hip_flexor-ink-256.webp","inkDetail":"/expansion-atlas/ig27_bench_hip_flexor-ink-960.webp","fillThumb":"/expansion-atlas/ig27_bench_hip_flexor-fill-256.webp","fillDetail":"/expansion-atlas/ig27_bench_hip_flexor-fill-960.webp"},"sourceSha256":"aedb26d7867fb8f7d48455ba40e1cff7069371e663aa79733ee11a8f4f5d798a","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"f67f89a394009474":{"fields":{"id":"ig27_bench_hip_flexor","cz":"Protažení přední strany kyčle vleže na lavici","en":"Bench-Supine Hip-Flexor Stretch","pat":"mobilita","eq":["flat_bench"],"measurementType":"DURATION","defaultRestSec":20,"unilateral":true,"sideMode":"perSide","focus":["Druhou nohu nech pomalu klesat za konec lavice s volně pokrčeným kolenem.","Slowly lower the other leg past the end of the bench with the knee comfortably bent."],"startPosition":["Sedni na konec nízké pevné lavice dostatečně dlouhé a široké pro celé tělo. S oporou rukou přejdi do lehu; hlava, trup i pánev zůstávají podepřené. Přitáhni obě nohy k trupu a jedno stehno přidrž rukama.","Sit at the end of a low stable bench long and wide enough to support the body. Use your hands to move into lying; keep the head, trunk and pelvis supported. Draw both legs toward the trunk and hold one thigh with the hands."],"execution":["Druhou nohu nech pomalu klesat za konec lavice s volně pokrčeným kolenem. Zastav při mírném tahu vpředu v kyčli a klidně dýchej; zapisuj sekundy na stranu klesající nohy. Před výměnou nebo posazením vrať nohu na lavici a použij oporu rukou.","Slowly lower the other leg past the end of the bench with the knee comfortably bent. Stop at a mild front-hip stretch and breathe easily; record seconds for the lowered leg. Return the leg to the bench and use hand support before switching or sitting up."],"watchFor":["Pánev nesmí sklouznout z konce a větší pokles nezískávej výrazným prohnutím beder. Chodidlo nemusí dosáhnout země. Nenech druhého člověka tlačit stehno dolů; při nejistém vstupu nebo opoře zvol dostupnější polohu na zemi.","Keep the pelvis from sliding off the end and do not gain a larger drop by strongly arching the lower back. The foot need not reach the floor. Do not let another person push the thigh down; choose a more accessible floor position if entry or support feels uncertain."]},"progression":["Lehčí: menší pokles nebo stabilní opora pod klesajícím chodidlem. Náročnější: malá změna poklesu při stejné opoře trupu a pánve. Závaží ani delší čas nejsou povinnou progresí.","Easier: a smaller drop or stable support under the lowered foot. More demanding: a small change in the drop with the same trunk and pelvic support. Added weights or longer holds are not required progression."]}}},"frog":{"id":"frog","segment":"I","edits":{"hd":null,"pos":["Z kleku opři ruce před sebe a rozsuň kolena jen do pohodlné šířky. Holeně nech směřovat dozadu, chodidla ven. Můžeš se snížit na předloktí; kolena případně podlož.","From kneeling, support yourself on your hands and open the knees only as wide as comfortable. Let the shins point backward and the feet outward. You may lower onto the forearms; pad the knees if needed."],"exe":["Pomalu posuň pánev trochu vzad a vrať se. Rozsah zvol podle mírného tahu na vnitřní straně stehen; můžeš v pohodlné poloze krátce zůstat. Zapisuj čas této klidné pohybové série, nikoli počet zhoupnutí.","Slowly move the pelvis a little backward and return. Use a range with a mild inner-thigh stretch; you may pause in a comfortable position. Record the time of this gentle mobility set, not the number of rocks."],"wat":["Není cílem dostat pánev na zem nebo kolena co nejdál. Zůstaň opřený a dýchej; při tlaku či bolesti v koleni nebo třísle zkrať rozsah, případně polohu opusť. Záda nemusíš násilně rovnat.","The aim is not to reach the floor with the pelvis or spread the knees as far as possible. Stay supported and breathe; reduce the range or leave the position if the knee or groin feels pinched or painful. Do not force the back into a rigid shape."],"foc":["Mírný tah na vnitřní straně stehen a klidný přesun pánve.","A mild inner-thigh stretch and a controlled pelvic shift."],"pro":["Lehčí: užší kolena a menší pohyb. Dále můžeš zkusit o trochu větší pohodlný rozsah. Větší šířka ani delší čas nejsou povinný postup k rozštěpu.","Easier: narrower knees and a smaller movement. Later, try a slightly larger comfortable range. Greater width or more time is not a compulsory route to a middle split."],"source":{"author":"GMB Fitness","document":"Hip Mobility Exercises: Frog Hip Stretch","url":"https://gmb.io/hip-mobility/","scope":"Technique-family reference for supported gentle rocking and optional pauses. Independent wording and timed-set convention; no prescribed GMB dose, contract-relax method or health-outcome claim."}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["quadruped"],"supports":["hand_support","forearm_support"],"priority":2,"aliases":["žabák","frog stretch","frog rock"],"equipmentRequirements":[["telo"]]},"policy":{"id":"frog","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/frog-89fbc7a5059da1f1.mp4"]},"art":{"appId":"frog","atlasId":"frog","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5e77e54490d7bba9ff6139a8272016d46c341e10edf249226e245b0706afd03f","thumb":"/unified-atlas/frog-ad873b6e154c90d4-thumb.webp","detail":"/unified-atlas/frog-cebbf8ccb596b7f8-detail.webp","inkThumb":"/unified-atlas/frog-ea357d5add16d5f8-inkThumb.webp","inkDetail":"/unified-atlas/frog-9c5f2df7cfccb600-inkDetail.webp","fillThumb":"/unified-atlas/frog-7c65727fb44a20ce-fillThumb.webp","fillDetail":"/unified-atlas/frog-6d44848a7d82dc42-fillDetail.webp"},"sourceSha256":"5e77e54490d7bba9ff6139a8272016d46c341e10edf249226e245b0706afd03f","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"cd3af2562a4f60e7":{"fields":{"id":"frog","cz":"Žabák","en":"Frog Stretch","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Mírný tah na vnitřní straně stehen a klidný přesun pánve.","A mild inner-thigh stretch and a controlled pelvic shift."],"startPosition":["Z kleku opři ruce před sebe a rozsuň kolena jen do pohodlné šířky. Holeně nech směřovat dozadu, chodidla ven. Můžeš se snížit na předloktí; kolena případně podlož.","From kneeling, support yourself on your hands and open the knees only as wide as comfortable. Let the shins point backward and the feet outward. You may lower onto the forearms; pad the knees if needed."],"execution":["Pomalu posuň pánev trochu vzad a vrať se. Rozsah zvol podle mírného tahu na vnitřní straně stehen; můžeš v pohodlné poloze krátce zůstat. Zapisuj čas této klidné pohybové série, nikoli počet zhoupnutí.","Slowly move the pelvis a little backward and return. Use a range with a mild inner-thigh stretch; you may pause in a comfortable position. Record the time of this gentle mobility set, not the number of rocks."],"watchFor":["Není cílem dostat pánev na zem nebo kolena co nejdál. Zůstaň opřený a dýchej; při tlaku či bolesti v koleni nebo třísle zkrať rozsah, případně polohu opusť. Záda nemusíš násilně rovnat.","The aim is not to reach the floor with the pelvis or spread the knees as far as possible. Stay supported and breathe; reduce the range or leave the position if the knee or groin feels pinched or painful. Do not force the back into a rigid shape."]},"progression":["Lehčí: užší kolena a menší pohyb. Dále můžeš zkusit o trochu větší pohodlný rozsah. Větší šířka ani delší čas nejsou povinný postup k rozštěpu.","Easier: narrower knees and a smaller movement. Later, try a slightly larger comfortable range. Greater width or more time is not a compulsory route to a middle split."]}}},"butterfly":{"id":"butterfly","segment":"I","edits":{"hd":null,"pos":["Sedni si a spoj chodidla před sebou. Paty nech v pohodlné vzdálenosti od pánve, kolena do stran. Sed můžeš lehce podložit; chodidla nebo kotníky jen volně přidržuj.","Sit with the soles together in front of you. Keep a comfortable distance between the heels and pelvis, with knees out to the sides. You may raise the seat slightly; hold the feet or ankles lightly."],"exe":["V pohodlném sedu nech kolena vlastní tíhou klesnout, kam mohou. Klidně dýchej a drž podle plánu. Zapisuj sekundy výdrže; kolena nemusí dosáhnout na zem.","Let the knees settle under their own weight in a comfortable seated position. Breathe calmly and hold as planned. Record seconds held; the knees do not need to reach the floor."],"wat":["Netlač lokty ani rukama kolena dolů a nepruž. Při tlaku v koleni nebo třísle povol polohu. Podložení stehen může pomoci pohodlně zůstat v sedu.","Do not press the knees downward with the elbows or hands, and do not bounce. Ease the position if the knee or groin feels pinched. Supporting the thighs can make the seated hold more comfortable."],"foc":["Pohodlná poloha kyčlí s mírným tahem na vnitřní straně stehen.","A comfortable hip position with a mild inner-thigh stretch."],"pro":["Uprav vzdálenost chodidel a výšku sedu podle pohodlí. Mírný náklon trupu je volitelná změna polohy, ne podmínka lepšího výsledku. Čas výdrže vol podle plánu.","Adjust foot distance and seat height for comfort. A small forward lean is an optional position change, not a requirement for a better result. Choose the hold duration in the plan."],"source":{"author":"Health and Wellbeing Queensland","document":"Butterfly pose","url":"https://hw.qld.gov.au/physical-activity/butterfly-pose/","scope":"Seated-position reference with optional support and no bouncing. Independent wording and individual dose; not a treatment or injury-prevention claim."}},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["unsupported"],"priority":1,"aliases":["motýlek","motýl","butterfly stretch"],"equipmentRequirements":[["telo"]]},"policy":{"id":"butterfly","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/butterfly-dcad3c09da10280d.mp4"]},"art":{"appId":"butterfly","atlasId":"butterfly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"3b3509e8df2c7b22e2772f35a3e3aefd60448be83ba66fbb3ed78f3838163715","thumb":"/unified-atlas/butterfly-28272d5331588e34-thumb.webp","detail":"/unified-atlas/butterfly-3acfe2264fe53b72-detail.webp","inkThumb":"/unified-atlas/butterfly-5c6cb4db45c48fdf-inkThumb.webp","inkDetail":"/unified-atlas/butterfly-1dd8080a1d4e3145-inkDetail.webp","fillThumb":"/unified-atlas/butterfly-f086c5be5a5a7aec-fillThumb.webp","fillDetail":"/unified-atlas/butterfly-fecd732cba45f2b9-fillDetail.webp"},"sourceSha256":"3b3509e8df2c7b22e2772f35a3e3aefd60448be83ba66fbb3ed78f3838163715","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"272a69f8f6ad43f5":{"fields":{"id":"butterfly","cz":"Motýl","en":"Butterfly","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pohodlná poloha kyčlí s mírným tahem na vnitřní straně stehen.","A comfortable hip position with a mild inner-thigh stretch."],"startPosition":["Sedni si a spoj chodidla před sebou. Paty nech v pohodlné vzdálenosti od pánve, kolena do stran. Sed můžeš lehce podložit; chodidla nebo kotníky jen volně přidržuj.","Sit with the soles together in front of you. Keep a comfortable distance between the heels and pelvis, with knees out to the sides. You may raise the seat slightly; hold the feet or ankles lightly."],"execution":["V pohodlném sedu nech kolena vlastní tíhou klesnout, kam mohou. Klidně dýchej a drž podle plánu. Zapisuj sekundy výdrže; kolena nemusí dosáhnout na zem.","Let the knees settle under their own weight in a comfortable seated position. Breathe calmly and hold as planned. Record seconds held; the knees do not need to reach the floor."],"watchFor":["Netlač lokty ani rukama kolena dolů a nepruž. Při tlaku v koleni nebo třísle povol polohu. Podložení stehen může pomoci pohodlně zůstat v sedu.","Do not press the knees downward with the elbows or hands, and do not bounce. Ease the position if the knee or groin feels pinched. Supporting the thighs can make the seated hold more comfortable."]},"progression":["Uprav vzdálenost chodidel a výšku sedu podle pohodlí. Mírný náklon trupu je volitelná změna polohy, ne podmínka lepšího výsledku. Čas výdrže vol podle plánu.","Adjust foot distance and seat height for comfort. A small forward lean is an optional position change, not a requirement for a better result. Choose the hold duration in the plan."]}}},"ex26_mob_adductor_rock":{"id":"ex26_mob_adductor_rock","segment":"I","edits":{"pos":["Opři dlaně pod ramena a jedno koleno pod kyčel. Druhou nohu natáhni do strany a opři chodidlo. Šířku zvol tak, abys mohl zůstat v klidné opoře.","Place the hands under the shoulders and one knee under the hip. Extend the other leg sideways with its foot supported on the floor. Choose a width that lets you remain comfortably supported."],"exe":["Pomalu posuň pánev dozadu k patě pokrčené nohy a vrať se do výchozí polohy. Jeden posun a návrat jsou jedno opakování. Stranu zapisuj podle natažené nohy a po sérii ji vystřídej.","Slowly move the pelvis backward toward the bent-leg heel, then return to the start. One shift and return is one repetition. Record the side of the straight leg and change sides after the set."],"wat":["Pánev výrazně neotáčej a rozsah nevyháněj tlakem do kolena či třísla. Hledej mírný tah na vnitřní straně nataženého stehna. Stačí pohodlná poloha zad a plynulý návrat.","Avoid a large pelvic turn and do not force range through pressure in the knee or groin. Look for a mild stretch along the inner straight-leg thigh. A comfortable back position and smooth return are enough."],"foc":["Posun v kyčli s nataženou nohou do strany, ne rotace trupu.","A hip shift with the other leg out to the side, without a trunk rotation."],"pro":["Lehčí: užší postavení a kratší posun. Dále zkus pomalejší návrat nebo trochu větší pohodlný rozsah; není nutné sednout až na patu.","Easier: a narrower setup and shorter shift. Later, try a slower return or slightly more comfortable range; reaching the heel is not required."]},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["quadruped"],"supports":["hand_support"],"priority":1,"aliases":["adductor rock back","adductor rockback","adduktory","posun pánve vzad"],"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_adductor_rock","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_adductor_mobility"},"art":{"appId":"ex26_mob_adductor_rock","atlasId":"ex26_mob_adductor_rock","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"5f25624b95668d84d868b7e516e094d8fcb00503a8615da9f57c506df975ec5e","thumb":"/expansion-atlas/ex26_mob_adductor_rock-original-256.webp","detail":"/expansion-atlas/ex26_mob_adductor_rock-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_adductor_rock-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_adductor_rock-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_adductor_rock-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_adductor_rock-fill-960.webp"},"sourceSha256":"5f25624b95668d84d868b7e516e094d8fcb00503a8615da9f57c506df975ec5e","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"79b4ad65cf4d16a6":{"fields":{"id":"ex26_mob_adductor_rock","cz":"Přenášení pánve vzad s nohou do strany","en":"Adductor Rock-Back","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Posun v kyčli s nataženou nohou do strany, ne rotace trupu.","A hip shift with the other leg out to the side, without a trunk rotation."],"startPosition":["Opři dlaně pod ramena a jedno koleno pod kyčel. Druhou nohu natáhni do strany a opři chodidlo. Šířku zvol tak, abys mohl zůstat v klidné opoře.","Place the hands under the shoulders and one knee under the hip. Extend the other leg sideways with its foot supported on the floor. Choose a width that lets you remain comfortably supported."],"execution":["Pomalu posuň pánev dozadu k patě pokrčené nohy a vrať se do výchozí polohy. Jeden posun a návrat jsou jedno opakování. Stranu zapisuj podle natažené nohy a po sérii ji vystřídej.","Slowly move the pelvis backward toward the bent-leg heel, then return to the start. One shift and return is one repetition. Record the side of the straight leg and change sides after the set."],"watchFor":["Pánev výrazně neotáčej a rozsah nevyháněj tlakem do kolena či třísla. Hledej mírný tah na vnitřní straně nataženého stehna. Stačí pohodlná poloha zad a plynulý návrat.","Avoid a large pelvic turn and do not force range through pressure in the knee or groin. Look for a mild stretch along the inner straight-leg thigh. A comfortable back position and smooth return are enough."]},"progression":["Lehčí: užší postavení a kratší posun. Dále zkus pomalejší návrat nebo trochu větší pohodlný rozsah; není nutné sednout až na patu.","Easier: a narrower setup and shorter shift. Later, try a slower return or slightly more comfortable range; reaching the heel is not required."]}}},"ex26_mob_travel_butterfly":{"id":"ex26_mob_travel_butterfly","segment":"I","edits":{"ez":null,"pos":["Sedni s nohama před sebe, kolena mohou zůstat trochu povolená. Opři dlaně vedle boků nebo mírně za nimi tak, abys mohl pánev kontrolovaně odlehčit.","Sit with the legs in front, allowing a little knee bend. Place the palms beside or slightly behind the hips so you can unweight the pelvis with control."],"exe":["Pokrč nohy, spoj chodidla a s pomocí rukou posuň pánev k patám do motýlku. Potom se vrať do výchozího sedu. Celá cesta tam a zpět je jedno opakování; zapojují se obě nohy současně.","Bend the legs, bring the soles together and use the hands to move the pelvis toward the heels into butterfly. Return to the starting sit. The whole out-and-back journey is one repetition, with both legs working together."],"wat":["Kolena netlač rukama dolů a nedopadej pánví na zem. Zkrať posun, pokud ruce nebo kyčle nedovolí klidný přechod. Nohy nemusí být ve výchozím sedu násilně propnuté.","Do not push the knees down or drop the pelvis onto the floor. Shorten the shift if the hands or hips cannot support a controlled transition. Do not force the knees straight in the starting sit."],"foc":["Plynulý přechod mezi dvěma sedy s oporou rukou.","A smooth transition between two seated positions with hand support."],"pro":["Lehčí: kratší posun a větší pomoc rukou. Dále zkus plynulejší přechod při stejném pohodlí. Vyšší sed není automaticky lehčí varianta tohoto přesunu.","Easier: a shorter shift and more hand assistance. Later, aim for a smoother transition with the same comfort. A higher seat is not automatically an easier version of this transition."]},"taxonomy":{"regions":["hips","thighs"],"secondaryRegions":[],"movements":["joint"],"focus":["mobility"],"positions":["seated"],"supports":["hand_support"],"priority":2,"aliases":["traveling butterfly","travelling butterfly","přechod do motýlku"],"equipmentRequirements":[["telo"]]},"policy":{"id":"ex26_mob_travel_butterfly","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"ex26_mob_travel_butterfly","atlasId":"ex26_mob_travel_butterfly","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"f9c5a5c45890aefb572391429b4d13179882ae85add2c23e715a1b4cb5658fa0","thumb":"/expansion-atlas/ex26_mob_travel_butterfly-original-256.webp","detail":"/expansion-atlas/ex26_mob_travel_butterfly-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_travel_butterfly-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_travel_butterfly-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_travel_butterfly-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_travel_butterfly-fill-960.webp"},"sourceSha256":"f9c5a5c45890aefb572391429b4d13179882ae85add2c23e715a1b4cb5658fa0","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"f8ea9eb14e31eaff":{"fields":{"id":"ex26_mob_travel_butterfly","cz":"Přechody mezi dlouhým sedem a motýlkem","en":"Traveling Butterfly","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Plynulý přechod mezi dvěma sedy s oporou rukou.","A smooth transition between two seated positions with hand support."],"startPosition":["Sedni s nohama před sebe, kolena mohou zůstat trochu povolená. Opři dlaně vedle boků nebo mírně za nimi tak, abys mohl pánev kontrolovaně odlehčit.","Sit with the legs in front, allowing a little knee bend. Place the palms beside or slightly behind the hips so you can unweight the pelvis with control."],"execution":["Pokrč nohy, spoj chodidla a s pomocí rukou posuň pánev k patám do motýlku. Potom se vrať do výchozího sedu. Celá cesta tam a zpět je jedno opakování; zapojují se obě nohy současně.","Bend the legs, bring the soles together and use the hands to move the pelvis toward the heels into butterfly. Return to the starting sit. The whole out-and-back journey is one repetition, with both legs working together."],"watchFor":["Kolena netlač rukama dolů a nedopadej pánví na zem. Zkrať posun, pokud ruce nebo kyčle nedovolí klidný přechod. Nohy nemusí být ve výchozím sedu násilně propnuté.","Do not push the knees down or drop the pelvis onto the floor. Shorten the shift if the hands or hips cannot support a controlled transition. Do not force the knees straight in the starting sit."]},"progression":["Lehčí: kratší posun a větší pomoc rukou. Dále zkus plynulejší přechod při stejném pohodlí. Vyšší sed není automaticky lehčí varianta tohoto přesunu.","Easier: a shorter shift and more hand assistance. Later, aim for a smoother transition with the same comfort. A higher seat is not automatically an easier version of this transition."]}}},"pancake":{"id":"pancake","segment":"J","edits":{"cz":"Předklon v roznoženém sedu · pancake","en":"Seated Straddle Forward Fold · Pancake","mp":["add","ham"],"ms":["glu","low"],"ez":null,"hd":null,"pos":["Sedni do pohodlného roznožení. Kolena a špičky směřují přibližně vzhůru, ruce polož před sebe. Šířku sedu i pokrčení kolen přizpůsob svému rozsahu.","Sit in a comfortable straddle. Knees and toes face roughly upward; place the hands in front. Adjust the width and knee bend to your available range."],"exe":["Naklop pánev vpřed a pomalu se předkloň mezi nohy. Ruce posuň jen tak daleko, abys mohl volně dýchat a vnímal snesitelný tah na vnitřní a zadní straně stehen. Vydrž po dobu zadanou v plánu a pomalu se vrať. Zapisují se sekundy výdrže, ne počet předklonů.","Tip the pelvis forward and slowly fold between the legs. Move the hands only as far as you can breathe freely and feel a tolerable stretch along the inner and back thighs. Hold for the planned time and return slowly. Record seconds held, not the number of folds."],"wat":["Pro tuto variantu hledej pohyb v kyčlích; dosah rukou sám neukazuje rozsah kyčlí. Netlač hrudník k podlaze ani kolena do propnutí. Pokud se objevuje ostrá bolest, brnění nebo sevření v kyčli, uber rozsah či skonči.","For this version, focus on movement at the hips; hand reach alone does not show hip range. Do not force the chest to the floor or lock the knees. Reduce the range or stop if sharp pain, tingling or hip pinching appears."],"pro":["Lehčí: užší roznožení, menší předklon, měkčí kolena nebo pevné podložení sedu. Plynulost a pohodlný dech jsou vhodným cílem i bez větší hloubky. Provaz, hrudník na zemi ani delší výdrž nejsou povinným pokračováním.","Easier: a narrower straddle, smaller fold, softer knees or a firm support under the seat. Smooth movement and comfortable breathing are useful goals without going deeper. A middle split, chest on the floor or a longer hold is not a required next step."],"foc":["Pohodlné roznožení, předklon z kyčlí a klidný dech.","Comfortable straddle, fold from the hips and breathe easily."],"equipmentDetail":["Základní varianta je na zemi bez povinné pomůcky. Podložka a pevně složená deka pod sed jsou volitelné úpravy.","The base version is on the floor with no required equipment. A mat and a firmly folded blanket under the seat are optional adjustments."]},"taxonomy":{"regions":["thighs"],"secondaryRegions":["hips"],"movements":["joint"],"focus":["mobility"],"equipmentRequirements":[["telo"]],"priority":1,"positions":["seated"],"supports":["hand_support"],"aliases":["pancake","pancake stretch","straddle fold","předklon v roznožení"]},"policy":{"id":"pancake","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"blockedMotionSources":["/exercise-motion/pancake-6cb818d98f49ed11.mp4"]},"art":{"appId":"pancake","atlasId":"pancake","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"46a6ea48c1cc837708aca41a00b7b973eaa2a7fb0e75f77ed94d715c7f0fba3b","thumb":"/unified-atlas/pancake-c65d5d1f036f393a-thumb.webp","detail":"/unified-atlas/pancake-c5935637b541e682-detail.webp","inkThumb":"/unified-atlas/pancake-b92f3a487c75adf6-inkThumb.webp","inkDetail":"/unified-atlas/pancake-b8702103adb41c61-inkDetail.webp","fillThumb":"/unified-atlas/pancake-a03490808ecb90df-fillThumb.webp","fillDetail":"/unified-atlas/pancake-32af7731f1e0f27e-fillDetail.webp"},"sourceSha256":"46a6ea48c1cc837708aca41a00b7b973eaa2a7fb0e75f77ed94d715c7f0fba3b","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"2534e3dfda417291":{"fields":{"id":"pancake","cz":"Předklon v roznoženém sedu · pancake","en":"Seated Straddle Forward Fold · Pancake","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Pohodlné roznožení, předklon z kyčlí a klidný dech.","Comfortable straddle, fold from the hips and breathe easily."],"startPosition":["Sedni do pohodlného roznožení. Kolena a špičky směřují přibližně vzhůru, ruce polož před sebe. Šířku sedu i pokrčení kolen přizpůsob svému rozsahu.","Sit in a comfortable straddle. Knees and toes face roughly upward; place the hands in front. Adjust the width and knee bend to your available range."],"execution":["Naklop pánev vpřed a pomalu se předkloň mezi nohy. Ruce posuň jen tak daleko, abys mohl volně dýchat a vnímal snesitelný tah na vnitřní a zadní straně stehen. Vydrž po dobu zadanou v plánu a pomalu se vrať. Zapisují se sekundy výdrže, ne počet předklonů.","Tip the pelvis forward and slowly fold between the legs. Move the hands only as far as you can breathe freely and feel a tolerable stretch along the inner and back thighs. Hold for the planned time and return slowly. Record seconds held, not the number of folds."],"watchFor":["Pro tuto variantu hledej pohyb v kyčlích; dosah rukou sám neukazuje rozsah kyčlí. Netlač hrudník k podlaze ani kolena do propnutí. Pokud se objevuje ostrá bolest, brnění nebo sevření v kyčli, uber rozsah či skonči.","For this version, focus on movement at the hips; hand reach alone does not show hip range. Do not force the chest to the floor or lock the knees. Reduce the range or stop if sharp pain, tingling or hip pinching appears."]},"progression":["Lehčí: užší roznožení, menší předklon, měkčí kolena nebo pevné podložení sedu. Plynulost a pohodlný dech jsou vhodným cílem i bez větší hloubky. Provaz, hrudník na zemi ani delší výdrž nejsou povinným pokračováním.","Easier: a narrower straddle, smaller fold, softer knees or a firm support under the seat. Smooth movement and comfortable breathing are useful goals without going deeper. A middle split, chest on the floor or a longer hold is not a required next step."]}}},"toetouch":{"id":"toetouch","segment":"J","edits":{"hd":null,"pos":["Postav se s chodidly u sebe nebo mírně od sebe. Váhu rozlož přes chodidla a kolena nech podle potřeby pokrčená.","Stand with the feet together or slightly apart. Spread the weight across the feet and bend the knees as needed."],"exe":["Pomalu se předkloň z kyčlí a nech paže i hlavu volně klesnout. Zvol pohodlnou polohu s mírným tahem v zadní straně stehen a klidně dýchej po zadanou dobu. Pro návrat pokrč kolena, podle potřeby opři ruce o stehna a pomalu se narovnej. Zapisuj sekundy výdrže.","Fold slowly from the hips and let the arms and head hang comfortably. Find a comfortable position with a mild stretch along the back thighs and breathe for the planned time. To return, bend the knees, rest the hands on the thighs if helpful and rise slowly. Record seconds held."],"wat":["Dotyk země není podmínkou. Záda mohou v pohodlném předklonu měnit tvar; nenutí se ani úplné napřímení, ani hluboké zakulacení. Nehoupej se do krajní polohy a nenuť kolena do propnutí. Při bolesti či brnění ustup.","Touching the floor is not required. The back can change shape in a comfortable fold; neither a perfectly straight spine nor a deep round is forced. Do not bounce into the end range or lock the knees. Ease out if pain or tingling occurs."],"pro":["Lehčí: více pokrčená kolena nebo menší předklon. Případná opora rukou je samostatná úprava. Postupem může být pohodlnější stejná poloha; zatížený Jeffersonův předklon není automatický další krok.","Easier: more knee bend or a smaller fold. Hand support is a separate adjustment if needed. Feeling more comfortable in the same position can be progress; a loaded Jefferson curl is not an automatic next step."],"foc":["Předklon v pohodlném rozsahu, bez povinného dotyku podlahy.","Fold within a comfortable range; reaching the floor is optional."],"equipmentDetail":["Bez povinné pomůcky, na pevném neklouzavém podkladu. Opora rukou o vlastní stehna nevyžaduje další vybavení.","No required equipment; use a firm non-slip surface. Resting hands on your own thighs needs no extra equipment."]},"taxonomy":{"regions":["thighs"],"secondaryRegions":["hips","back"],"movements":["joint"],"focus":["mobility"],"equipmentRequirements":[["telo"]],"priority":1,"positions":["standing"],"supports":["unsupported"],"aliases":["toe touch","standing forward fold","předklon ve stoji"]},"policy":{"id":"toetouch","measurementType":"DURATION","loadMode":"none","sideMode":"none","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false},"art":{"appId":"toetouch","atlasId":"toetouch","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"8dfb461b1b83fe8645d96770a0e9c3ee2c82f6cc788efac7a9a3f9cae46dd69d","thumb":"/unified-atlas/toetouch-8fff1c446cb767d2-thumb.webp","detail":"/unified-atlas/toetouch-07c4da8df539584c-detail.webp","inkThumb":"/unified-atlas/toetouch-f26d6f8835811d86-inkThumb.webp","inkDetail":"/unified-atlas/toetouch-8785d7abb557343f-inkDetail.webp","fillThumb":"/unified-atlas/toetouch-99b9245805788d2e-fillThumb.webp","fillDetail":"/unified-atlas/toetouch-d8819b5f990896ff-fillDetail.webp"},"sourceSha256":"8dfb461b1b83fe8645d96770a0e9c3ee2c82f6cc788efac7a9a3f9cae46dd69d","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"1334ea94c8fee21b":{"fields":{"id":"toetouch","cz":"Předklon ve stoji","en":"Standing Forward Fold","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Předklon v pohodlném rozsahu, bez povinného dotyku podlahy.","Fold within a comfortable range; reaching the floor is optional."],"startPosition":["Postav se s chodidly u sebe nebo mírně od sebe. Váhu rozlož přes chodidla a kolena nech podle potřeby pokrčená.","Stand with the feet together or slightly apart. Spread the weight across the feet and bend the knees as needed."],"execution":["Pomalu se předkloň z kyčlí a nech paže i hlavu volně klesnout. Zvol pohodlnou polohu s mírným tahem v zadní straně stehen a klidně dýchej po zadanou dobu. Pro návrat pokrč kolena, podle potřeby opři ruce o stehna a pomalu se narovnej. Zapisuj sekundy výdrže.","Fold slowly from the hips and let the arms and head hang comfortably. Find a comfortable position with a mild stretch along the back thighs and breathe for the planned time. To return, bend the knees, rest the hands on the thighs if helpful and rise slowly. Record seconds held."],"watchFor":["Dotyk země není podmínkou. Záda mohou v pohodlném předklonu měnit tvar; nenutí se ani úplné napřímení, ani hluboké zakulacení. Nehoupej se do krajní polohy a nenuť kolena do propnutí. Při bolesti či brnění ustup.","Touching the floor is not required. The back can change shape in a comfortable fold; neither a perfectly straight spine nor a deep round is forced. Do not bounce into the end range or lock the knees. Ease out if pain or tingling occurs."]},"progression":["Lehčí: více pokrčená kolena nebo menší předklon. Případná opora rukou je samostatná úprava. Postupem může být pohodlnější stejná poloha; zatížený Jeffersonův předklon není automatický další krok.","Easier: more knee bend or a smaller fold. Hand support is a separate adjustment if needed. Feeling more comfortable in the same position can be progress; a loaded Jefferson curl is not an automatic next step."]}}},"ex26_mob_straddle_compression":{"id":"ex26_mob_straddle_compression","segment":"L","edits":{"pos":["Sedni si do pohodlného roznožení. Dlaně opři o zem po stranách jednoho stehna a pánev nech na podlaze. Pracovní koleno drž natažené v rozsahu, který je pro tebe pohodlný.","Sit in a comfortable straddle. Place the palms on the floor on either side of one thigh and keep the pelvis on the floor. Keep the working knee comfortably straight."],"exe":["Zvedni jednu nohu z kyčle jen tak vysoko, aby se pata odlepila od země, a pomalu ji vrať. Zdvih a návrat jsou jedno opakování na zvedané noze. Po plánované sérii vystřídej nohu.","Lift one leg from the hip just enough to clear the heel from the floor, then lower slowly. One lift and return is one repetition for the lifted leg. Change legs after the planned set."],"wat":["Nezískávej výšku záklonem trupu ani odlepením pánve. Malý zdvih je v pořádku. Šířku roznožení ani natažení kolena nevynucuj; zvolenou polohu drž během série stejnou.","Do not gain height by leaning the trunk backward or lifting the pelvis. A small lift is fine. Do not force straddle width or knee extension; keep the chosen position consistent within the set."],"pro":["Lehčí: užší sed, dlaně blíž k pánvi nebo předem zvolená mírně pokrčená pracovní noha. Náročnější může být krátká pauza či dlaně dál vpředu při klidné pánvi. Změnu polohy si poznamenej; není to povinný postup.","Easier: a narrower straddle, hands nearer the pelvis or a slightly bent working knee chosen before the set. A brief pause or hands farther forward may increase the demand while the pelvis stays still. Note setup changes; this is not a required progression."],"foc":["Malý aktivní zdvih jedné nohy; pánev zůstává na podlaze.","A small active lift of one leg with the pelvis staying on the floor."],"equipmentDetail":["Vlastní váha a opora dlaní o podlahu. Podložka je volitelná. Šířku sedu, polohu dlaní a pokrčení kolena při porovnávání sérií neměň bez poznámky.","Bodyweight with the palms supported on the floor. A mat is optional. Record changes in straddle width, hand position or knee bend when comparing sets."],"source":{"author":"Move More","document":"Unilateral straddle compression","url":"https://www.movemorevrl.com/compression-development/videos/unilateral-straddle-compression","scope":"Public publisher title and description confirm unilateral straddle compression; the subscription video was not accessed. Independent coaching text describes the existing selected illustration and counts one lift and return, without a fixed height, dose or promised outcome."}},"taxonomy":{"movements":["joint"],"priority":1,"equipmentRequirements":[["telo"]],"regions":["hips"],"secondaryRegions":["thighs","trunk"],"focus":["mobility","strength"],"positions":["seated"],"supports":["hand_support"],"aliases":["unilateral straddle compression","aktivní komprese v roznožení","zdvih paty v širokém sedu"]},"policy":{"id":"ex26_mob_straddle_compression","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_flexion","blockedMotionSources":["/exercise-motion/ex26_mob_straddle_compression-cecd4700e841e70b.mp4"]},"art":{"appId":"ex26_mob_straddle_compression","atlasId":"ex26_mob_straddle_compression","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"cc688757b91fbc435e079cd62bda3a7d64953569a6ef4385d7424a87740e19d5","thumb":"/expansion-atlas/ex26_mob_straddle_compression-original-256.webp","detail":"/expansion-atlas/ex26_mob_straddle_compression-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_straddle_compression-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_straddle_compression-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_straddle_compression-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_straddle_compression-fill-960.webp"},"sourceSha256":"cc688757b91fbc435e079cd62bda3a7d64953569a6ef4385d7424a87740e19d5","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"72151dddc6b8fff3":{"fields":{"id":"ex26_mob_straddle_compression","cz":"Zdvih nohy v širokém sedu","en":"Unilateral Straddle Compression","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Malý aktivní zdvih jedné nohy; pánev zůstává na podlaze.","A small active lift of one leg with the pelvis staying on the floor."],"startPosition":["Sedni si do pohodlného roznožení. Dlaně opři o zem po stranách jednoho stehna a pánev nech na podlaze. Pracovní koleno drž natažené v rozsahu, který je pro tebe pohodlný.","Sit in a comfortable straddle. Place the palms on the floor on either side of one thigh and keep the pelvis on the floor. Keep the working knee comfortably straight."],"execution":["Zvedni jednu nohu z kyčle jen tak vysoko, aby se pata odlepila od země, a pomalu ji vrať. Zdvih a návrat jsou jedno opakování na zvedané noze. Po plánované sérii vystřídej nohu.","Lift one leg from the hip just enough to clear the heel from the floor, then lower slowly. One lift and return is one repetition for the lifted leg. Change legs after the planned set."],"watchFor":["Nezískávej výšku záklonem trupu ani odlepením pánve. Malý zdvih je v pořádku. Šířku roznožení ani natažení kolena nevynucuj; zvolenou polohu drž během série stejnou.","Do not gain height by leaning the trunk backward or lifting the pelvis. A small lift is fine. Do not force straddle width or knee extension; keep the chosen position consistent within the set."]},"progression":["Lehčí: užší sed, dlaně blíž k pánvi nebo předem zvolená mírně pokrčená pracovní noha. Náročnější může být krátká pauza či dlaně dál vpředu při klidné pánvi. Změnu polohy si poznamenej; není to povinný postup.","Easier: a narrower straddle, hands nearer the pelvis or a slightly bent working knee chosen before the set. A brief pause or hands farther forward may increase the demand while the pelvis stays still. Note setup changes; this is not a required progression."]}}},"ex26_mob_knee_hug_release":{"id":"ex26_mob_knee_hug_release","segment":"L","edits":{"en":"Assisted Knee Lift to Active Hip-Flexion Hold","pos":["Ve stoji přitáhni pokrčené koleno rukama do pohodlné výšky. Stůj stabilně na druhé noze a trup nech přirozeně vzpřímený. Nemusíš využít nejvyšší dostupnou polohu.","While standing, use the hands to bring one bent knee to a comfortable height. Balance on the other leg with the trunk naturally upright. You do not need to use the highest available position."],"exe":["Uvolni ruce, krátce udrž koleno vlastní silou a potom nohu pomalu polož. Přitažení s dopomocí, uvolnění rukou, krátké udržení a položení nohy tvoří jedno opakování na zvedané straně. Po plánované sérii vystřídej nohu.","Release the hands, briefly maintain knee height with your own effort, then lower the foot slowly. The assisted lift, hand release, brief active hold and lowering together count as one repetition for the lifted side. Change legs after the planned set."],"wat":["Výšku neudržuj záklonem ani vytažením pánve do strany. Po uvolnění rukou může koleno mírně klesnout; příště zvol nižší polohu, kterou udržíš klidně. Dýchej a nepřitahuj koleno násilím.","Do not maintain height by leaning backward or hiking the pelvis to one side. The knee may lower slightly when the hands release; next time choose a lower position you can hold steadily. Breathe and do not pull the knee forcefully."],"pro":["Lehčí: nižší poloha kolena. Pokud omezuje rovnováha, lze jednu ruku nechat na pevné opoře a koleno přitáhnout druhou; tuto změnu si poznamenej. Delší udržení je volitelná změna úkolu, ne důvod automaticky přidávat zátěž či měnit počítání na sekundy.","Easier: a lower knee position. If balance limits the task, keep one hand on a fixed support and assist the knee with the other; note this setup change. A longer hold is an optional task change, not a reason to add load automatically or change the count to seconds."],"foc":["Po uvolnění rukou krátce udrž koleno bez záklonu trupu.","Briefly maintain knee height after releasing the hands, without leaning backward."],"equipmentDetail":["Základní varianta nevyžaduje pomůcku. Pevná opora jedné ruky je volitelná úprava při omezení rovnováhou; zapisuj ji v poznámce.","The base version requires no equipment. Fixed support for one hand is an optional balance modification; record it in the notes."]},"taxonomy":{"movements":["joint"],"priority":1,"equipmentRequirements":[["telo"]],"regions":["hips"],"secondaryRegions":["trunk"],"focus":["mobility","strength"],"positions":["standing"],"supports":[],"aliases":["standing hip flexion end range hold","assisted knee lift and active hold","aktivní udržení kolena po dopomoci"]},"policy":{"id":"ex26_mob_knee_hug_release","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_flexion","blockedMotionSources":["/exercise-motion/ex26_mob_knee_hug_release-99424d3f50701685.mp4"]},"art":{"appId":"ex26_mob_knee_hug_release","atlasId":"ex26_mob_knee_hug_release","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"723198fce07636a765c7c15ca413fed4fe64fe675587dca77bdd175e18ce76dc","thumb":"/expansion-atlas/ex26_mob_knee_hug_release-original-256.webp","detail":"/expansion-atlas/ex26_mob_knee_hug_release-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_knee_hug_release-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_knee_hug_release-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_knee_hug_release-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_knee_hug_release-fill-960.webp"},"sourceSha256":"723198fce07636a765c7c15ca413fed4fe64fe675587dca77bdd175e18ce76dc","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"37d6fd6807bfc29c":{"fields":{"id":"ex26_mob_knee_hug_release","cz":"Aktivní udržení vysokého kolena po dopomoci","en":"Assisted Knee Lift to Active Hip-Flexion Hold","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Po uvolnění rukou krátce udrž koleno bez záklonu trupu.","Briefly maintain knee height after releasing the hands, without leaning backward."],"startPosition":["Ve stoji přitáhni pokrčené koleno rukama do pohodlné výšky. Stůj stabilně na druhé noze a trup nech přirozeně vzpřímený. Nemusíš využít nejvyšší dostupnou polohu.","While standing, use the hands to bring one bent knee to a comfortable height. Balance on the other leg with the trunk naturally upright. You do not need to use the highest available position."],"execution":["Uvolni ruce, krátce udrž koleno vlastní silou a potom nohu pomalu polož. Přitažení s dopomocí, uvolnění rukou, krátké udržení a položení nohy tvoří jedno opakování na zvedané straně. Po plánované sérii vystřídej nohu.","Release the hands, briefly maintain knee height with your own effort, then lower the foot slowly. The assisted lift, hand release, brief active hold and lowering together count as one repetition for the lifted side. Change legs after the planned set."],"watchFor":["Výšku neudržuj záklonem ani vytažením pánve do strany. Po uvolnění rukou může koleno mírně klesnout; příště zvol nižší polohu, kterou udržíš klidně. Dýchej a nepřitahuj koleno násilím.","Do not maintain height by leaning backward or hiking the pelvis to one side. The knee may lower slightly when the hands release; next time choose a lower position you can hold steadily. Breathe and do not pull the knee forcefully."]},"progression":["Lehčí: nižší poloha kolena. Pokud omezuje rovnováha, lze jednu ruku nechat na pevné opoře a koleno přitáhnout druhou; tuto změnu si poznamenej. Delší udržení je volitelná změna úkolu, ne důvod automaticky přidávat zátěž či měnit počítání na sekundy.","Easier: a lower knee position. If balance limits the task, keep one hand on a fixed support and assist the knee with the other; note this setup change. A longer hold is an optional task change, not a reason to add load automatically or change the count to seconds."]}}},"ex26_mob_halfkneel_groin":{"id":"ex26_mob_halfkneel_groin","segment":"L","edits":{"pos":["Klekni si na jedno koleno přibližně pod kyčlí. Druhé chodidlo polož šikmo před sebe a do strany, koleno směřuje přibližně za prsty. Úhel chodidla a šířku postoje zvol podle pohodlí. Ruce mohou zůstat na bocích.","Kneel with one knee roughly under the hip. Place the other foot diagonally forward and out to the side, with its knee following the toes. Choose a comfortable foot angle and stance width. The hands may rest on the hips."],"exe":["Pomalu posuň pánev do strany směrem k položenému chodidlu a vrať se. Posun a návrat jsou jedno opakování. Pro tento popis strany označuj podle nohy s chodidlem na zemi; po sérii polohu nohou vyměň. Tah můžeš vnímat v jednom i obou tříslech.","Slowly shift the pelvis sideways toward the planted foot and return. One shift and return is one repetition. For this instruction, identify the side by the leg with its foot planted; switch the leg positions after the set. You may feel tension in one or both groins."],"wat":["Trup nech pohodlně vzpřímený a pohyb veď z kyčlí. Většího rozsahu nedosahuj jen otočením trupu ani tlačením kolena dovnitř. Zvol menší posun, pokud v třísle nebo koleni cítíš nepříjemný tlak.","Keep the trunk comfortably upright and move through the hips. Do not create extra range merely by rotating the trunk or pushing the knee inward. Use a smaller shift if there is uncomfortable pressure in the groin or knee."],"pro":["Lehčí: menší posun, užší postoj nebo lehká opora rukou. Rozsah můžeš zvětšit, pokud zůstane pohyb pohodlný a kontrolovaný. Přidané závaží ani co největší roznožení nejsou součástí této varianty.","Easier: a smaller shift, narrower stance or light hand support. You may increase the range while the movement stays comfortable and controlled. Added weight and a maximal straddle are not part of this version."],"foc":["Klidný boční posun pánve v polokleku a návrat.","A controlled sideways pelvic shift in half kneeling, followed by a return."],"equipmentDetail":["Vlastní váha; měkká podložka pod klečící koleno je volitelná. Opora rukou je úprava podle potřeby, ne povinné vybavení základní varianty.","Bodyweight; soft padding under the kneeling knee is optional. Hand support is an as-needed modification, not required equipment for the base version."]},"taxonomy":{"movements":["joint"],"priority":1,"equipmentRequirements":[["telo"]],"regions":["hips","thighs"],"secondaryRegions":[],"focus":["mobility"],"positions":["kneeling"],"supports":[],"aliases":["half kneeling groin opener","boční posun v polokleku","mobilita přitahovačů v polokleku"]},"policy":{"id":"ex26_mob_halfkneel_groin","measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"perSide","requirements":[["telo"]],"unknown":false,"explicitTarget":true,"manualProgression":true,"manualWarmup":true,"noAddedWeight":true,"allowEstimatedMax":false,"allowComparableRecords":false,"familyOverride":"hip_adductor_mobility"},"art":{"appId":"ex26_mob_halfkneel_groin","atlasId":"ex26_mob_halfkneel_groin","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"a614d08f4fe582938173beee44ecaf995e89a5352baaae63f77289c5e65551d2","thumb":"/expansion-atlas/ex26_mob_halfkneel_groin-original-256.webp","detail":"/expansion-atlas/ex26_mob_halfkneel_groin-original-960.webp","inkThumb":"/expansion-atlas/ex26_mob_halfkneel_groin-ink-256.webp","inkDetail":"/expansion-atlas/ex26_mob_halfkneel_groin-ink-960.webp","fillThumb":"/expansion-atlas/ex26_mob_halfkneel_groin-fill-256.webp","fillDetail":"/expansion-atlas/ex26_mob_halfkneel_groin-fill-960.webp"},"sourceSha256":"a614d08f4fe582938173beee44ecaf995e89a5352baaae63f77289c5e65551d2","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"88e6f4bdf3bfa355":{"fields":{"id":"ex26_mob_halfkneel_groin","cz":"Boční posun v polokleku pro kyčle","en":"Half-Kneeling Groin Opener","pat":"mobilita","eq":["telo"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":15,"unilateral":true,"sideMode":"perSide","focus":["Klidný boční posun pánve v polokleku a návrat.","A controlled sideways pelvic shift in half kneeling, followed by a return."],"startPosition":["Klekni si na jedno koleno přibližně pod kyčlí. Druhé chodidlo polož šikmo před sebe a do strany, koleno směřuje přibližně za prsty. Úhel chodidla a šířku postoje zvol podle pohodlí. Ruce mohou zůstat na bocích.","Kneel with one knee roughly under the hip. Place the other foot diagonally forward and out to the side, with its knee following the toes. Choose a comfortable foot angle and stance width. The hands may rest on the hips."],"execution":["Pomalu posuň pánev do strany směrem k položenému chodidlu a vrať se. Posun a návrat jsou jedno opakování. Pro tento popis strany označuj podle nohy s chodidlem na zemi; po sérii polohu nohou vyměň. Tah můžeš vnímat v jednom i obou tříslech.","Slowly shift the pelvis sideways toward the planted foot and return. One shift and return is one repetition. For this instruction, identify the side by the leg with its foot planted; switch the leg positions after the set. You may feel tension in one or both groins."],"watchFor":["Trup nech pohodlně vzpřímený a pohyb veď z kyčlí. Většího rozsahu nedosahuj jen otočením trupu ani tlačením kolena dovnitř. Zvol menší posun, pokud v třísle nebo koleni cítíš nepříjemný tlak.","Keep the trunk comfortably upright and move through the hips. Do not create extra range merely by rotating the trunk or pushing the knee inward. Use a smaller shift if there is uncomfortable pressure in the groin or knee."]},"progression":["Lehčí: menší posun, užší postoj nebo lehká opora rukou. Rozsah můžeš zvětšit, pokud zůstane pohyb pohodlný a kontrolovaný. Přidané závaží ani co největší roznožení nejsou součástí této varianty.","Easier: a smaller shift, narrower stance or light hand support. You may increase the range while the movement stays comfortable and controlled. Added weight and a maximal straddle are not part of this version."]}}},"revhyper":{"id":"revhyper","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"revhyper","viewOnly":true,"measurementType":"REPS_ONLY","loadMode":"none","sideMode":"none"},"art":{"appId":"revhyper","atlasId":"revhyper","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"563fb84e4235445138ff92d0440efc9d9a74870913267503ff24732a3e861641","thumb":"/unified-atlas/revhyper-0d430e9091f05f78-thumb.webp","detail":"/unified-atlas/revhyper-61fa15b9617f327a-detail.webp","inkThumb":"/unified-atlas/revhyper-59e3622fde2c475a-inkThumb.webp","inkDetail":"/unified-atlas/revhyper-70e4fd311ff767c3-inkDetail.webp","fillThumb":"/unified-atlas/revhyper-dbfd64d7fc352d5d-fillThumb.webp","fillDetail":"/unified-atlas/revhyper-c92d5b31ba5cc4d6-fillDetail.webp"},"sourceSha256":"563fb84e4235445138ff92d0440efc9d9a74870913267503ff24732a3e861641","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"f673e88069005656":{"fields":{"id":"revhyper","cz":"Zanožování vleže na lavici","en":"Bench Reverse Hyperextension","pat":"ohyb","eq":["lavice"],"measurementType":"REPS_ONLY","defaultRestSec":60,"unilateral":false,"sideMode":"none","focus":["Zvedej hýžděmi a zadní stranou stehen. Rozsah končí v rovině trupu.","Lift with the glutes and the backs of the thighs. The range ends level with the torso."],"startPosition":["Lehni si břichem na pevnou lavici, která se při pohybu neposune ani nepřeklopí. Podepři trup a pánev, kyčle nech u okraje a obě nohy volně pod ním. Rukama se pevně přidrž.","Lie face down on a stable bench that will not slide or tip. Support the trunk and pelvis with the hips near the edge and both legs hanging below it. Hold firmly with the hands."],"execution":["Zvedni nohy do roviny s trupem. Nahoře krátce stiskni hýždě. Pomalu dolů.","Raise the legs to the line of the torso. Squeeze the glutes briefly at the top. Lower slowly."],"watchFor":["Nešvihej a nechoď nad rovinu trupu. Při citlivých zádech řiď rozsah a zátěž podle tolerance.","No swinging, and do not go above the line of the torso. With a sensitive back, set range and load by tolerance."]},"progression":["Uprav ovládaný rozsah nebo krátkou pauzu. Přídavnou zátěž používej pouze při bezpečně vyřešeném upevnění.","Adjust controlled range or a brief pause. Use added load only with an established secure attachment."]}}},"ex26_ball_reverseext":{"id":"ex26_ball_reverseext","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"ex26_ball_reverseext","viewOnly":true,"measurementType":"BODYWEIGHT_REPS","loadMode":"none","sideMode":"none"},"art":{"appId":"ex26_ball_reverseext","atlasId":"ex26_ball_reverseext","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"ca6b473d37c755f9750736ef60c6df45f3d23ea0fd175707183ce0ee8d190960","thumb":"/expansion-atlas/ex26_ball_reverseext-original-256.webp","detail":"/expansion-atlas/ex26_ball_reverseext-original-960.webp","inkThumb":"/expansion-atlas/ex26_ball_reverseext-ink-256.webp","inkDetail":"/expansion-atlas/ex26_ball_reverseext-ink-960.webp","fillThumb":"/expansion-atlas/ex26_ball_reverseext-fill-256.webp","fillDetail":"/expansion-atlas/ex26_ball_reverseext-fill-960.webp"},"sourceSha256":"ca6b473d37c755f9750736ef60c6df45f3d23ea0fd175707183ce0ee8d190960","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"b00daa59ad28567d":{"fields":{"id":"ex26_ball_reverseext","cz":"Zanožení obou nohou s pánví na míči","en":"Stability-Ball Reverse Extension","pat":"ohyb","eq":["fitball"],"measurementType":"BODYWEIGHT_REPS","defaultRestSec":120,"unilateral":false,"sideMode":"none","focus":["Zvedni obě nohy do prodloužení trupu a pomalu je spusť.","Lift both legs until they align with the trunk, then lower slowly."],"startPosition":["Na neklouzavé podlaze lehni břichem na míč. Podepři pánev, dlaně pevně opři o zem a před zvednutím nohou ověř, že ovládáš pohyb míče.","Lie face down over the ball on a non-slip floor. Support the pelvis, plant the palms firmly and check control of the ball before lifting the legs."],"execution":["Zvedni obě nohy do prodloužení trupu a pomalu je spusť.","Lift both legs until they align with the trunk, then lower slowly."],"watchFor":["Nohy nezvedej nad linii trupu a nehoupej míčem.","Do not lift above trunk level or rock the ball for momentum."]},"progression":["Lehčí: menší rozsah nebo více pokrčená kolena. Jedna zvedaná noha mění i nároky na kontrolu rotace. Pro větší náročnost můžeš přidat krátkou pauzu při stejné stabilní poloze.","Easier: a smaller range or more knee bend. Lifting one leg also changes the demand for rotational control. A brief pause can increase demand while maintaining the same stable position."]}}},"pikefold":{"id":"pikefold","segment":"R","edits":{},"taxonomy":{},"policy":{"id":"pikefold","viewOnly":true,"measurementType":"DURATION","loadMode":"none","sideMode":"none","familyOverride":"hip_flexion_mobility"},"art":{"appId":"pikefold","atlasId":"pikefold","unified":true,"primary":{"width":960,"height":960,"sourceSha256":"99af6abfea7fd2a0169e3939e977c37b9a025daecd8f418ae1fd8d590862ab2c","thumb":"/unified-atlas/pikefold-8dd49f2fe48082d5-thumb.webp","detail":"/unified-atlas/pikefold-e6d10ce16f872d74-detail.webp","inkThumb":"/unified-atlas/pikefold-5756b77eb1887b0f-inkThumb.webp","inkDetail":"/unified-atlas/pikefold-2a033672d7d6ed85-inkDetail.webp","fillThumb":"/unified-atlas/pikefold-d96d2b738a365a65-fillThumb.webp","fillDetail":"/unified-atlas/pikefold-bd48f559587395ed-fillDetail.webp"},"sourceSha256":"99af6abfea7fd2a0169e3939e977c37b9a025daecd8f418ae1fd8d590862ab2c","contourOnly":true,"darkOutline":true},"deliveryProfiles":{"b6d96d6b2f32e01a":{"fields":{"id":"pikefold","cz":"Pike fold · Předklon","en":"Pike Fold","pat":"mobilita","eq":["telo"],"measurementType":"DURATION","defaultRestSec":15,"unilateral":false,"sideMode":"none","focus":["Klidně dýchej a zvol mírný, snesitelný tah v zadní straně nohou.","Breathe calmly and choose a mild, tolerable stretch behind the legs."],"startPosition":["Stůj pohodlně, kolena můžeš lehce pokrčit. Nech prostor pro volný předklon.","Stand comfortably; the knees may bend slightly. Leave room for an easy forward fold."],"execution":["Sklápěj se z kyčlí, hrudník ke stehnům, ruce k zemi. Dýchej a nech tíhu táhnout.","Hinge from the hips, chest to the thighs, hands toward the ground. Breathe and let gravity pull."],"watchFor":["Netlač do bolesti ani do maximálního dosahu. Dlaně nemusejí na podlahu a přirozené zakulacení trupu samo o sobě neznehodnocuje výdrž.","Do not force pain or maximum reach. The palms need not reach the floor, and natural trunk rounding does not itself invalidate the hold."]},"progression":["Měň pohodlný rozsah nebo délku výdrže. Zatížený předklon ani dotyk země nejsou povinným cílem.","Adjust comfortable range or hold duration. A loaded fold or floor contact is not a required goal."]}}}};
